export const kuranSearch: { slug: string; chunks: { text: string; headingId: string; headingText: string }[] }[] = [{"slug":"Ajet-o-kamenovanju-i-derogacija-ucenja","chunks":[{"text":"Derogacija je postojala još u vreme Poslanika ﷺ i nije uvedena nakon njega. Ajet o kamenovanju prenelo je više ashaba pouzdanim lancima, a njegov propis ostao je na snazi uz saglasnost pravnika. Omer ga nije uneo u mushaf sa obrazloženjem: da se ne bi reklo da je Omer nešto dodao Kur'anu. Uz to, izraz starac i starica mogao bi navesti na pogrešno razumevanje uslova bračnog stanja.","headingId":"","headingText":""},{"text":"Šta je derogacija Derogacija je postojala još u vreme Poslanika ﷺ i nije uvedena nakon njega. Ona je imala zakonodavnu svrhu, a najbolji primer je postepena zabrana opojnog pića: 1. En Nahl 16:67 razdvaja opojno piće od lepe opskrbe. 2. El Bekara 2:219 navodi štetu, ali još bez zabrane. 3. En Nisa 4:43 zabranjuje pristupanje namazu u pijanom stanju. 4. El Maida 5:90 donosi potpunu zabranu. Omer ibn el Hattab je više puta molio Allaha da razjasni propis o opojnom piću, sve dok nije objavljen konačni ajet. Taj primer pokazuje da postupnost i menjanje propisa nisu naknadna ljudska domišljanja, nego način na koji je zakonodavstvo objavljivano još za Poslanikovog ﷺ života.","headingId":"sta-je-derogacija","headingText":"Šta je derogacija"},{"text":"Ajet o kamenovanju Više ashaba prenelo je ajet o kamenovanju pouzdanim lancima. Omer ibn el Hattab naveo je: „Učili smo u njemu ajet o kamenovanju: starac i starica, ako počine blud, kamenujte ih oboje.\" Abdullah ibn Omer izvestio je o Poslanikovoj ﷺ primeni tog propisa kada su Jevreji doveli slučaj bluda. Abdullah ibn Abbas naveo je: „Učio sam ga: ako starac i starica počine blud, kamenujte ih oboje.\" Omer je izrazio bojazan: „Pobojao sam se da će proći dugo vremena, pa da će ljudi reći: ne nalazim kamenovanje u Allahovoj Knjizi.\" Među pravnicima nema razilaženja o obaveznosti kamenovanja oženjenog bludnika, bilo muškarca ili žene.","headingId":"ajet-o-kamenovanju","headingText":"Ajet o kamenovanju"},{"text":"Zašto je učenje derogirano Omer nije uneo ajet o kamenovanju u mushaf, sa obrazloženjem: Da se ne bi reklo: Omer je dodao Kur'anu, zapisao bih ajet o kamenovanju. Ta izjava je vrlo rečita. Čovek koji je bio halifa i koji je taj tekst i sam učio, ipak ga nije uneo, jer nije imao ovlašćenje da u mushaf unosi ono što u njemu nije bilo utvrđeno propisanim putem. To je isti onaj metod dva svedoka i zapisa pred Poslanikom ﷺ. Uz to, izraz starac i starica mogao bi navesti na pogrešno razumevanje u pogledu uslova bračnog stanja. Kamenovanje se, naime, primenjuje samo na one koji su bili u braku, a ne na sve starije osobe. Uklanjanje učenja uz zadržavanje propisa sprečilo","headingId":"zasto-je-ucenje-derogirano","headingText":"Zašto je učenje derogirano"},{"text":"je pogrešnu primenu.","headingId":"zasto-je-ucenje-derogirano","headingText":"Zašto je učenje derogirano"},{"text":"Kamenovanje u ranijim objavama Ponovljeni zakon 13:10 Zaspi ga kamenjem da pogine. Ponovljeni zakon 22:21 24 Neka je zaspu kamenjem da pogine. Jovan 8:5 A Mojsije nam u zakonu zapovedi da takve kamenjem ubijamo. U tom odlomku Isa ne poriče važenje zakona, nego se umeće na osnovu postupka.","headingId":"kamenovanje-u-ranijim-objavama","headingText":"Kamenovanje u ranijim objavama"},{"text":"Značenje pojma Redžm znači bacanje kamenja, a u islamskoj terminologiji označava kamenovanje oženjenog bludnika kamenjem do smrti.","headingId":"znacenje-pojma","headingText":"Značenje pojma"},{"text":"Zaključak Derogacija učenja ajeta o kamenovanju, uz zadržavanje njegovog propisa, dokumentovan je i višestruko prenesen slučaj onoga što se naziva nesh et tilave duned hukm. Ashabi su ga prepoznali, o njemu postoji saglasnost, a primenjivan je neprekidno od Poslanikovog ﷺ vremena.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Arapske-tacke-i-znaci","chunks":[{"text":"Natpisi pokazuju da su Arapi poznavali tačke i pre poslanstva i da su one bile deo njihovog jezičkog nasleđa. Natpis sa Džebel Ramma, iz razdoblja od 328. do 350. godine, sadrži tačkovana slova, a papirus iz Ihnasje iz 22. godine po Hidžri pokazuje raširenu upotrebu tačaka već u Omerovo doba. Treba, uz to, razlikovati dve vrste tačkovanja: ono za razlikovanje slova i ono za vokalizaciju.","headingId":"","headingText":""},{"text":"Natpisi pre poslanstva 1. Rakušin natpis. Pronađen u Medain Salihu, iz 267. godine, na grobu žene po imenu Rakuš. Učenjaci ga svrstavaju i u arapske i u nabatejske natpise, ali arapski jezik preovlađuje. Tekst se mogao razumeti jedino ako se reči smeste u arapski okvir. 2. Natpis sa Džebel Ramma. Iz razdoblja od 328. do 350. godine. Tekst glasi: „Hram Lat, velika zahvalnost delatnom čoveku koji je stekao svoj imetak.\" Slova ja, džim i nun u tom natpisu su tačkovana. 3. Natpis iz Sakake. Neobična mešavina džezm pisma i nabatejskih slova, pronađena u Sakaki u Hidžazu. Natpis pokazuje tačke uz arapska džezm slova ba, ta i nun. Zekerijja Muhammed navodi da je natpis mešavina nabatejskih i arapskih slova i da","headingId":"natpisi-pre-poslanstva","headingText":"Natpisi pre poslanstva"},{"text":"reči u njemu ukazuju na razdoblje razvoja arapskog pisanja. Tekst glasi: „Napisala Džadilat za Amn, oslobođena.\" Zekerijja primećuje da je natpis najverovatnije napisan barem decenijama pre poslanstva, ako ne i mnogo ranije. Zekerijja Muhammed, o natpisu iz Sakake. 4. Natpis Abd Šemsa ibn el Mugire. Muhammed Abdullah el Harbi objavio je predislamski natpis sa tačkama: „U Tvoje ime, Allahu, ja, Abd Šems ibn el Mugira, tražim oprost od svoga Gospodara.\" Muhammed Abdullah el Harbi. 5. Natpis iz crkve u Petri. Iz razdoblja između petog i šestog veka, u kojem je reč napisana tačkovanim slovima u džezm pismu, i pripisuje se arapskom pisaru. Tačkovanje je bilo poznato i kod arapskih Nabatejaca, što potvrđuju njihovi natpisi.","headingId":"natpisi-pre-poslanstva","headingText":"Natpisi pre poslanstva"},{"text":"Tačkovanje pre osmanskog mushafa Tačkovanje slova nije nastalo nakon zapisivanja Kur'ana, kako neki pretpostavljaju. Hafni Nasif naveo je da izum idžama prethodi vremenu Abdul Melika ibn Mervana i da je tačkovanje postojalo pre poslanstva. Hafni Nasif. Tri dokaza to potkrepljuju: 1. Od Ibn Abbasa se prenosi da je Amir ibn Džedera bio taj koji je uspostavio idžam. 2. Oblici sličnih slova, poput ba, ta i sa, upućuju na namernu zamisao. 3. Pronađeni su drevni zapisi, nastali pre hilafeta Abdul Melika, koji sadrže tačkovanje pojedinih slova.","headingId":"tackovanje-pre-osmanskog-mushafa","headingText":"Tačkovanje pre osmanskog mushafa"},{"text":"Zašto u osmanskom mushafu nema znakova Numerisanje sura, ajeta i delova, kao i znaci, postojali su u kur'anskim rukopisima još od poslaničkog doba. Odsustvo znakova u osmanskim mushafima objašnjava se time što su sami prepisivači uklonili znake i podele iz teksta nakon što je bio označen, sa ciljem da se objedine sva učenja i da se u jednom tekstu omogući više izgovora reči. To je važna tačka. Odsustvo znakova nije bilo posledica neznanja ili nerazvijenog pisma, nego namerna odluka koja je jednom rasmu omogućila da nosi više dopuštenih učenja.","headingId":"zasto-u-osmanskom-mushafu-nema-znakova","headingText":"Zašto u osmanskom mushafu nema znakova"},{"text":"Papirusi i natpisi nakon poslanstva 1. Papirus iz Ihnasje, 22. godina po Hidžri. Pokazuje da je upotreba tačaka bila raširena među Arapima u Omerovom hilafetu. Tekst glasi: „U ime Allaha, Milostivog, Samilosnog, ovo je ono što su Abdullah ibn Džabir i njegovi drugovi uzeli od šargarepe iz Ahnasa.\" 2. Papirus P. Berol. 15002, 22. godina po Hidžri. Arapsko grčki papirus koji sadrži tačke i predstavlja trgovinski ugovor. Datovanje je veoma rano, jer potiče iz druge godine ulaska Arapa u Egipat. 3. Zuhejrov natpis, 24. godina po Hidžri. Tekst glasi: „U ime Allaha, ja, Zuhejr, napisah u vreme Omerove smrti, dvadeset četvrte godine.\"","headingId":"papirusi-i-natpisi-nakon-poslanstva","headingText":"Papirusi i natpisi nakon poslanstva"},{"text":"Sanski palimpsest Sanski rukopis pokazao je da upotreba tačaka nije kasnila do druge polovine prvog veka, nego da je postojala već u Omerovom hilafetu. Istraživači Mohsen Godarzi i Behnam Sadegi utvrdili su da donji tekst rukopisa potiče iz vremena ubrzo nakon Poslanikove ﷺ smrti, možda petnaest godina kasnije, a najkasnije iz Alijinog hilafeta. Mohsen Goudarzi i Behnam Sadeghi, o sanskom palimpsestu. Primeri tačkovanja u njemu: 1. kalilen, Et Tevba 9, tačka na kafu 2. fasikun, Et Tevba 8, tačka na nunu 3. jekfuru, El Bekara 90, tačka na fau 4. jerkubun, Et Tevba 10, tačka na kafu Tačkovanje, čak i u tim tekstovima, nije bilo obavezno u svim slučajevima. Reč je, dakle, o poznatoj i korišćenoj mogućnosti, a ne o","headingId":"sanski-palimpsest","headingText":"Sanski palimpsest"},{"text":"dosledno sprovedenom sistemu, sve do kasnijeg ustaljivanja. Kalkašendi je naveo: „Malo je verovatno da su slova, uprkos svojim sličnim oblicima, bila bez tačaka sve do vremena kada je Kur'an tačkovan.\" El Kalkašendi.","headingId":"sanski-palimpsest","headingText":"Sanski palimpsest"},{"text":"Dve vrste tačkovanja Postoji mogućnost zabune u pojmu tačkovanja koji se spominje u istorijskim predajama, jer je tačkovanje bilo dvojako: tačkovanje radi vokalizacije i tačkovanje radi razlikovanja slova. Tačkovanje radi vokalizacije pripisuje se Ebul Esvedu ed Duelijju, umrlom 69. godine po Hidžri, odnosno 688. godine, a njegova svrha bila je uređivanje izgovora u pogledu fethe, damme i kesre, radi izbegavanja jezičkih grešaka. To tačkovanje nije dugo trajalo, jer ga je Halil ibn Ahmed zamenio vokalskim znacima izvedenim iz oblika elifa, jaa i vava, nakon što je nastala zabuna između tačaka za vokalizaciju i tačaka za razlikovanje sličnih slova. Tačkovanje, dakle, ni u jednom od svoja dva oblika nije izum nearapa, kako neki tvrde, nego je drevno arapsko nasleđe.","headingId":"dve-vrste-tackovanja","headingText":"Dve vrste tačkovanja"}]},{"slug":"Da-li-je-bismila-deo-Kurana","chunks":[{"text":"Razilaženje među pravnim školama tiče se isključivo toga da li se bismila broji kao ajet pojedine sure i da li se u namazu uči naglas. Ono se ne tiče njenog prisustva u mushafu. Bismila je zapisana u svim osmanskim primercima i nijedna škola nikada nije tražila da se odatle ukloni. Razlika u brojanju posledica je razlike među priznatim kiraetima, a ne nesigurnosti u tekst.","headingId":"","headingText":""},{"text":"Sadržaj primedbi Iznose se tri odvojene primedbe: 1. Da razilaženje o bismili pokazuje nesigurnost u kur'anski tekst. 2. Da izostanak bismile na početku sure Et Tevba pokazuje da je nešto izgubljeno. 3. Da je sama bismila preuzeta iz sirijske trinitarne formule. Svaka od njih obrađuje se odvojeno.","headingId":"sadrzaj-primedbi","headingText":"Sadržaj primedbi"},{"text":"Prvi deo hadiski dokazi Predaja od Umm Seleme, radijallahu anha, utvrđuje da je bismila ajet sure El Fatiha. Sunen Ebu Davud; ocenio Albani kao verodostojnu. Predaja od Ebu Hurejre, radijallahu anhu, potvrđuje isto. Sahihul džami'; ocenio Albani kao verodostojnu. Predaja od Ibn Abbasa, radijallahu anhuma, ukazuje na to da je bismila razdvajala sure, i to tako što Poslanik ﷺ nije znao gde se sura završava dok mu ne bi bila objavljena bismila. Sunen Ebu Davud; ocenio Albani kao verodostojnu. Ova poslednja predaja važna je i sama za sebe. Ona pokazuje da bismila nije bila pisarska ili uređivačka odluka nego objavljeni znak granice između sura. To je suprotno od pretpostavke da su granice sura naknadno određene. Predaje o tihom učenju prenose","headingId":"prvi-deo-hadiski-dokazi","headingText":"Prvi deo - hadiski dokazi"},{"text":"se od Enesa ibn Malika, radijallahu anhu. Sunen Nesai; Sunen Tirmizi, koji je predaju ocenio kao hasen sahih; ocenio i Albani.","headingId":"prvi-deo-hadiski-dokazi","headingText":"Prvi deo - hadiski dokazi"},{"text":"Drugi deo zašto Et Tevba nema bismilu Predaja koja se pripisuje Osmanu ibn Affanu, radijallahu anhu, objašnjava da su El Enfal i Et Tevba objavljivane u bliskom razdoblju, da Poslanik ﷺ nije izričito pojasnio da su odvojene sure, pa su zapisane bez bismile između njih. Musned Ahmed; Sunen Tirmizi; Sunen Ebu Davud. Albani je lanac ocenio kao slab, a primedbu je izneo i Šuajb el Arnaut. Lanac te predaje jeste slab i to treba reći otvoreno. Međutim, glavni argument ne visi o njoj. On počiva na tome da je Poslanik ﷺ Kur'an svake godine ponavljao pred Džibrilom, a u godini svoje smrti dva puta, i da tom prilikom nije bilo nikakve ispravke. Prećutno odobrenje u tom kontekstu ima težinu potvrde.","headingId":"drugi-deo-zasto-et-tevba-nema-bismilu","headingText":"Drugi deo - zašto Et-Tevba nema bismilu"},{"text":"Treći deo stavovi učenjaka Šenkiti navodi da bismila jeste ajet u pojedinim kiraetima, a u drugima nije, i da je razilaženje među učenjacima o tome očekivano. Eš Šenkiti, Muzekkire fi usulil fikh, str. 66. Sujuti navodi da je bismila objavljena sa surom u nekim od sedam harfova. Es Sujuti, El Itkan fi ulumil Kur'an, tom 1, str. 239. Ibn Tejmijje smatra da je bismila kur'anski tekst, zapisan u svim osmanskim mushafima, ali da nije tehnički deo sure koja joj prethodi ili koja za njom sledi, nego samostalan ajet koji sure razdvaja. Ibn Tejmijje. Nevevi navodi da je ona potpun ajet sa početka sure El Fatiha, bez spora. En Nevevi, El Medžmu' šerhul Muhezzeb, tom 3, str. 290. Ibn el Džezeri","headingId":"treci-deo-stavovi-ucenjaka","headingText":"Treći deo - stavovi učenjaka"},{"text":"primenjuje isto načelo kao i na ostale razlike među deset kiraeta. Ibn el Džezeri, En Nešr fil kiraatil ašr, tom 1, str. 21.","headingId":"treci-deo-stavovi-ucenjaka","headingText":"Treći deo - stavovi učenjaka"},{"text":"Načelo harfova Isti obrazac vidi se i drugde. Reč huve u suri El Hadid prisutna je u pet kiraeta, kod Ibn Kesira, Ebu Amra, Asima, Hamze i Kisaija, a odsutna kod Nafija i Ibn Amira. Oba oblika su Kur'an. Bismila prati isto načelo.","headingId":"nacelo-harfova","headingText":"Načelo harfova"},{"text":"Četvrti deo četiri pravne škole | Škola | Da li je ajet El Fatihe | Da li je ajet ostalih sura | Učenje u namazu | | | | | | | Hanefijska | Ne | Samostalan ajet koji razdvaja sure | Tiho | | Malikijska | Ne | Ne, osim u suri En Neml | Ne uči se | | Šafijska | Da | Da | Naglas u glasnim namazima | | Hanbelijska | Da | Da | Tiho | Šafijski stav dele i Ata, Tavus, Mudžahid i Seid ibn Džubejr. Treba pažljivo pogledati šta se u ovoj tabeli zapravo razilazi. Razilaženje je o brojanju i o načinu učenja u namazu. Nijedna škola ne osporava da je bismila zapisana","headingId":"cetvrti-deo-cetiri-pravne-skole","headingText":"Četvrti deo - četiri pravne škole"},{"text":"u mushafu, niti da je En Neml 27:30 kur'anski tekst. Prigovor koji iz ove tabele izvodi nesigurnost teksta meša pravno pitanje sa tekstualnim.","headingId":"cetvrti-deo-cetiri-pravne-skole","headingText":"Četvrti deo - četiri pravne škole"},{"text":"Peti deo naglas ili tiho U prilog tihom učenju navode se: Predaja od Aiše, radijallahu anha, da je Poslanik ﷺ namaz započinjao tekbirom i učenjem el hamdu lillahi rabbil alemin . Predaja od Ebu Hurejre, radijallahu anhu, o Božijem odgovoru na učenje El Fatihe, koja takođe počinje od el hamdu lillahi rabbil alemin . Darekutni je zaključio da su svi izveštaji o učenju naglas slabi. Ed Darekutni. Ibn Kajjim el Dževzijje smatra da je Poslanik ﷺ ponekad učio naglas, ali češće tiho, i ukazuje na to da učenje naglas u svih pet dnevnih namaza ne bi moglo ostati nezapaženo među ashabima. Ibn Kajjim el Dževzijje.","headingId":"peti-deo-naglas-ili-tiho","headingText":"Peti deo - naglas ili tiho"},{"text":"Šesti deo šijski stav El Hilli i imamijski učenjaci smatraju da sure Ed Duha i El Inširah čine jednu suru, kao i sure El Fil i Kurejš. Šerai'ul islam, tom 1, str. 66. Es Saduk potvrđuje isto uparivanje. Es Saduk, El I'tikadat, str. 84. Allame el Hilli, međutim, priznaje da su ashabi bismilu utvrdili na počecima sura u zapisu mushafa. El Hilli, Nihajetul ahkam, tom 1, str. 462; Tezkiretul fukaha, tom 3, str. 133. Muhammed Taki el Medžlisi prenosi da je učenje bismile naglas u svim namazima sunnet. Revdatul muttekin, tom 2, str. 303. Ovde je zanimljivo da šijski izvori koji se navode kao dokaz razilaženja istovremeno potvrđuju prisustvo bismile u zapisu mushafa. To je ustupak koji ruši onu upotrebu","headingId":"sesti-deo-sijski-stav","headingText":"Šesti deo - šijski stav"},{"text":"za koju se ti izvori navode.","headingId":"sesti-deo-sijski-stav","headingText":"Šesti deo - šijski stav"},{"text":"Sedmi deo tvrdnja o hanbelijskom iskrivljenju Iznosi se tvrdnja da hanbelijski stav znači da je bismila dodata tekstu. Odgovor ide u nekoliko koraka: 1. Razilaženje se tiče brojanja, ne prisustva. Nijedan hanbelijski učenjak nije tražio uklanjanje bismile iz mushafa. 2. Ahmed ibn Hanbel bio je hadiski autoritet prvog reda. Zehebi beleži razmere njegovog pamćenja hadisa. Ez Zehebi. 3. Hanbelijski stav o tihom učenju izveden je iz verodostojne predaje od Enesa ibn Malika kod Tirmizija. 4. Malikijska i hanefijska škola takođe ne broje bismilu kao ajet ostalih sura osim En Nemla, pa bi ista optužba morala pogoditi i njih. 5. Oštre izjave u pravnim raspravama treba čitati u kontekstu rasprave , a ne kao doktrinarne tvrdnje o kur'anskom tekstu. Postoji saglasnost","headingId":"sedmi-deo-tvrdnja-o-hanbelijskom-iskrivljenju","headingText":"Sedmi deo - tvrdnja o hanbelijskom iskrivljenju"},{"text":"da onaj ko bismilu smatra ajetom, kao i onaj ko je ne smatra, ostaje musliman, upravo zbog dokumentovanog razilaženja. Izuzetak je poricanje bismile u suri En Neml, jer se ona tamo nalazi unutar sure, u Sulejmanovom pismu, i o tome nema spora. Sura En Neml 27:30 Ono je od Sulejmana i glasi: U ime Allaha, Milostivog, Samilosnog!","headingId":"sedmi-deo-tvrdnja-o-hanbelijskom-iskrivljenju","headingText":"Sedmi deo - tvrdnja o hanbelijskom iskrivljenju"},{"text":"Osmi deo tvrdnja o sirijskom poreklu Iznosi se tvrdnja da je bismila preuzeta iz sirijske formule i da u sebi krije trojstvo, pri čemu se rahmanu povezuje sa utrobom i utelovljenjem, a rahimu sa Svetim duhom.","headingId":"osmi-deo-tvrdnja-o-sirijskom-poreklu","headingText":"Osmi deo - tvrdnja o sirijskom poreklu"},{"text":"Zajednički semitski koren Koren r h m zajednički je arapskom, hebrejskom i sirijskom aramejskom, jer su to srodni semitski jezici, i nosi značenja utrobe, milosti i samilosti. Razijevo zapažanje o hebrejskom srodniku jeste jezička činjenica, a ne priznanje pozajmljivanja. Zaključivanje po kojem zajednički koren znači pozajmljivanje pogrešno je u samom postupku. Ako bi ono važilo, onda bi svaka reč zajednička dvama srodnim jezicima bila dokaz da je jedan jezik uzeo od drugog, što je besmisleno.","headingId":"zajednicki-semitski-koren","headingText":"Zajednički semitski koren"},{"text":"Razlika između Rahman i Rahim Er Rahman označava sveobuhvatnu milost koja na ovom svetu obuhvata sva stvorenja, i vernike i nevernike. Er Rahim označava posebnu milost prema vernicima na ahiretu. Ta razlika utvrđena je u tefsirskoj tradiciji i nije nikakvo tajanstveno ponavljanje.","headingId":"razlika-izmedju-rahman-i-rahim","headingText":"Razlika između Rahman i Rahim"},{"text":"Događaj na Hudejbiji Ovo je tačka koja tvrdnju o pozajmljivanju obara u potpunosti. Prilikom sklapanja ugovora na Hudejbiji, Suhejl ibn Amr usprotivio se zapisivanju bismillahir rahmanir rahim i zatražio da se umesto toga napiše bismike Allahumme , jer Kurejšije nisu poznavale naziv er Rahman . Da je ta formula postojala u predislamskoj arapskoj ili sirijskoj upotrebi, prigovor Suhejla ibn Amra ne bi imao smisla. On se usprotivio upravo zato što mu je naziv bio nepoznat. Poslanik ﷺ je pristao na kurejšijsku verziju samo u tekstu ugovora, dok objava nije promenjena.","headingId":"dogadjaj-na-hudejbiji","headingText":"Događaj na Hudejbiji"},{"text":"Nema dokumentovane trinitarne formule Nijedan sirijski doktrinarni tekst ne definiše rahmanu kao drugu osobu trojstva. Reč je o naknadnom bogoslovskom očitavanju jezičkog oblika, bez tekstualne potpore.","headingId":"nema-dokumentovane-trinitarne-formule","headingText":"Nema dokumentovane trinitarne formule"},{"text":"Koptski patrijarsi Koptski patrijarsi uneli su islamsku bismilu u svoju prepisku sa sirijskim antiohijcima. To pokazuje priznanje njenog verskog dostojanstva, a ne dokazuje izvođenje.","headingId":"koptski-patrijarsi","headingText":"Koptski patrijarsi"},{"text":"Zaključak 1. Bismila je ajet sure El Fatiha prema verodostojnim predajama od Umm Seleme, Ebu Hurejre i Ibn Abbasa. 2. Ona ima i samostalnu ulogu znaka granice između sura, što je Poslaniku ﷺ bilo objavljivano. 3. Izostanak na početku Et Tevbe potvrđen je prećutnim odobrenjem tokom godišnjeg ponavljanja pred Džibrilom. 4. Razilaženje četiri pravne škole tiče se brojanja ajeta i načina učenja, a ne prisustva teksta. 5. Tvrdnja o sirijskom poreklu pada na Suhejlovom prigovoru na Hudejbiji.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Da-li-je-bismilla-sirijska","chunks":[{"text":"Izostavljanje elifa u često korišćenim izrazima priznata je odlika arapskog pravopisa, a ne pozajmica iz sirijskog. To pokazuje i sam Kur'an: u suri El Fatiha ta reč se piše bez elifa, a u suri El Alek sa elifom. Uz to, isti izostavljeni oblik javlja se i u sirijskim hrišćanskim bogoslužbenim rukopisima.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Tvrdi se da izraz bismillah, pisan bez elifa, potiče iz sirijskog oblika bišm, a ne iz arapskog.","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Prvo to je odlika arapskog pravopisa Izostavljanje elifa u često korišćenim izrazima priznata je odlika arapskog pravopisa, a ne pozajmica iz sirijskog. Najbolji dokaz nalazi se u samom Kur'anu. Sura El Fatiha 1:1 U ime Allaha, Milostivog, Samilosnog. Sura El Alek 96:1 Čitaj, u ime Gospodara tvoga, koji stvara. U prvom slučaju reč je zapisana bez elifa, a u drugom sa elifom. Ta unutrašnja razlika sama obara primedbu. Da je izostavljanje elifa bilo posledica pisanja sirijskim pismom, isti oblik bi se javljao dosledno kroz čitav tekst. Umesto toga, razlika prati učestalost izraza, upravo onako kako to arapski pravopis i nalaže. Isto važi i za reč salat, koja se u klasičnim rukopisima piše na dva načina.","headingId":"prvo-to-je-odlika-arapskog-pravopisa","headingText":"Prvo - to je odlika arapskog pravopisa"},{"text":"Drugo sami sirijski rukopisi to ne potvrđuju Više sirijskih hrišćanskih bogoslužbenih rukopisa koristi isti taj izostavljeni oblik izraza bismillah. Da je taj oblik isključivo sirijski, očekivali bismo da sirijski hrišćani svoje pismo razlikuju od arapskog Kur'ana time što bi koristili drugačiji pravopis. To poklapanje pokazuje ili zajedničko semitsko poreklo ili prenošenje iz arapskog u sirijski.","headingId":"drugo-sami-sirijski-rukopisi-to-ne-potvrdjuju","headingText":"Drugo - sami sirijski rukopisi to ne potvrđuju"},{"text":"Treće nedoslednost same primedbe Sirijski hrišćanski crkveni izvori protivreče onima koji tvrde da je kur'anski pravopis stran, jer i sami koriste isti oblik.","headingId":"trece-nedoslednost-same-primedbe","headingText":"Treće - nedoslednost same primedbe"}]},{"slug":"Da-li-je-Hafs-ibn-Sulejman-nepouzdan","chunks":[{"text":"Ocena prenosioca u hadisu i njegova ocena u kiraetu dve su odvojene stvari, sa odvojenim merilima. Zehebi za Hafsa istovremeno navodi obe: pouzdan i precizan u učenju, slab u hadisu. Uz to, Asimovo učenje nije preneo samo Hafs, nego više desetina učača, pa cela stvar i ne visi o jednom čoveku.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Iznosi se tvrdnja da je učenje po kojem najveći deo muslimanskog sveta danas uči Kur'an, dakle Hafsovo predanje Asimovog kiraeta, nepouzdano, jer su hadiski kritičari samog Hafsa ibn Sulejmana ocenili kao slabog.","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Prvo Asimovo učenje nije preneo jedan čovek Ibn el Džezeri nabraja preko dvadeset i tri imena učača koji su prenosili Asimovo učenje, i navodi da su od njega prenosili i mnogi drugi. Ibn el Džezeri, En Nešr fil kiraatil ašr. Ovo je tačka na kojoj primedba pada i pre nego što se uđe u ocenu samog Hafsa. Ako isto učenje nezavisno prenosi više desetina ljudi, onda se ono ne oslanja na pouzdanost bilo kog pojedinca. Rasprava o jednom prenosiocu bila bi presudna samo kada bi on bio jedini put do teksta, a on to nije.","headingId":"prvo-asimovo-ucenje-nije-preneo-jedan-covek","headingText":"Prvo - Asimovo učenje nije preneo jedan čovek"},{"text":"Drugo kiraeti se prenose masovnim prenosom Ibn es Subki potvrdio je da deset kiraeta ispunjavaju uslove masovnog prenosa i da su poznati u veri po nužnosti. Abdul Vehhab ibn es Subki. Masovan prenos znači da toliki broj ljudi prenosi isto da je njihovo slaganje u grešci nemoguće. U takvom prenosu ocena pojedinačnog lanca postaje sporedna.","headingId":"drugo-kiraeti-se-prenose-masovnim-prenosom","headingText":"Drugo - kiraeti se prenose masovnim prenosom"},{"text":"Treće slab u hadisu, imam u kiraetu Zehebi na više mesta navodi obe ocene zajedno, bez ikakvog osećaja protivrečnosti: Što se tiče učenja, on je pouzdan, utvrđen i precizan, za razliku od njegovog stanja u hadisu. Izvor: Zehebi. Šemsudin ez Zehebi. Zehebi ga na drugim mestima naziva autoritetom u učenju, slabim u hadisu, i imamom u učenju, slabim u hadisu. Ibn Hadžer navodi da je njegov hadis napušten, uprkos njegovom prvenstvu u učenju. Ibn Hadžer el Askalani. Hejsemi navodi da ga je Ahmed smatrao pouzdanim, a da su ga imami oslabili u hadisu. El Hejsemi. Munavi navodi da je Hafs ibn Sulejman pouzdan u učenju, ali ne i u hadisu. El Munavi.","headingId":"trece-slab-u-hadisu-imam-u-kiraetu","headingText":"Treće - slab u hadisu, imam u kiraetu"},{"text":"Četvrto zašto to nije protivrečnost Razlika između dve discipline je stvarna i tehnička. Hadis iziskuje pamćenje mnoštva različitih tekstova, sa različitim lancima, koji se međusobno preklapaju i mešaju. Prenosilac koji tu pogreši ocenjuje se kao slab u dabtu , dakle u preciznosti. Kiraet je jedan jedini tekst, koji se uči celog života, pred učiteljem, iz dana u dan, i koji se proverava svakim ponavljanjem. Neko može biti krajnje precizan u tom jednom tekstu, a nepouzdan u prenošenju hiljada hadisa. Presudno je i to da se kritika Hafsa odnosi na dabt, dakle na preciznost, a ne na adalu, dakle na moralnu ispravnost. Njegova slabost pripisuje se tome što se posvetio Kur'anu, a ne bavljenju hadisom, a ne nekakvoj nepoštenosti.","headingId":"cetvrto-zasto-to-nije-protivrecnost","headingText":"Četvrto - zašto to nije protivrečnost"},{"text":"Peto optužba za laž","headingId":"peto-optuzba-za-laz","headingText":"Peto - optužba za laž"},{"text":"Izjava Ibn Haraša Ibn Adijj je Ibn Haraša kritikovao, ukazujući na to da je izmišljao spojeve u lancima. Ibn Adijj. Zehebi ga je označio najtežim mogućim ocenama. Optužba za laž, dakle, dolazi od čoveka koji je i sam ocenjen kao nepouzdan i sklon izmišljanju spojeva u lancima. Ta optužba pada već na svom izvoru.","headingId":"izjava-ibn-harasa","headingText":"Izjava Ibn Haraša"},{"text":"Predaja koja se pripisuje Jahjau ibn Meinu Lanac te predaje prolazi kroz Ahmeda ibn Muhammeda el Bagdadija, o kome nema podataka. Nasuprot tome, dvojica dokumentovanih učenika Ibn Meina prenose drugačije: Osman ibn Seid ed Darimi prenosi da je njegova ocena glasila samo: nije pouzdan. Ebu Kudama es Serahsi takođe navodi samo: nije pouzdan.","headingId":"predaja-koja-se-pripisuje-jahjau-ibn-meinu","headingText":"Predaja koja se pripisuje Jahjau ibn Meinu"},{"text":"Šesto šta reč lažljivac znači kod ranijih kritičara Ibn Manzur u Lisanul arebu beleži da je reč kezzab u jeziku ranijih učenjaka često označavala onoga ko greši, a ne onoga ko namerno izmišlja. Ibn Manzur, Lisanul areb. Zehebi je to isto načelo primenio na istovetne izjave o drugim prenosiocima. Isto važi i za izraz da je nečiji hadis napušten. On u biografskoj literaturi označava slabost preciznosti, a ne optužbu za izmišljanje.","headingId":"sesto-sta-rec-lazljivac-znaci-kod-ranijih-kriticara","headingText":"Šesto - šta reč lažljivac znači kod ranijih kritičara"},{"text":"Sedmo Hafsova učenja potvrđena su i drugim lancima Pojedinačna Hafsova učenja potvrđena su nezavisno, kroz druge lance, što se vidi iz Šatibijje i drugih dela o kiraetima. To znači da bi, i kada bi se Hafs u potpunosti zanemario, isti tekst ostao potvrđen.","headingId":"sedmo-hafsova-ucenja-potvrdjena-su-i-drugim-lancima","headingText":"Sedmo - Hafsova učenja potvrđena su i drugim lancima"},{"text":"Zaključak Primedba meša dve discipline i dva merila. Hafs jeste oslabljen kao prenosilac hadisa i to niko ne krije, ali je istovremeno priznat kao imam u učenju, a njegovo učenje ne stoji samo na njemu. Ono se prenosi masovno, potvrđeno je drugim lancima i slaže se sa osmanskim mushafom.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Da-li-je-Ibn-Mesud-poricao-el-Felek-i-en-Nas","chunks":[{"text":"Predaja na koju se prigovarači pozivaju slaba je, jer u njenom lancu stoji Ebu Ishak, za kojeg Ibn Hibban navodi da je činio tedlis, a prenosi u obliku an'ane. Uz to, kiraet Asima, preko Zirra ibn Hubejša, ide upravo preko Ibn Mes'uda, a te dve sure u njemu postoje. Kur'an se, uostalom, prenosi mutevatir prenosom, pa saglasnost bilo kojeg pojedinca nije uslov njegove utvrđenosti.","headingId":"","headingText":""},{"text":"Prvo načelno pitanje Kur'an je do nas prenesen neprekinutim, masovnim prenosom, a odsustvo neslaganja nije uslov mutevatir prenosa. Nije uslov Kur'ana da se Abdullah ibn Mes'ud sa njim slaže. Čak i kada bi Kur'an poricao u celini, to ne bi umanjilo njegov mutevatir prenos. Da dve muavvize spadaju u Kur'an, utvrđeno je u Sahihu Muslima, br. 814, i u Sahihu Ibn Hibbana, br. 1842. Sahih Muslim, br. 814; Sahih Ibn Hibban, br. 1842.","headingId":"prvo-nacelno-pitanje","headingText":"Prvo - načelno pitanje"},{"text":"Drugo šta predaja zapravo kaže Predaja iz Musneda imama Ahmeda navodi da Ibn Mes'ud te sure nije uvrstio u svoj lični mushaf. Vidimo iz predaje da Ibn Mes'ud nije čuo Allahovog Poslanika ﷺ da ih uči u namazu, pa ih zato nije zapisao u svoj lični primerak. Smatrao je da su to dve učene zaštite kojima je Poslanik ﷺ tražio zaštitu za Hasana i Husejna. To znači da ih je čuo od Poslanika ﷺ i da nije poricao da su objava. Reč je, dakle, o njegovoj proceni o čemu je tu reč, a ne o poricanju objave. Taberani beleži da je Ibn Mes'ud rekao: „Ne mešajte sa Kur'anom ono što nije od njega, jer su to dve zaštite kojima je","headingId":"drugo-sta-predaja-zapravo-kaze","headingText":"Drugo - šta predaja zapravo kaže"},{"text":"Poslanik ﷺ tražio utočište.\" Et Taberani.","headingId":"drugo-sta-predaja-zapravo-kaze","headingText":"Drugo - šta predaja zapravo kaže"},{"text":"Treće slabost lanca U lancu stoji Ebu Ishak, za kojeg Ibn Hibban navodi da je činio tedlis, iako su ga učenjaci beležili. Predaja onoga ko čini tedlis odbacuje se kada dođe u obliku an'ane, kao što je slučaj u prenosu od Abdur Rahmana. Više učenjaka ga je kritikovalo: 1. Ebu Hatim: „Iskren je, ali se na njega ne oslanja.\" 2. Jahja el Kattan: „Bio je nemaran.\" 3. Ahmed: „Njegovo prenošenje je pomešano.\" Ta predaja ne jača ni Taberanijevim prenosom preko Ebul Džehma el Hanefija, jer on prenosi od Hasana ibn Ibrahima el Kermanija. Slabost lanca te predaje, dakle, jasna je, i na nju se nije dopušteno osloniti.","headingId":"trece-slabost-lanca","headingText":"Treće - slabost lanca"},{"text":"Četvrto nijedan ashab to nije potvrdio Do nas nije stigla nijedna predaja od ashaba koja bi to potvrdila o Abdullahu ibn Mes'udu. Kiraet koji se prenosi od Asima ibn Ebu en Nedžuda el Kufija, od Zirra ibn Hubejša el Esedija, obuhvata Zirrovo učenje od Abdullaha ibn Mes'uda, i Ibn Mes'udovo učenje pred Allahovim Poslanikom ﷺ. Nije preneseno da su dve muavvize izostajale iz učenja Abdullaha ibn Mes'uda. To je odlučujuće. Ako kiraet koji ide upravo preko Ibn Mes'uda te dve sure sadrži, onda tvrdnja da ih je on odbacivao protivreči samom prenosnom lancu koji nosi njegovo ime.","headingId":"cetvrto-nijedan-ashab-to-nije-potvrdio","headingText":"Četvrto - nijedan ashab to nije potvrdio"},{"text":"Zaključak Tvrdnja da je Ibn Mes'ud poricao da dve muavvize spadaju u Kur'an nije utvrđena. Kur'an se prenosi mutevatir prenosom, a kur'anski položaj sura El Felek i En Nas utvrđen je verodostojnim predajama i masovnim učenjem čitavog ummeta.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Da-li-je-Poslanik-mogao-zaboraviti-Kuran","chunks":[{"text":"Izraz u suri El A'la, „i ti nećeš zaboraviti, osim ono što Allah hoće\", vezan je za Allahovu volju, koja se nije ostvarila. Postoje dva tumačenja: da je izuzetak oblikovni, a ne stvarni, ili da se odnosi na derogaciju učenja. Uz to, privremeni izostanak nečega iz pamćenja nije isto što i brisanje iz njega, a Kur'an je bio i zapisan i sačuvan u srcima ashaba, i to u mutevatir broju.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Tvrdi se da je Poslanik ﷺ mogao zaboraviti Kur'an, uz pozivanje na ajete iz sure El A'la. Sura El A'la 87:6 7 Mi ćemo te naučiti da izgovaraš pa ništa nećeš zaboraviti, osim onoga što će Allah hteti.","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Prvo jezičko pitanje Učenjaci česticu la ovde tumače kao negaciju, a ne kao zabranu. Kurtubi navodi: „Prvo je preče, jer izuzetak od zabrane gotovo nikada nije ništa drugo do poznati privremeni izuzetak.\" El Kurtubi. Izuzetak zavisi od Allahove volje, a ona se nije ostvarila. Sura El Kijama 75:17 Mi smo dužni da ga saberemo da bi ga ti čitao.","headingId":"prvo-jezicko-pitanje","headingText":"Prvo - jezičko pitanje"},{"text":"Drugo dva tumačenja izuzetka 1. Oblikovni, a ne stvarni izuzetak. Ferra objašnjava: „Nije hteo da išta zaboravi, i to je poput Njegovih reči: u njemu će večno boraviti, dok je nebesa i Zemlje, osim ako Gospodar tvoj drugačije ne odredi.\" El Ferra. 2. Izuzetak se odnosi na derogaciju učenja. To znači da je Allah hteo da učenje pojedinih ajeta bude podignuto derogacijom, a ne da ih je Poslanik ﷺ trajno zaboravio.","headingId":"drugo-dva-tumacenja-izuzetka","headingText":"Drugo - dva tumačenja izuzetka"},{"text":"Treće odgovor na hadis Hadis koji navode pokazuje da su ajeti bili zapisani u Poslanikovim ﷺ rukama i sačuvani u srcima njegovih ashaba, koji su ih primili od njega i čiji je broj dosegao stepen neprekinutog, masovnog prenosa. Privremeni izostanak nečega iz uma nije isto što i njegovo brisanje iz njega. To je ključna razlika, jer se cela primedba oslanja na poistovećivanje ta dva stanja. Bakillani navodi: „Ako misliš na to da zaboravi onoliko koliko zaboravi znalac koji je Kur'an naučio napamet, to je dopušteno nakon što ga je izvršio i dostavio.\" El Bakillani.","headingId":"trece-odgovor-na-hadis","headingText":"Treće - odgovor na hadis"},{"text":"Četvrto vrste zaborava kod poslanika 1. Zaborav u onome što se ne prenosi dopušten je, po ljudskoj prirodi. 2. Zaborav u onome što se prenosi iziskuje dva uslova: da nastupi nakon dostavljanja, i da usledi ponovno sećanje. Nevevi navodi: „To je dokaz da mu je dopušteno da zaboravi ono što je već dostavio ummetu.\" En Nevevi. Kada je reč o Kur'anu, razlikuju se dve podvrste: 1. Privremeni zaborav koji brzo nestaje, po ljudskoj prirodi. 2. To da Allah ukloni ajete derogacijom učenja.","headingId":"cetvrto-vrste-zaborava-kod-poslanika","headingText":"Četvrto - vrste zaborava kod poslanika"},{"text":"Peto odbačeno mišljenje Pojedini su tvrdili da se zaborav uopšte ne dešava, nego samo njegov oblik, radi poduke. Kadija Ijad to odbacuje: „To je protivrečnost koja se odbacuje, i to nije rekao niko od onih koji se slede, osim profesora Ebul Muzaffera el Isferajinija.\" Kadija Ijad.","headingId":"peto-odbaceno-misljenje","headingText":"Peto - odbačeno mišljenje"}]},{"slug":"Da-li-je-rec-Kuran-sirijska","chunks":[{"text":"Arapski i sirijski jezik potiču iz zajedničkog korena, pa je prirodno da se mnoge reči u njima poklapaju i po izgovoru i po značenju. Reč Kur'an je imenica izvedena iz glagola kara, sa dva značenja: učiti i sakupiti. Upravo to drugo značenje, sakupljanje, nije poznato u sirijskom, što tvrdnju o pozajmljivanju obara u samom temelju.","headingId":"","headingText":""},{"text":"Osnovni odgovor Arapski i sirijski jezik potiču iz zajedničkog korena, pa je prirodno naći mnoge reči koje se u oba jezika poklapaju u izgovoru i značenju. Moguće je i da se jedan od jezika razvio tako da zajednički izgovor u njemu nosi dodatna značenja kojih u drugom nema. Reč Kur'an je imenica izvedena iz glagola kara, u značenju učiti, dakle slediti slova i izgovarati ih, pa se u poreklu glagola javlja poklapanje sa sirijskim. To je posledica srodnosti dvaju jezika, a srodnost ne znači da je arapski taj glagol preuzeo iz sirijskog. Ako bi se stvar tako postavljala, moglo bi se jednako pitati zašto ne bi bilo obrnuto, to jest zašto sirijski ne bi bio taj koji je glagol preuzeo","headingId":"osnovni-odgovor","headingText":"Osnovni odgovor"},{"text":"iz arapskog. Sama činjenica poklapanja ne pokazuje smer pozajmljivanja.","headingId":"osnovni-odgovor","headingText":"Osnovni odgovor"},{"text":"Šta o tome kaže Draz Šejh Muhammed Abdullah Draz naveo je jezičko i etimološko značenje reči Kur'an i Kitab. Muhammed Abdullah Draz, En Nebeul azim, str. 41. Reč Kur'an izvorno je imenica oblika fu'lan, sa dammom, poput reči gufran, šukran i tuklan. Kaže se: proučio sam ga, učenjem i kur'anom, u istom značenju, dakle proučio sam ga. Upotreba reči kur'an u tom glagolskom značenju javlja se u ajetu: Sura El Kijama 75:17 Mi smo dužni da ga saberemo da bi ga ti čitao. Zatim je ta reč postala vlastito ime te plemenite Knjige. Sura El Isra 17:9 Ovaj Kur'an vodi jedinom ispravnom putu. Ona se naziva i Knjigom: Sura El Bekara 2:1 2 Elif lam mim. Ova Knjiga, u koju","headingId":"sta-o-tome-kaze-draz","headingText":"Šta o tome kaže Draz"},{"text":"nema nikakve sumnje.","headingId":"sta-o-tome-kaze-draz","headingText":"Šta o tome kaže Draz"},{"text":"Tajna dvaju naziva U nazivu Kur'an uzeto je u obzir to što se on uči jezicima, kao što je u nazivu Knjiga uzeto u obzir to što se zapisuje perima. Oba naziva spadaju u imenovanje stvari prema značenju na kojem počiva.","headingId":"tajna-dvaju-naziva","headingText":"Tajna dvaju naziva"},{"text":"Drugo značenje sakupljanje Reč Kur'an je i masdar glagola kara u značenju sakupiti, i tako je nazvan zato što objedinjuje sure, ajete i sve islamske propise. To značenje glagola kara nije poznato u sirijskom. Upravo tu tvrdnja o pozajmljivanju pada: reč u arapskom nosi značenjski raspon koji izvorni jezik iz kojeg je navodno preuzeta uopšte nema. Zebidi je u Tadžul arusu naveo: „Kara nešto znači sakupio ga je i objedinio, dakle spojio je jedno sa drugim.\" I: „Kare'tu šej'en kur'anen znači sakupio sam ga i spojio jedno sa drugim.\" Ez Zebidi, Tadžul arus. Iz toga je i njihov izraz kojim se kaže da utroba nije obuhvatila dete. Ebu Ishak ez Zedždžadž naveo je u svom tefsiru: „Govor Uzvišenog Allaha, koji","headingId":"drugo-znacenje-sakupljanje","headingText":"Drugo značenje - sakupljanje"},{"text":"je objavio Svome Poslaniku ﷺ, naziva se Knjigom, Kur'anom i Furkanom, zato što objedinjuje sure i spaja ih.\" Ez Zedždžadž. I ajet „Mi smo dužni da ga saberemo\" nosi upravo to značenje sakupljanja.","headingId":"drugo-znacenje-sakupljanje","headingText":"Drugo značenje - sakupljanje"},{"text":"Zašto tvrdnja o pozajmljivanju ne stoji ni metodološki Pored navedenog, tri opšta razloga govore protiv nje: Srodni jezici imaju zajedničke korene. Arapski, hebrejski i sirijski aramejski potiču iz zajedničke semitske osnove, pa je postojanje sličnog korena u dva od njih očekivano, a ne izuzetno. Zajedništvo nema smer. Da bi se pozajmljivanje dokazalo, potrebno je pokazati da reč u jednom jeziku nema izvođenje, a u drugom ima. Ovde je obrnuto: u arapskom postoji potpuno izvođenje sa oba značenja. Postoji cela porodica reči. Od istog korena u arapskom postoje glagol, particip, glagolska imenica i drugi oblici, svi u redovnoj upotrebi. Pozajmljene reči obično ulaze usamljene, bez porodice izvedenica. Ovaj postupak zaključivanja nije poseban za ovo pitanje. On je opšte pravilo uporedne lingvistike","headingId":"zasto-tvrdnja-o-pozajmljivanju-ne-stoji-ni-metodoloski","headingText":"Zašto tvrdnja o pozajmljivanju ne stoji ni metodološki"},{"text":"i primenjuje se jednako na svaki jezik. Zaključak da je reč pozajmljena traži dokaz, a sličnost oblika u srodnim jezicima taj dokaz nije.","headingId":"zasto-tvrdnja-o-pozajmljivanju-ne-stoji-ni-metodoloski","headingText":"Zašto tvrdnja o pozajmljivanju ne stoji ni metodološki"},{"text":"I kada bi reč bila pozajmljena Vredi primetiti da ni najgori mogući ishod ne bi značio ono što se iz njega izvodi. Postojanje pozajmljenica u jednom jeziku ne dovodi u pitanje ni izvornost tog jezika ni izvornost teksta na njemu. To pitanje muslimanskim jezikoslovcima nikada nije bilo sporno. Tvrdnja koju bi kritičar morao dokazati mnogo je jača od one koju iznosi: morao bi pokazati da tekst nije nastao na arapskom, a ne da jedna reč ima srodnika u srodnom jeziku.","headingId":"i-kada-bi-rec-bila-pozajmljena","headingText":"I kada bi reč bila pozajmljena"},{"text":"Zaključak Reč Kur'an je, dakle, arapski masdar glagola kara, u značenju učiti ili sakupiti.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Da-li-je-stvaranje-trajalo-sest-ili-osam-dana","chunks":[{"text":"Primedba se svodi na sabiranje dva plus četiri plus dva. Ali ajet o četiri dana ne uvodi novo razdoblje nego zbirno navodi ukupno vreme koje obuhvata i ona prva dva. To se u arapskom vidi po vezniku: upotrebljeno je ve, koje ne označava redosled, a ne summe ili fe, koji bi značili da jedno sledi za drugim.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Kur'an na više mesta navodi da je stvaranje nebesa i Zemlje trajalo šest dana. Sura El A'raf 7:54 Gospodar vaš je Allah, koji je nebesa i Zemlju u šest vremenskih razdoblja stvorio. Isto stoji i u ajetima Junus 10:3, Hud 11:7, El Furkan 25:59 i Kaf 50:38. Primedba se, međutim, gradi na razlaganju u suri Fussilet: Sura Fussilet 41:9 12 Reci: Zar, zaista, nećete da verujete u Onoga koji je u dva vremenska razdoblja Zemlju stvorio... I On je po njoj nepomična brda stvorio i blagoslovljenom je učinio i proizvode njezine u četiri vremenska razdoblja odredio... pa ih u dva vremenska razdoblja, kao sedam nebesa, uredio. Otuda se sabira: dva plus četiri plus dva jednako osam.","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Prvi deo ključ je u vezniku Arapski jezik razlikuje veznike po tome da li podrazumevaju redosled: | Veznik | Značenje | | | | | summe | Zatim, nakon toga podrazumeva vremenski razmak i redosled | | fe | Pa, odmah zatim podrazumeva neposredno sledovanje | | ve | I povezuje, bez tvrdnje o redosledu | U ajetu 41:10 upotrebljen je ve , a ne summe niti fe . Fahrudin er Razi izričito je naveo da vav označava neograničeno povezivanje, a ne redosled. Fahrudin er Razi. Ovo nije naknadno domišljanje radi izbegavanja primedbe. Reč je o osnovnom pravilu arapske sintakse, koje se primenjuje jednako na sve tekstove i koje se u gramatikama navodi nezavisno od ovog ajeta. Onaj ko primedbu","headingId":"prvi-deo-kljuc-je-u-vezniku","headingText":"Prvi deo - ključ je u vezniku"},{"text":"iznosi, prevodi arapski veznik ve kao da znači zatim, što nije.","headingId":"prvi-deo-kljuc-je-u-vezniku","headingText":"Prvi deo - ključ je u vezniku"},{"text":"Drugi deo kako to zvuči u običnom govoru Klasični mufessiri objasnili su to poređenjem sa svakodnevnim izražavanjem. Kurtubi je naveo primer čoveka koji kaže da je od Basre do Bagdada putovao deset dana, a do Kufe petnaest, pri čemu je ukupno vreme petnaest, a ne dvadeset pet. El Kurtubi. Begavi je naveo da četiri dana znače dva dana pridodata prethodnim dvama. El Begavi. Zedždžadž je dao isto objašnjenje. Ez Zedždžadž.","headingId":"drugi-deo-kako-to-zvuci-u-obicnom-govoru","headingText":"Drugi deo - kako to zvuči u običnom govoru"},{"text":"Tačan razmer | Stepen | Dani | | | | | Stvaranje Zemlje | 2 | | Brda i opskrba, uključujući prethodna dva | ukupno 4 | | Sedam nebesa | 2 | | Ukupno | 6 | Broj četiri je, dakle, zbirni, a ne dodatni.","headingId":"tacan-razmer","headingText":"Tačan razmer"},{"text":"Treći deo hadis Ebu Hurejre Zasebna primedba tiče se hadisa u kojem se stvaranje raspoređuje po danima u sedmici.","headingId":"treci-deo-hadis-ebu-hurejre","headingText":"Treći deo - hadis Ebu Hurejre"},{"text":"Razilaženje o lancu Ovo je jedno od poznatih mesta razilaženja među hadiskim kritičarima i ne treba ga prikrivati. Osporavali lanac: Buhari u Et Tarihul kebiru, Ali ibn el Medini kako prenosi Bejheki, Ibn Kesir u svom tefsiru, Ibn Tejmijje u Medžmu'ul fetavi, Ibn Kajjim u El Menarul munifu. Prihvatali verodostojnost: Muslim, koji ga je uvrstio u svoj Sahih, Ibn Hibban, koji ga je ocenio verodostojnim, Ševkani, Ebu Hajjan el Endelusi i Albani. Ovde je pošteno reći da spor postoji i da ga ozbiljni učenjaci vode sa obe strane. Ali za samu primedbu o šest ili osam dana to i nije presudno. Primedba se rešava na prethodnoj tački, u gramatici ajeta. Čak i kada bi hadis bio odbačen, kur'anski račun ostaje","headingId":"razilazenje-o-lancu","headingText":"Razilaženje o lancu"},{"text":"šest.","headingId":"razilazenje-o-lancu","headingText":"Razilaženje o lancu"},{"text":"Da li je poreklo u israilijatima Iznosi se mogućnost da hadis potiče od Ka'ba el Ahbara, jevrejskog konvertita. Protiv toga govori to što izveštaji koji se vezuju za Ka'ba el Ahbara počinju od nedelje, dok hadis počinje od subote. Da je preuzet, počinjao bi na istom mestu.","headingId":"da-li-je-poreklo-u-israilijatima","headingText":"Da li je poreklo u israilijatima"},{"text":"Šta znači jevm Reč jevm u arapskom ne označava nužno dan od dvadeset četiri sata. E. W. Lane navodi značenje vremena uopšte. E. W. Lane, Arabic English Lexicon. Hans Wehr navodi značenja doba, razdoblja, vremena. Hans Wehr, Dictionary of Modern Written Arabic. Ragib el Isfahani daje isto značenje. Er Ragib el Isfahani, El Mufredat. Sam Kur'an tu reč koristi za razdoblja različite dužine, u ajetima El Hadždž 22:47 i Es Sedžda 32:5. Ibn Tejmijje je ukazao na to da šest dana stvaranja nisu mereni sunčevim kretanjem, jer sunca još nije bilo. Ibn Tejmijje.","headingId":"sta-znaci-jevm","headingText":"Šta znači jevm"},{"text":"Pet primedbi na hadis Prva hadis navodi sedam dana, a Kur'an šest. Šest kur'anskih razdoblja i sedam dana u sedmici nisu iste jedinice. Albani je upravo to i objasnio. Druga protivreči izveštaju kod Taberija da je stvaranje počelo u nedelju. Reč je o predaji koja se vezuje za Abdullaha ibn Selama i Ka'ba el Ahbara, dakle o izveštaju nižeg stepena od hadisa. Treća protivreči saglasnosti da je počelo u nedelju. Ibn el Enbari je tvrdio saglasnost o suboti, a ne o nedelji, pa se navodna saglasnost ne može utvrditi. Četvrta hadis ne spominje stvaranje nebesa. Hadis obrađuje stvaranje Zemlje i onoga na njoj, a ne celokupno stvaranje. Neizrečeno nije poricanje. Peta drveće pre svetlosti je nemoguće. Ibn el Esir el","headingId":"pet-primedbi-na-hadis","headingText":"Pet primedbi na hadis"},{"text":"Džezeri ukazao je na to da reč nur u tom kontekstu može značiti dobro i blagodat, a ne fizičku svetlost. Ibn el Esir el Džezeri. Ovo poslednje objašnjenje treba označiti kao ono što jeste: jedno od mogućih tumačenja, a ne utvrđen zaključak. Ono je jezički moguće i navodi ga priznat leksikograf, ali ne treba ga predstavljati kao jedino ili konačno rešenje.","headingId":"pet-primedbi-na-hadis","headingText":"Pet primedbi na hadis"},{"text":"Svrha hadisa Suhejli, umro 581. godine po Hidžri, objasnio je da je svrha hadisa bila odgovor na jevrejsko shvatanje o suboti kao danu odmora. Es Suhejli. Ahmed Abdur Rahman el Benna es Sa'ati, umro 1378. godine po Hidžri, izneo je isto zapažanje. Ahmed Abdur Rahman el Benna es Sa'ati. Kur'an nigde ne pripisuje Allahu odmaranje nakon stvaranja, i to je razlika koju hadis i ističe.","headingId":"svrha-hadisa","headingText":"Svrha hadisa"},{"text":"Zaključak Račun od osam dana nastaje iz pogrešnog prevoda jednog veznika. Kada se ve prevede onako kako u arapskom stoji, ajeti u suri Fussilet daju šest, isto koliko i sva ostala mesta. Rasprava o hadisu Ebu Hurejre je zasebna i na ovaj račun ne utiče.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Da-li-je-Zejd-ibn-Sabit-izgubio-ajete","chunks":[{"text":"Izraz „izgubio sam\" odnosi se na gubitak pisanog zapisa, a ne na gubitak sačuvanog teksta, kako izričito navode Ibn Hazm, Ibn Hadžer i Ajni. Zejd je te ajete već znao napamet i znao je gde im je mesto. Ono što je tražio bio je pisani primerak nastao po Poslanikovoj ﷺ naredbi, jer je metod sakupljanja iziskivao i zapis i dva svedoka, a ne samo pamćenje.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Tvrdi se da je Zejd ibn Sabit izgubio tri kur'anska ajeta, i to na osnovu predaja u Sahihu Buharije. Jedna predaja spominje ajet iz sure El Ahzab, pronađen kod Huzejme ibn Sabita el Ensarija. Druga spominje dva ajeta sa kraja sure Et Tevba, pronađena kod Ebu Huzejme el Ensarija.","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Prvo nema protivrečnosti Između te dve predaje nema protivrečnosti. Ukupan broj ajeta koje je Zejd ibn Sabit našao kod te dvojice jeste tri: jedan ajet iz sure El Ahzab i dva ajeta sa kraja sure Et Tevba. Ibn el Dževzi je naveo: Oba su tačna. Oba ajeta pronađena su kod Huzejme. Poslednji ajet sure Et Tevba pronađen je kod njega u vreme Ebu Bekra, a ajet iz sure El Ahzab u vreme Osmana. Izvor: Ibn el Dževzi. Ibn el Dževzi. Ibn Battal je naveo da je ajet iz Et Tevbe bio kod Ebu Huzejme, a ajet iz El Ahzaba kod Huzejme ibn Sabita, a to nije ista osoba. Ibn Battal.","headingId":"prvo-nema-protivrecnosti","headingText":"Prvo - nema protivrečnosti"},{"text":"Drugo šta izraz „izgubio\" zapravo znači Ibn Hazm je objasnio: Što se tiče toga da je Zejd ibn Sabit izgubio ajet, to nije onako kako neuki misle. Nego to znači da ga nije našao zapisanog ni kod koga osim kod tog čoveka. Izvor: Ibn Hazm. Ibn Hazm. Ibn Hadžer je naveo: „Ono na šta ukazuje jeste da je gubitak bio gubitak pisanog postojanja, a ne gubitak toga da je sačuvan.\" Ibn Hadžer el Askalani, Fethul bari. Bedrudin el Ajni je objasnio: „Čuli su ga iz usta Allahovog Poslanika ﷺ, a izgubili su njegov zapis.\" Bedrudin el Ajni. El Hazin je pojasnio da je Zejd tražio primerak Kur'ana iz izvornog rukopisa napisanog po Poslanikovoj ﷺ naredbi, i da je obraćanje drugim","headingId":"drugo-sta-izraz-izgubio-zapravo-znaci","headingText":"Drugo - šta izraz „izgubio\" zapravo znači"},{"text":"ljudima bilo radi provere, a ne radi sticanja novog znanja, jer je Kur'an već bio sačuvan kod Zejda i drugih ashaba. El Hazin. Zerkeši je naveo: „Zejdove reči da ga je našao samo kod Huzejme ne znače da se Kur'an utvrđuje pojedinačnom vešću, jer ga je Zejd već bio čuo i znao je gde mu je mesto.\" Ez Zerkeši.","headingId":"drugo-sta-izraz-izgubio-zapravo-znaci","headingText":"Drugo - šta izraz „izgubio\" zapravo znači"},{"text":"Treće metod sakupljanja Zerkani je primetio da je Zejd u sakupljanju Kur'ana sledio precizan i pomno određen metod, koji su mu postavili Ebu Bekr i Omer: Nije se oslanjao samo na ono što je znao napamet, ni na ono što je zapisao, ni na ono što je neposredno čuo. Izvor: Ez Zerkani. Ez Zerkani, Menahilul irfan. Dr Muhammed Hasan Džebel naveo je tri uslova koja su morala biti ispunjena: 1. Tekst je morao biti zapisan u prisustvu Poslanika ﷺ. 2. Tekst je morao biti sačuvan i primljen neposredno od Poslanika ﷺ. 3. Dva svedoka morala su posvedočiti za prethodna dva uslova. Upravo taj metod objašnjava celu stvar. Zejd nije tražio ajet zato što ga niko nije znao, nego zato što","headingId":"trece-metod-sakupljanja","headingText":"Treće - metod sakupljanja"},{"text":"je uslov za unošenje u zbirku bio pisani zapis nastao pred Poslanikom ﷺ, uz dva svedoka. Strogost metoda, dakle, ne pokazuje slabost očuvanja, nego njegovu pažljivost.","headingId":"trece-metod-sakupljanja","headingText":"Treće - metod sakupljanja"},{"text":"Četvrto pitanje mutevatir prenosa Dva ajeta sa kraja sure Et Tevba nisu utvrđena kao kur'anski samo na osnovu izjave Ebu Huzejme. Njihov položaj utvrđen je brojnim predajama od ashaba, koji su ih znali napamet i kada ih nisu zapisali. Pisanje nije uslov mutevatir prenosa. Uslov je da ih prenosi skupina za koju je nezamislivo da se dogovori o laži.","headingId":"cetvrto-pitanje-mutevatir-prenosa","headingText":"Četvrto - pitanje mutevatir prenosa"},{"text":"Peto pitanje datovanja Imam Darekutni naveo je da je to hadis o sakupljanju Kur'ana, koji prenosi Zuhri, od Ubejda es Sebbaka, od Zejda ibn Sabita. Ed Darekutni. Hafiz Ibn Kesir naveo je da je smeštanje događaja sa ajetom iz El Ahzaba u vreme nakon Osmanovog sakupljanja upitno, i da se to zapravo dogodilo tokom sakupljanja koje je pokrenuo Ebu Bekr es Siddik. Ibn Kesir.","headingId":"peto-pitanje-datovanja","headingText":"Peto - pitanje datovanja"},{"text":"Ajet o kojem je reč Sura El Ahzab 33:23 Ima vernika koji ispunjavaju zavet dat Allahu.","headingId":"ajet-o-kojem-je-rec","headingText":"Ajet o kojem je reč"},{"text":"Zaključak Kur'an je ostao, i u reči i u zapisu, onakav kakav je objavljen.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Da-li-neuobicajena-ucenja-tabiina-obaraju-ocuvanje-Kurana","chunks":[{"text":"Nijedno od osam navedenih učenja ne ispunjava uslove priznatog kiraeta. Lanci su prekinuti, jer tabiini nisu sreli Poslanika ﷺ, a pojedini prenosioci su i posebno oslabljeni. Isti ti tabiini prenosili su utvrđeni tekst kroz priznate lance učenja, a rukopisi iz prvog veka, uključujući birmingemski, slažu se sa osmanskim mushafom.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Navodi se osam učenja koja se pripisuju pojedinim tabiinima i koja se razlikuju od utvrđenog teksta, pa se iz toga izvodi zaključak da kur'anski tekst nije očuvan. Navedena učenja pripisuju se sledećim ljudima: 1. Ubejdu ibn Umejru el Lejsiju, u suri El A'la. 2. Ikrimi, u ajetu o otkupu posta. 3. Ikrimi, na drugom mestu. 4. Mudžahidu, u ajetu o Safi i Mervi. 5. Seidu ibn Džubejru, u ajetu o otkupu posta. 6. Alkami i el Esvedu en Nehaiju, u suri El Fatiha. 7. Hattanu ibn Abdullahu, u ajetu o Poslanikovoj ﷺ smrtnosti. 8. A'mešu, u Ajetul kursiji.","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Prvo prekinuti lanci Tabiin je, po definiciji, onaj ko je sreo ashaba, a ne Poslanika ﷺ. To znači da učenje pripisano tabiinu bez navedenog ashaba u lancu ne dopire do izvora. Takav lanac je prekinut, a prekinut lanac ne može utvrditi kur'anski tekst ni u jednoj školi hadiskih nauka. Uz opšti prekid, pojedini lanci imaju i posebne slabosti: U drugom lancu je Hammad ibn Selema , čije se pamćenje u poznijim godinama pogoršalo, kako navodi Ibn Hadžer. Ibn Hadžer, Takribut tehzib. U četvrtom lancu je Jusuf ibn Abdul Melik , prenosilac o kome nema ocene, dakle nepoznat.","headingId":"prvo-prekinuti-lanci","headingText":"Prvo - prekinuti lanci"},{"text":"Drugo protivreče verodostojnom sunnetu Svako od tih učenja sudara se sa hadisima najviše ocene: | Navodno učenje | Verodostojan tekst | | | | | Sura El A'la | Buhari, br. 5755 | | Ajet o Safi i Mervi | Buhari, br. 1561, od Aiše | | Sura El Fatiha | Buhari, br. 749 | | Ajet o Poslanikovoj ﷺ smrtnosti | Buhari, br. 4187, Ebu Bekrovo učenje | | Ajetul kursija | Muslim, br. 810 | Ebu Bekrov slučaj posebno je rečit. On je taj ajet proučio pred okupljenim ashabima na dan Poslanikove ﷺ smrti, u trenutku najveće moguće pažnje, i niko ga nije ispravio.","headingId":"drugo-protivrece-verodostojnom-sunnetu","headingText":"Drugo - protivreče verodostojnom sunnetu"},{"text":"Treće isti ti tabiini prenosili su utvrđeni tekst Ovo je najteži deo prigovora za onoga ko ga iznosi. Imena koja se navode kao svedoci protiv teksta nalaze se u lancima priznatih učača: Mudžahid, Ikrima i Hattan ibn Abdullah nalaze se u lancu Ebu Amra. Alkama i el Esved nalaze se u lancu Hamze ez Zejjata. Ibn Kesirov lanac vodi do Ubejja ibn Ka'ba i Omera ibn el Hattaba. Asimov lanac vodi do Abdullaha ibn Mes'uda. Ibn Amirov lanac vodi do Osmana ibn Affana. Nafijev lanac obuhvata sedamdeset tabiina. Jakub el Hadrami ima lanac ocenjen kao krajnje čvrst i visok. Dakle, od istih tih ljudi imamo dva potpuno različita svedočanstva: jedno kroz priznate, neprekinute i proverene lance učenja, koje se slaže","headingId":"trece-isti-ti-tabiini-prenosili-su-utvrdjeni-tekst","headingText":"Treće - isti ti tabiini prenosili su utvrđeni tekst"},{"text":"sa mushafom, i drugo kroz pojedinačne prekinute predaje, koje se ne slaže. Nema razloga da se drugo pretpostavi prvom.","headingId":"trece-isti-ti-tabiini-prenosili-su-utvrdjeni-tekst","headingText":"Treće - isti ti tabiini prenosili su utvrđeni tekst"},{"text":"Četvrto to nisu nova zapažanja Ta učenja već su bila prenesena od pojedinih ashaba i već su bila obrađena i odbačena u klasičnoj literaturi. Nije reč o nekakvom skorašnjem otkriću, nego o materijalu koji je vekovima poznat i ocenjen.","headingId":"cetvrto-to-nisu-nova-zapazanja","headingText":"Četvrto - to nisu nova zapažanja"},{"text":"Peto saglasnost ashaba o osmanskom mushafu Ibn Ebu Davud es Sidžistani u Kitabul mesahifu beleži da su ashabi odobrili Osmanovo ujednačavanje. Ibn Ebu Davud es Sidžistani, Kitabul mesahif. Ibn Kesir je lanac tog izveštaja ocenio kao verodostojan. Ibn Kesir, uvod u tefsir. Alija ibn Ebu Talib, radijallahu anhu, izjavio je da bi, da Osman to nije učinio, on to sam učinio. Ibn Ebu Davud es Sidžistani, Kitabul mesahif.","headingId":"peto-saglasnost-ashaba-o-osmanskom-mushafu","headingText":"Peto - saglasnost ashaba o osmanskom mushafu"},{"text":"Šesto uslovi priznatog kiraeta Ibn el Džezeri je uslove sveo na četiri: 1. Verodostojan lanac prenošenja. 2. Neprekinut lanac. 3. Slaganje sa arapskim jezikom. 4. Slaganje sa osmanskim mushafom. Navedenih osam učenja pada već na prvom i drugom uslovu. Ono što ne ispunjava te uslove naziva se šazz , dakle neuobičajeno učenje, i po definiciji nije Kur'an.","headingId":"sesto-uslovi-priznatog-kiraeta","headingText":"Šesto - uslovi priznatog kiraeta"},{"text":"O rukopisima","headingId":"o-rukopisima","headingText":"O rukopisima"},{"text":"Birmingemski rukopis Pergament je radiokarbonski datovan u razdoblje između 568. i 645. godine. Sadrži delove sure Merjem, ajeti 91 98, sure Ta ha, ajeti 1 40, i sure El Kehf, ajeti 17 31. Tekst se u potpunosti slaže sa osmanskim mushafom, bez razlika. David Thomas sa Univerziteta u Birmingemu ukazao je na to da pergament potiče iz razdoblja unutar dve decenije nakon Poslanikove ﷺ smrti. David Thomas, Univerzitet u Birmingemu.","headingId":"birmingemski-rukopis","headingText":"Birmingemski rukopis"},{"text":"Svedočanstva orijentalista William Muir je za osmansku redakciju naveo da je tekst ostao tako čist kroz dvanaest vekova. William Muir, The Life of Mahomet, 1878. Arthur Jeffery je zaključio da se razlike u rukopisima gotovo uvek daju objasniti kao pisarske omaške. Arthur Jeffery, The Moslem World, tom 30, 1940. François Déroche je utvrdio da se varijante u ranim rukopisima tipološki uklapaju u osmanski tip teksta. François Déroche, Qur'ans of the Umayyads. Ova svedočanstva treba čitati onako kako ona glase. Ona ne znače da su navedeni autori prihvatili islamsko učenje o objavi, niti da su odustali od svojih šireg kritičkih stavova. Ona se odnose isključivo na jedno pitanje: na stabilnost teksta kroz rukopisni prenos.","headingId":"svedocanstva-orijentalista","headingText":"Svedočanstva orijentalista"},{"text":"Zaključak 1. Neuobičajena učenja nemaju verodostojan prenos. 2. Njihovi lanci su prekinuti, a pojedini prenosioci i dodatno oslabljeni. 3. Isti tabiini koji se navode kao dokaz prenosili su utvrđeni tekst. 4. Saglasnost ashaba nadjačava pojedinačne neuobičajene predaje. 5. Ta učenja protivreče verodostojnom sunnetu. 6. Rukopisi potvrđuju slaganje sa osmanskim tekstom.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Da-li-nikah-u-Kuranu-znaci-snosaj","chunks":[{"text":"Najjači odgovor nije rečnički nego kur'anski. U ajetu El Ahzab 33:49 redosled je jasan: prvo nikah, zatim razvod, zatim izričita napomena da do dodira nije došlo. Ako bi nikah značio snošaj, ajet bi tvrdio i da je dodira bilo i da ga nije bilo, u istoj rečenici.","headingId":"","headingText":""},{"text":"Sadržaj tvrdnje Iznosi se tvrdnja da reč nikah u Kur'anu ne znači brak nego snošaj, pa se onda kur'anski propisi o braku predstavljaju kao propisi o polnom činu.","headingId":"sadrzaj-tvrdnje","headingText":"Sadržaj tvrdnje"},{"text":"Ajet koji tvrdnju obara Sura El Ahzab 33:49 O vernici, kada se oženite vernicama, pa se od njih razvedete pre nego što ste imali odnos s njima, one nisu dužne čekati određeno vreme koje ćete vi brojati; darujte ih i lepo ih otpustite. Redosled u ovom ajetu je sledeći: 1. Nikah sklapanje braka. 2. Razvod raskid tog braka. 3. Napomena da do dodira nije došlo izričito, kao uslov propisa. 4. Posledica žena nema obavezu čekanja. Ako bi nikah značio snošaj, ajet bi glasio da su imali odnos, pa se razveli pre nego što su imali odnos. To nije tumačenje koje se može braniti nego rečenica koja sama sebe poništava. Uz to bi ceo propis izgubio smisao, jer se obaveza čekanja","headingId":"ajet-koji-tvrdnju-obara","headingText":"Ajet koji tvrdnju obara"},{"text":"upravo i zasniva na tome da li je do odnosa došlo.","headingId":"ajet-koji-tvrdnju-obara","headingText":"Ajet koji tvrdnju obara"},{"text":"Jezička napomena Arapski jezik razlikuje pojmove koje tvrdnja stapa u jedan: | Pojam | Značenje | | | | | Nikah | Brak, bračni ugovor | | Zevadž | Brak, ženidba | | Vet' | Polni odnos | Reč nikah u osnovi znači spajanje i sjedinjenje, i odatle je u pravnoj upotrebi postala naziv za ugovor koji dvoje spaja. Ona može, u određenim kontekstima, obuhvatiti i posledicu tog ugovora, ali to je izvedena upotreba, dok je osnovno značenje ugovor. Greška u postupku ovde je ista kao i kod drugih sličnih primedbi. Uzima se jedno od mogućih značenja višeznačne reči, proglašava se jedinim, i zatim se primenjuje na sva mesta bez obzira na kontekst. To se u tumačenju bilo kog teksta","headingId":"jezicka-napomena","headingText":"Jezička napomena"},{"text":"smatra nedopuštenim, pa bi tako trebalo i ovde.","headingId":"jezicka-napomena","headingText":"Jezička napomena"},{"text":"Rečnička potvrda El Mu'džemul vedžiz reč nikah određuje kao brak. El Mu'džemul vedžiz, str. 633. Ibn Manzur u Lisanul arebu, pod korenom n k h, navodi Ezherijevo tumačenje kur'anskih mesta upravo kroz pojam zevadž , dakle braka. Ibn Manzur, Lisanul areb, izdanje Dar el mearif, str. 4537, koren n k h.","headingId":"recnicka-potvrda","headingText":"Rečnička potvrda"},{"text":"Upotreba u hrišćanskim arapskim izvorima Ovo je zapažanje koje tvrdnju dodatno otežava onima koji je iznose. Arapski hrišćanski tekstovi, uključujući arapska izdanja Biblije, istu reč koriste upravo u značenju braka, i to na mestima koja govore o bračnom zakonu. Matej 5:32 A ja vam kažem da svaki koji pusti ženu svoju, osim za preljubu, navodi je te čini preljubu. Ovaj argument treba pažljivo postaviti. On ne tvrdi da je hrišćanska upotreba merilo za kur'ansko značenje. On pokazuje nešto uže: da arapski govornici, i to oni koji nisu muslimani, tu reč u bogoslužbenom i pravnom kontekstu koriste u značenju braka. Da je reč po sebi značila snošaj, takva upotreba ne bi bila moguća.","headingId":"upotreba-u-hriscanskim-arapskim-izvorima","headingText":"Upotreba u hrišćanskim arapskim izvorima"},{"text":"Zašto primedba ne stoji Sažeto, primedba pada iz tri razloga, od kojih je svaki dovoljan: 1. Kur'anska upotreba je odlučujuća. El Ahzab 33:49 postavlja nikah pre razvoda i izričito isključuje dodir, što tvrđeno značenje čini nemogućim. 2. Rečnici osnovno značenje daju kao brak , a ne kao polni čin. 3. Arapska upotreba izvan islama istu reč koristi u istom značenju.","headingId":"zasto-primedba-ne-stoji","headingText":"Zašto primedba ne stoji"},{"text":"Zaključak Tvrdnja se svodi na uzimanje jednog izvedenog značenja višeznačne reči i njegovo nametanje svim mestima na kojima se ta reč javlja. Prvi ajet koji se pogleda pokazuje da to nije održivo.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Deset-prigovora-o-ocuvanju-Kurana","chunks":[{"text":"Prigovori o očuvanju Kur'ana obično se iznose u nizu, jedan za drugim, kako bi stvorili utisak nagomilanih dokaza. Kada se razdvoje i ispitaju pojedinačno, svode se na tri vrste: predaje sa slabim lancima, verodostojne predaje o derogaciji, i predaje o ličnim primercima ashaba. Ovaj pregled služi kao mapa; svaki prigovor obrađen je do kraja u zasebnom članku.","headingId":"","headingText":""},{"text":"Zašto se navode u nizu Postupak nabrajanja treba prepoznati. Deset primedbi, od kojih svaka pada iz svog razloga, ne postaje jaka time što ih ima deset. Deset praznih vreća ne teži ništa više od jedne. Zato svaka mora biti ispitana zasebno, sa svojim izvorom i svojom ocenom.","headingId":"zasto-se-navode-u-nizu","headingText":"Zašto se navode u nizu"},{"text":"Pregled","headingId":"pregled","headingText":"Pregled"},{"text":"1. Predaja o milion i dvadeset sedam hiljada slova Navodi se predaja u kojoj se broj slova u Kur'anu daje kao znatno veći od onoga što današnji mushaf sadrži. Odgovor: Predaja ima slab lanac. Uz to, brojanje slova nikada nije bilo ujednačeno, jer zavisi od toga kako se broje slova koja se pišu, a ne izgovaraju, i obrnuto. Različiti načini brojanja daju različite zbirove za isti tekst.","headingId":"1-predaja-o-milion-i-dvadeset-sedam-hiljada-slova","headingText":"1. Predaja o milion i dvadeset sedam hiljada slova"},{"text":"2. Ajet o kamenovanju Odgovor: Reč je o dokumentovanom slučaju derogacije učenja uz zadržavanje propisa. Sam Omer, radijallahu anhu, odbio je da ga unese u mushaf, sa obrazloženjem da se ne bi reklo da je nešto dodao. Obrađeno u članku Ajet o kamenovanju zašto je njegovo učenje derogirano.","headingId":"2-ajet-o-kamenovanju","headingText":"2. Ajet o kamenovanju"},{"text":"3. Pogibija učača na Jemami Odgovor: Pogibija jeste istorijska činjenica, ali izvori je navode kao povod prvom sakupljanju , a ne kao izveštaj o gubitku. Ista pogibija ne može biti i dokaz gubitka i povod postupku koji je tekst osigurao. Obrađeno u članku Zuhrijeva slaba predaja o izgubljenom Kur'anu.","headingId":"3-pogibija-ucaca-na-jemami","headingText":"3. Pogibija učača na Jemami"},{"text":"4. Izjava Ibn Omera da je mnogo Kur'ana izgubljeno Odgovor: Predaja je verodostojna, ali je sam Ebu Ubejd svrstava pod poglavlje o derogaciji, a isto tumačenje daju Ibn Hadžer, Sujuti i Alusi. Obrađeno u članku Izjava Ibn Omera da je mnogo Kur'ana izgubljeno.","headingId":"4-izjava-ibn-omera-da-je-mnogo-kurana-izgubljeno","headingText":"4. Izjava Ibn Omera da je mnogo Kur'ana izgubljeno"},{"text":"5. Sura El Ahzab i navodnih dvesta ajeta Odgovor: Sve navedene predaje su slabe, zbog Ibn Lehie, Abdullaha ibn Šerika, Jezida ibn Ebu Zijada i Asima ibn Behdele. Obrađeno u članku Tvrdnja da je sura El Ahzab imala dvesta ajeta.","headingId":"5-sura-el-ahzab-i-navodnih-dvesta-ajeta","headingText":"5. Sura El-Ahzab i navodnih dvesta ajeta"},{"text":"6. Ajeti iz sure Et Tevba Navodi se Huzejfina izjava o tome da se od te sure uči samo deo onoga što je bilo. Odgovor: Reč je o istoj vrsti građe kao pod tačkom četiri i pet: ili o slabom lancu, ili o izrazu koji ukazuje na derogirano učenje. Izraz „učili smo\" upravo je ustaljeni način na koji se derogirano učenje spominje.","headingId":"6-ajeti-iz-sure-et-tevba","headingText":"6. Ajeti iz sure Et-Tevba"},{"text":"7. Ajet o dvema dolinama Ebu Musa el Ešari, radijallahu anhu, prenosi da je postojao tekst o čovekovoj pohlepi, koji je potom zaboravljen. Odgovor: Sama predaja izričito kaže da je tekst podignut , dakle uklonjen odlukom, a ne izgubljen ljudskim propustom. To je opis derogacije učenja, i to opis koji dolazi iz usta samog ashaba. Ovde vredi zastati. Predaja koja se navodi kao dokaz gubitka u sebi sadrži i objašnjenje zašto to nije gubitak. Onaj ko je navodi obično citira prvi deo, a izostavlja drugi.","headingId":"7-ajet-o-dvema-dolinama","headingText":"7. Ajet o dvema dolinama"},{"text":"8. Ajet o pet dojenja Odgovor: Predaja je verodostojna i o njoj nema spora. Ona opisuje derogaciju učenja: propis je ostao poznat i primenjuje se u fikhu do danas, dok tekst nije unesen u mushaf. To je razlika između uklanjanja teksta odlukom i gubitka teksta nemarom.","headingId":"8-ajet-o-pet-dojenja","headingText":"8. Ajet o pet dojenja"},{"text":"9. Predaja o životinji koja je pojela list Odgovor: Predaja pada na Muhammedu ibn Ishaku, koji je mudellis i ovde prenosi izrazom an . Alusi i Ibn Hazm ocenili su njen sadržaj kao neodrživ. Uz to, gubitak jednog lista ne dodiruje tekst koji hiljade ljudi znaju napamet. Obrađeno u članku Predaja o petlu koji je pojeo list sa ajetima.","headingId":"9-predaja-o-zivotinji-koja-je-pojela-list","headingText":"9. Predaja o životinji koja je pojela list"},{"text":"10. Sure El Hafd i El Hal' Odgovor: Nijedan izveštaj o njima nije potvrđen verodostojnim lancem. Ti tekstovi javljaju se u kontekstu dove kunut. Odlučujuće je to što deset priznatih kiraeta koji vode do Ubejja ibn Ka'ba te dve sure ne sadrže. Obrađeno u članku Osam tvrdnji o iskrivljenju Kur'ana.","headingId":"10-sure-el-hafd-i-el-hal","headingText":"10. Sure El-Hafd i El-Hal'"},{"text":"Tri vrste građe Kada se svih deset poređa, vidi se da pripadaju svega trima vrstama: | Vrsta | Primedbe | Šta o njima treba znati | | | | | | Slabi lanci | 1, 3, 5, 6, 9, 10 | Padaju na imenovanom prenosiocu, po merilima koja važe za sve predaje | | Derogacija učenja | 2, 4, 7, 8 | Verodostojne, ali opisuju uklanjanje odlukom, a ne gubitak | | Lični primerci ashaba | 10 | Beležnice pojedinaca, sa dovama i tumačenjima uz tekst | Razlikovanje druge vrste od prve najvažnije je za pošteno vođenje rasprave. Kod druge vrste odgovor nije da je predaja slaba, jer nije. Odgovor je da ona ne znači ono što se iz nje","headingId":"tri-vrste-gradje","headingText":"Tri vrste građe"},{"text":"izvodi. Mešati te dve vrste odgovora, pa na verodostojnu predaju odgovarati kao da je slaba, jednako je pogrešno kao i sam prigovor.","headingId":"tri-vrste-gradje","headingText":"Tri vrste građe"},{"text":"Zaključak Deset prigovora ne čini jedan jak dokaz nego deset zasebnih pitanja, od kojih svako ima svoj izvor i svoju ocenu. Šest pada na lancu, četiri opisuju derogaciju, i nijedan ne pokazuje da je iz mushafa nestalo ono što je u njemu trebalo da bude.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Dva-ucenja-u-ajetu-Ez-Zarijat-58","chunks":[{"text":"Oba oblika prenose se verodostojnim lancima, prvi preko Abdullaha ibn Mes'uda, drugi preko Abdullaha ibn Omera. Poslanik ﷺ je za svog života izričito odobrio različita učenja istog teksta, što je zabeleženo u Buhariji i Muslimu. Postojanje dva učenja, dakle, nije trag izmene nego posledica onoga što je od početka bilo dopušteno.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Iznosi se tvrdnja da je tekst iskrivljen, jer je Abdullah ibn Mes'ud, radijallahu anhu, ajet učio u prvom licu, dok mushaf ima treće lice. Sura Ez Zarijat 51:58 Opskrbu daje jedino Allah, Moćni i Jaki! Oblik koji se prenosi od Ibn Mes'uda glasi u prvom licu: „Ja sam Onaj koji opskrbu daje, Moćni i Jaki.\"","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Prvo dopuštenost više učenja Poslanik ﷺ je za svog života izričito odobrio da se isti tekst uči na više načina. Omer ibn el Hattab, radijallahu anhu, čuo je Hišama ibn Hakima ibn Hizama kako suru El Furkan uči drugačije nego što ju je on sam naučio, pa ga je odveo Poslaniku ﷺ. Poslanik ﷺ je saslušao obojicu i za svakog rekao da je tako objavljeno. Zatim je naveo da je Kur'an objavljen na sedam harfova, pa neka se uči ono što je od njega lakše. Izvor: Buhari i Muslim. Sahih Buhari; Sahih Muslim. Ovaj događaj rešava celu primedbu unapred. Ako se dva ashaba razilaze u učenju istog teksta, i ako Poslanik ﷺ obojici kaže da je tako objavljeno, onda razlika","headingId":"prvo-dopustenost-vise-ucenja","headingText":"Prvo - dopuštenost više učenja"},{"text":"u učenju po sebi ne može biti dokaz izmene. Ona je, naprotiv, dokaz da je takva raznolikost od početka bila predviđena. Predaje o sedam harfova prenose i Ebu Davud i Tirmizi, a lance su ocenili Ahmed Šakir u svom priređivanju Musneda i Albani. Sunen Ebu Davud; Sunen Tirmizi; Ahmed Šakir, priređivanje Musneda; El Albani. Ubejj ibn Ka'b i Abdullah ibn Abbas, radijallahu anhum, takođe su primili predaju o sedam harfova.","headingId":"prvo-dopustenost-vise-ucenja","headingText":"Prvo - dopuštenost više učenja"},{"text":"Drugo zašto mushaf ima oblik koji ima Kada je Osman, radijallahu anhu, ujednačio mushafe, zapisan je jedan od utvrđenih harfova, kurejšijski. Ovde treba razlikovati dve stvari. Osmanov postupak nije poništio ostale utvrđene harfove kao objavu, nego je ujednačio zapis. Ono što se moglo uklopiti u taj zapis ostalo je u upotrebi kroz priznate kiraete, a ono što se nije uklapalo prestalo je da se prenosi kao učenje mushafa. To je odluka o zapisu, a ne tvrdnja da je nešto bilo pogrešno.","headingId":"drugo-zasto-mushaf-ima-oblik-koji-ima","headingText":"Drugo - zašto mushaf ima oblik koji ima"},{"text":"Treće usmeni prenos je merodavan Kur'an se nikada nije prenosio samo zapisom. Osmanski zapis bio je bez tačaka i bez znakova za samoglasnike, pa je sam po sebi dopuštao više očitavanja. Ono što je odlučivalo kako se tekst uči bio je neprekinut usmeni prenos od učača do učača, sve do Poslanika ﷺ. Zato se učenja i danas ne uzimaju iz knjige nego se primaju od učitelja koji ima potvrđen lanac.","headingId":"trece-usmeni-prenos-je-merodavan","headingText":"Treće - usmeni prenos je merodavan"},{"text":"Četvrto i suprotni oblik ima verodostojan lanac Oblik u trećem licu, onaj koji stoji u mushafu, prenosi se verodostojnim lancem od Abdullaha ibn Omera, radijallahu anhuma. El Vadi'i, Es Sahihul musned. Dakle, nije reč o tome da postoji jedan ashabski prenos nasuprot mushafu, nego o dva ashabska prenosa, od kojih je jedan ušao u zapis.","headingId":"cetvrto-i-suprotni-oblik-ima-verodostojan-lanac","headingText":"Četvrto - i suprotni oblik ima verodostojan lanac"},{"text":"Zaključak Oba oblika prenose se verodostojno, oba imaju isto značenje, i nijedan ne uvodi propis kojeg u drugom nema. Poslanik ﷺ je razliku te vrste izričito odobrio dok je bio živ. Ono što se predstavlja kao trag iskrivljenja zapravo je zabeleženo obeležje same objave.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Dvadeset-pet-predaja-koje-sije-navode","chunks":[{"text":"Dvadeset pet predaja koje se navode kao dokaz iskrivljenja svode se na četiri vrste: derogirano učenje, slab lanac, neuobičajeno učenje i izmišljotinu. Ono što je presudno jeste da veći deo tih ocena dolazi iz samih šijskih izvora, jer su Tusi, Tabersi i Hui za mnoge od njih izneli isto tumačenje.","headingId":"","headingText":""},{"text":"O čemu je reč Iznosi se spisak od dvadeset pet predaja iz sunnijskih zbirki, sa tvrdnjom da one zajedno pokazuju da je kur'anski tekst izmenjen. Ovakav spisak treba čitati sa dve stvari na umu. Prvo, deset praznih vreća ne teži više od jedne, pa ni dvadeset pet predaja koje pojedinačno padaju ne postaju jak dokaz time što ih ima mnogo. Drugo, i ovo je važnije, ako bi te predaje zaista dokazivale iskrivljenje, dokazivale bi ga jednako za svakoga, jer se nalaze u knjigama koje obe strane koriste.","headingId":"o-cemu-je-rec","headingText":"O čemu je reč"},{"text":"Prvo pojašnjenje šta znači tahrif Pre razmatranja pojedinačnih predaja treba razjasniti pojam. Iskrivljenje znači da je tekst promenjen ljudskim zahvatom, dodavanjem ili oduzimanjem, mimo Božije odluke. Derogacija učenja znači da je tekst uklonjen odlukom Onoga koji ga je i objavio, još za Poslanikovog ﷺ života. To dvoje nije isto, i najveći deo spiska počiva upravo na njihovom mešanju.","headingId":"prvo-pojasnjenje-sta-znaci-tahrif","headingText":"Prvo pojašnjenje - šta znači tahrif"},{"text":"Drugo pojašnjenje ashabska učenja Pojedina učenja koja se prenose od ashaba nisu ušla u osmanski zapis. Za to postoje tri objašnjenja, i nijedno ne podrazumeva izmenu: 1. Reč je o derogiranom učenju , uklonjenom pre Poslanikove ﷺ smrti. 2. Reč je o tumačenju zapisanom uz tekst u ličnoj beležnici pojedinog ashaba. 3. Reč je o neuobičajenom učenju , koje ne ispunjava uslove priznatog kiraeta.","headingId":"drugo-pojasnjenje-ashabska-ucenja","headingText":"Drugo pojašnjenje - ashabska učenja"},{"text":"Pregled po vrstama","headingId":"pregled-po-vrstama","headingText":"Pregled po vrstama"},{"text":"Predaje o derogiranom učenju | Br. | Predaja | Izvor | | | | | | 1 | Ajet o kamenovanju | Ibn Abbas o Omeru | | 2 | Ajeti o dojenju | Aiša, El Itkan | | 3 | Ono što je Ebu Musa zaboravio | Ebu Musa el Ešari, El Itkan | | 4 | Borite se kao što ste se borili | Misver ibn Mahrema, El Itkan | | 5 | Dva ajeta koja nisu zapisana | Meslema ibn Muhalled, El Itkan | | 6 | Dužina sure El Ahzab | Zirr ibn Hubejš, El Itkan | | 7 | O poginulima kod Bir Meune | Enes, El Itkan | | 8 | O onima koji","headingId":"predaje-o-derogiranom-ucenju","headingText":"Predaje o derogiranom učenju"},{"text":"klanjaju u prvim safovima | Hamida bint Ebu Junus, El Itkan | | 9 | Sure El Hal' i El Hafd | El Itkan | | 10 | Izjava Ibn Omera | Ebu Ubejd, El Itkan | | 11 | Dvesta ajeta sure El Ahzab | Urva od Aiše, El Itkan | Ovo je najvažnija stavka celog odgovora. Za veći deo ovih predaja isto tumačenje, dakle derogaciju učenja, izneli su i šijski učenjaci Tusi i Tabersi. Time spisak gubi svrhu zbog koje je sastavljen: ne razdvaja dve strane, jer obe iste predaje tumače istovetno.","headingId":"predaje-o-derogiranom-ucenju","headingText":"Predaje o derogiranom učenju"},{"text":"Predaje sa neuobičajenim učenjem | Br. | Predaja | Napomena | | | | | | 13 | Učenje o Poslaniku ﷺ kao ocu vernika | Neuobičajeno učenje, priznaju i šijski komentatori | | 14 | Učenje o ikindijskom namazu | Neuobičajeno učenje, spominju ga i šijski učenjaci | | 15 | Učenje u suri El Lejl | Pojedinačno učenje; Tabersi potvrđuje da je neuobičajeno | | 16 | Učenje u suri El Fatiha | Neuobičajeno; spominju Ajaši i Kummi | Neuobičajeno učenje po definiciji nije Kur'an, jer ne ispunjava uslove priznatog kiraeta. Njegovo postojanje u izvorima pokazuje da su ti izvori otvoreno beležili i ono što nisu prihvatali, što je znak pouzdanosti prenosa, a ne njegove slabosti.","headingId":"predaje-sa-neuobicajenim-ucenjem","headingText":"Predaje sa neuobičajenim učenjem"},{"text":"Predaje sa slabim ili prekinutim lancem | Br. | Predaja | Mana | | | | | | 12 | O broju slova u Kur'anu | Slab lanac; pripisano Omeru bez potvrde | | 17 | Predaja o ždralovima | Oslabili je Ibn el Arebi, Kurtubi i Albani | | 19 | Hadžadžove izmene | Abbad ibn Suhajb je slab | | 20 | Učenje u suri En Nur | Nije potvrđeno od Ibn Abbasa; lanac slab | | 21 | Svetlost vernika | Oslabio Ibn el Enbari | | 22 | Životinja koja je pojela list | Muhammed ibn Ishak je mudellis | | 23 | Slova nepravilnog izgovora | Zbrkan i prekinut lanac |","headingId":"predaje-sa-slabim-ili-prekinutim-lancem","headingText":"Predaje sa slabim ili prekinutim lancem"},{"text":"Predaje koje počivaju na nesporazumu Osamnaesta izjava da je imamov mushaf nestao odnosi se na jedan određeni primerak, a ne na prenošeni tekst. Ibn Ebu Davud, El Mesahif, prenos od Malika. Dvadeset četvrta tvrdnja da je Ibn Mes'ud poricao dve poslednje sure odbačena je i sa šijske strane, kod Nurija, kao i kod kadije Ebu Bekra i Ibn Hazma. Dvadeset peta ajet koji se vezuje za Huzejmu, na kraju sure Et Tevba, potvrđen je masovnim pamćenjem. Uslov dva svedoka odnosio se na zapis , a ne na utvrđivanje da je nešto Kur'an; to je već bilo poznato mnoštvu hafiza. Dvadeset peta stavka najčešće se pogrešno razume, pa je vredi razjasniti. Zejd ibn Sabit tražio je dva svedoka da bi potvrdio","headingId":"predaje-koje-pocivaju-na-nesporazumu","headingText":"Predaje koje počivaju na nesporazumu"},{"text":"da je određeni zapis nastao pred Poslanikom ﷺ. On nije tražio dokaz da je tekst Kur'an, jer je to znalo mnoštvo ljudi napamet. Reč je o proveri zapisa, a ne o utvrđivanju objave.","headingId":"predaje-koje-pocivaju-na-nesporazumu","headingText":"Predaje koje počivaju na nesporazumu"},{"text":"Zašto ovaj spisak ne postiže svoj cilj Prvo , izvori su zajednički. Predaje su uzete iz dela koja obe strane koriste, pa bi, ako nešto dokazuju, dokazivale to svima. Drugo , ocene dolaze iz oba tabora. Za veći deo spiska isto tumačenje daju i šijski učenjaci, među njima Tusi, Tabersi i Hui. Treće , otvorenost beleženja govori u prilog prenosu. Da je postojala namera prikrivanja, ta građa ne bi bila zabeležena, imenovana i vekovima predavana kao predmet zasebne nauke. Treća tačka zaslužuje da se ponovi, jer se stalno previđa. Sve što spisak sadrži potiče iz muslimanskih knjiga, koje su te predaje same zabeležile, ocenile i razvrstale. Zajednica koja bi krila izmenu ne bi vodila iscrpnu evidenciju o svemu što bi","headingId":"zasto-ovaj-spisak-ne-postize-svoj-cilj","headingText":"Zašto ovaj spisak ne postiže svoj cilj"},{"text":"je moglo teretiti.","headingId":"zasto-ovaj-spisak-ne-postize-svoj-cilj","headingText":"Zašto ovaj spisak ne postiže svoj cilj"},{"text":"Zaključak Dvadeset pet predaja ne čini jedan dokaz nego dvadeset pet zasebnih pitanja. Kada se razvrstaju, jedanaest opisuje derogaciju učenja, četiri govore o neuobičajenim učenjima, sedam pada na lancu, a preostale počivaju na nesporazumu o tome šta je bio predmet provere.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Ebu-Amr-ibn-el-Ala-i-tvrdnja-o-prigovoru","chunks":[{"text":"Izjava koja se Ebu Amru pripisuje javlja se kod Ebul Kasima en Nejsaburija i Fahrudina er Razija, ali bez ikakvog lanca prenošenja. Njegova potvrđena izjava, koju prenosi Asmai, kaže upravo suprotno: da bi učio drugačije da nije toga što ne sme učiti osim onako kako je preneseno. To je i temeljno načelo: učenje je sunnet koji se sledi, a ne stvar ličnog izbora.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Ebu Amru ibn el Alau pripisuje se izjava kojom on navodno prigovara jednom kur'anskom obliku. Ta izjava javlja se u delu I'džazul bejan od Ebul Kasima en Nejsaburija, 2/549, i u Mefatihul gajbu od Fahrudina er Razija, 22/65, ali bez ikakvog lanca prenošenja. Ebul Kasim en Nejsaburi, I'džazul bejan, 2/549; Fahrudin er Razi, Mefatihul gajb, 22/65. Lanac prenošenja je put koji vodi ka verodostojnosti teksta, a nema dobra u tekstu bez lanca prenošenja. Jahja ibn Seid el Kattan naveo je: „Ne gledaj u hadis, nego gledaj u lanac prenošenja. Ako je lanac verodostojan, onda je u redu.\" Jahja ibn Seid el Kattan.","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Njegova potvrđena izjava Asmai prenosi: Čuo sam Ebu Amra ibn el Alaa kako kaže: Da nije toga što ne mogu učiti osim onako kako je učeno, proučio bih to slovo tako i tako. Izvor: Asmai. Ibn Mudžahid, Es Seb'a, str. 47; El Mustagfiri, Fedailul Kur'an, 1/373. Ta izjava pokazuje upravo suprotno od onoga radi čega se navodi. On kaže da mu se neki drugi oblik čini jezički bližim, ali da ga ne sme učiti, jer učenje ne zavisi od jezičkog ukusa nego od prenosa. To je izjava koja potvrđuje strogost predaje, a ne prigovor tekstu. Klasični učenjaci to su i utvrdili kao načelo: učenje je sunnet koji se sledi, dakle kasniji naraštaj ga prima od ranijeg, bez ličnog izmišljanja. Ibn","headingId":"njegova-potvrdjena-izjava","headingText":"Njegova potvrđena izjava"},{"text":"el Džezeri, En Nešr fil kiraatil ašr, 1/17.","headingId":"njegova-potvrdjena-izjava","headingText":"Njegova potvrđena izjava"},{"text":"Jezička stvarnost ajeta Sura Ta Ha 20:63 Rekoše: Ova dvojica su čarobnjaci. Taj ajet ima više potvrđenih učenja, i sva su jezički ispravna. Učenje Ebu Amra spada u kanonski kiraet koji se prenosi do Poslanika ﷺ.","headingId":"jezicka-stvarnost-ajeta","headingText":"Jezička stvarnost ajeta"}]},{"slug":"Elif-pauze-u-ucenju-Kurana","chunks":[{"text":"Elif koji se utvrđuje pri zastanku ima položaj fethe, a njegovo javljanje na mestima zastanka osnov je njegove ispravnosti. Postoje dva prepoznata arapska narečja, jedno koje taj elif koristi i drugo koje ga izostavlja. Ibn el Enbari izričito navodi da onaj ko ih uči bez elifa, a piše ih u mushafu sa elifom, nije protivrečio mushafu.","headingId":"","headingText":""},{"text":"Jezička osnova Elif koji se utvrđuje pri zastanku ima položaj fethe, a njegovo javljanje na mestima zastanka osnov je njegove ispravnosti.","headingId":"jezicka-osnova","headingText":"Jezička osnova"},{"text":"Učači koji elif izostavljaju Ebu Amr, Džahderi, Jakub i Hamza izostavljaju elif i pri spajanju i pri zastanku. Njihov argument je da je elif u pisanju dodatan.","headingId":"ucaci-koji-elif-izostavljaju","headingText":"Učači koji elif izostavljaju"},{"text":"Stav Ibn el Enbarija Ko uči ez zunun, es sebil i er resul bez elifa u ta tri slova, a piše ih u Kur'anu sa elifom, taj nije protivrečio mushafu. Izvor: Ibn el Enbari. Ibn el Enbari. On objašnjava da se elif spušta na položaj fethe, a ono što je uz njega jeste oslonac za pokret koji mu prethodi. Ovde je jezgro odgovora na primedbu. Razlika između zapisa i izgovora ne znači da se neko ogrešio o mushaf. Rasm beleži jedno, a učenje dopušta oba oblika, jer je elif na tom mestu nosilac vokala, a ne zaseban glas.","headingId":"stav-ibn-el-enbarija","headingText":"Stav Ibn el-Enbarija"},{"text":"Narečna osnova Postoje dva prepoznata arapska narečja: jedno koje taj elif koristi i drugo koje ga izostavlja. Reč je o ustaljenoj jezičkoj raznolikosti među Arapima.","headingId":"narecna-osnova","headingText":"Narečna osnova"},{"text":"Učači koji slede to narečje Nafi, Ibn Kesir, Ibn Muhajsin i Kisai utvrđuju elif pri zastanku, a izostavljaju ga pri spajanju. Ibn el Enbari zaključuje: „Opravdano je reći da je elif bio potreban pri zastanku kako bi se osiguralo da se fetha zadrži.\" Ibn el Enbari.","headingId":"ucaci-koji-slede-to-narecje","headingText":"Učači koji slede to narečje"},{"text":"Pregled stavova | Učač | Postupak | | | | | Ebu Amr | Izostavlja elif i pri spajanju i pri zastanku | | Džahderi | Isto | | Jakub | Isto | | Hamza | Isto | | Nafi i njegov krug | Utvrđuje pri zastanku, izostavlja pri spajanju | | Ibn Kesir | Isto | | Ibn Muhajsin | Isto | | Kisai | Isto | Ahmed ibn Jahja, poznat kao Sa'leb, takođe je o toj pojavi govorio, a kao potvrda navode se i stihovi iz starije arapske poezije u kojima se isti postupak javlja na krajevima stihova. Ahmed ibn Jahja. Da je pravilo opisano na osnovu poezije i običnog govora, a ne izvedeno iz mushafa, važno je","headingId":"pregled-stavova","headingText":"Pregled stavova"},{"text":"za ocenu prigovora. Kada pravilo postoji nezavisno od teksta na koji se primenjuje, ono nije naknadno smišljeno objašnjenje.","headingId":"pregled-stavova","headingText":"Pregled stavova"},{"text":"Zašto je elif ipak zapisan Zapis je morao podneti oba postupka istovremeno. Da elif nije zapisan, oni koji ga izgovaraju pri zastanku ne bi imali uporište u zapisu. Da je zapisan tako da se mora izgovarati uvek, oni koji ga izostavljaju bili bi isključeni. Ovo je opšta osobina osmanskog zapisa, koja se vidi i na drugim mestima. Rasm nije bio pravopis u savremenom smislu, sa jednim propisanim oblikom za svaku reč. Bio je okvir koji je istovremeno podnosio više primljenih načina učenja. Ono što izgleda kao nedoslednost jeste zapravo namerna širina.","headingId":"zasto-je-elif-ipak-zapisan","headingText":"Zašto je elif ipak zapisan"},{"text":"Zaključak Elif zastanka nije pisarska omaška nego zabeležena crta arapskog govora, opisana kod gramatičara nezavisno od Kur'ana. Razlike među učačima o njemu tiču se izgovora u jednom položaju i ne dodiruju značenje nijednog ajeta.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Izjava-Ibn-Omera-o-izgubljenom-Kuranu","chunks":[{"text":"Ova predaja je verodostojna i to nije sporno. Sporno je njeno značenje, a ono je jednoglasno protumačeno. Sam Ebu Ubejd svrstao ju je pod poglavlje o onome što je uklonjeno nakon objave i nije potvrđeno u mushafima, dakle o derogaciji. Isto tumačenje daju Ibn Hadžer u Fethul bariju, Sujuti u El Itkanu i Alusi u Ruhul meaniju.","headingId":"","headingText":""},{"text":"Predaja o kojoj je reč Neka niko od vas ne govori: uzeo sam čitav Kur'an. Otkud on zna šta je sve od njega? Mnogo Kur'ana je izgubljeno. Nego neka kaže: uzeo sam od njega ono što se pojavilo. Izvor: Ibn Omer. Sunen Seida ibn Mensura, br. 140, preko Ismaila ibn Ibrahima, od Ejjuba, od Nafija, od Ibn Omera. Ova predaja jeste verodostojna, i to ovde nije sporno. Sporno je isključivo njeno značenje. Odgovor se, dakle, ne gradi na osporavanju lanca, nego na tome kako su je razumeli sami učenjaci.","headingId":"predaja-o-kojoj-je-rec","headingText":"Predaja o kojoj je reč"},{"text":"Prvo kako ju je razvrstao sam Ebu Ubejd Ebu Ubejd je tu predaju svrstao pod naslov poglavlja: „Ono što je uklonjeno iz Kur'ana nakon njegove objave i nije potvrđeno u mushafima.\" Taj naslov odnosi se isključivo na ajete koji su objavljeni, pa ih je Allah derogirao za Poslanikovog ﷺ života, a o tome postoji potpuna muslimanska saglasnost.","headingId":"prvo-kako-ju-je-razvrstao-sam-ebu-ubejd","headingText":"Prvo - kako ju je razvrstao sam Ebu Ubejd"},{"text":"Drugo stav učenjaka Ibn Hadžer el Askalani naveo je: „U tome nema ničega što protivreči hadisu poglavlja, jer je sve to od onoga što je derogirano.\" Ibn Hadžer el Askalani, Fethul bari. Sujuti tu predaju svrstava pod „ono čije je učenje derogirano, a propis nije\". Es Sujuti, El Itkan fi ulumil Kur'an, 3/81 82. Alusi potvrđuje: „Složili su se da nema nikakvog manjka u onome što je preneseno u Kur'anu, onako kako danas postoji između dve korice.\" El Alusi, Ruhul meani. Priređivač Sunena Seida ibn Mensura, dr Sa'd ibn Abdullah Al Hamid, objašnjava da izraz „mnogo Kur'ana je izgubljeno\" znači da je izostavljeno za života Poslanika ﷺ, ili da je izostavljeno u dvema zbirkama oko kojih je postignuta saglasnost nakon","headingId":"drugo-stav-ucenjaka","headingText":"Drugo - stav učenjaka"},{"text":"njega. Dr Sa'd ibn Abdullah Al Hamid.","headingId":"drugo-stav-ucenjaka","headingText":"Drugo - stav učenjaka"},{"text":"Treće Poslanik ﷺ nije ostavio ništa drugo Abdul Aziz ibn Rufej i Šeddad ibn Makil upitali su Ibn Abbasa: Da li je Poslanik ﷺ nešto ostavio? Odgovorio je: Nije ostavio ništa osim onoga što je između dve korice. Izvor: Sahih Buhari. Sahih Buhari. Ibn Hadžer objašnjava: „Naslov ovog poglavlja odgovor je onima koji su tvrdili da je mnogo Kur'ana izgubljeno zato što su izgubljeni njegovi nosioci.\" Ibn Hadžer el Askalani. Bedrudin el Ajni pojašnjava: „Ovo poglavlje je napisano kao odgovor rafidijama koji su tvrdili da je mnogo Kur'ana izgubljeno i da je izričito spominjanje imameta Alije ibn Ebu Taliba bilo utvrđeno u Kur'anu, ali da su ga ashabi prikrili.\" Bedrudin el Ajni. Sura Fussilet 41:41 42 A on je, zaista,","headingId":"trece-poslanik-nije-ostavio-nista-drugo","headingText":"Treće - Poslanik ﷺ nije ostavio ništa drugo"},{"text":"knjiga zaštićena, laž joj je strana, bilo s koje strane; on je Objava od Mudrog i hvale dostojnog.","headingId":"trece-poslanik-nije-ostavio-nista-drugo","headingText":"Treće - Poslanik ﷺ nije ostavio ništa drugo"},{"text":"Četvrto predaja o ajetu o kamenovanju Predaja u kojoj stoji da je ajet o kamenovanju izgubljen sa mnogo Kur'ana koje je otišlo sa Muhammedom nema utvrđen lanac prenošenja. Sujuti je spominje u El Itkanu, 2/33, i u Ed Durrul mensuru, u poglavlju o derogiranom učenju. Es Sujuti, El Itkan, 2/33. Čak i kada bi bila verodostojna, ta izjava odnosi se na derogaciju, koja ima razrađene pravne propise.","headingId":"cetvrto-predaja-o-ajetu-o-kamenovanju","headingText":"Četvrto - predaja o ajetu o kamenovanju"},{"text":"Peto o navodnim dodacima Tvrdnje da je Kur'an izvorno sadržao ajete poput onih o Aliji jesu izmišljotine. Onima koji te tvrdnje iznose treba postaviti jasno pitanje: da li su ti navodni ajeti derogirani ili su ih ashabi namerno izbrisali? Ako je prvo, onda nisu ni trebali ostati. Ako je drugo, to protivreči jednoglasnom svedočanstvu ashaba, tabiina i svih islamskih imama.","headingId":"peto-o-navodnim-dodacima","headingText":"Peto - o navodnim dodacima"},{"text":"Zaključak Izjava Ibn Omera odnosi se na kur'anske ajete čije je učenje derogirano za života Poslanika ﷺ. Naslov poglavlja kod Ebu Ubejda, kao i Ibn Hadžer, Sujuti, Alusi i priređivač Sunena Seida ibn Mensura, to tumačenje potvrđuju bez razilaženja.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Jedanaest-razlika-izmedu-Hafsa-i-Kaluna","chunks":[{"text":"Razlike među priznatim predanjima nisu greške u prepisivanju nego primljeni oblici učenja, svaki sa sopstvenim neprekinutim lancem do Poslanika ﷺ. Sve navedene razlike uklapaju se u isti osmanski zapis bez tačaka i samoglasničkih znakova. Nijedna od njih ne uvodi propis kojeg u drugom predanju nema.","headingId":"","headingText":""},{"text":"Napomena o pojmovima Pre pregleda razlika treba razjasniti pojmove, jer se prigovor često gradi upravo na njihovom mešanju. Kiraet je učenje koje se pripisuje jednom od priznatih imama učača, poput Asima ili Nafija. Rivajet je predanje tog učenja preko određenog učenika. Hafs i Šuba su dvojica prenosilaca Asimovog kiraeta. Kalun i Verš su dvojica prenosilaca Nafijevog kiraeta. Hafs i Kalun, dakle, nisu dva kiraeta nego dva rivajeta dvaju različitih kiraeta. Nazivati njihove razlike razlikama među rukopisima, verzijama ili izdanjima jeste pojmovna zamena. Reč je o učenjima, a ne o tekstovima koji se međusobno osporavaju.","headingId":"napomena-o-pojmovima","headingText":"Napomena o pojmovima"},{"text":"Kako su te razlike nastale Kur'an se od početka primao slušanjem, od učitelja koji je i sam primio od svog učitelja. Osmanski zapis bio je bez tačaka koje razlikuju slova i bez znakova za samoglasnike. On je, dakle, bio okvir unutar kojeg su se utvrđeni oblici učenja mogli zapisati istim potezom pera. Zato razlika u samoglasniku ili u tome da li je glagol u aktivnom ili pasivnom obliku nije zahtevala različit zapis.","headingId":"kako-su-te-razlike-nastale","headingText":"Kako su te razlike nastale"},{"text":"Pregled jedanaest razlika | Br. | Mesto | Hafs | Drugo predanje | Priroda razlike | | | | | | | | 1 | Ali Imran 3:146 | katele borio se | kutile bio ubijen | Aktiv i pasiv | | 2 | Ali Imran 3:125 | musevvimin koji obeležavaju | musevvemin obeleženi | Aktivni i pasivni particip | | 3 | Ali Imran 3:161 | jegulle da pronevri | jugalle da bude pronevereno | Aktiv i pasiv | | 4 | Ez Zuhruf 43:19 | ibadu robovi | inde kod | Razlika u reči | | 5 | Ez Zuhruf 43:24 | kale reče | kul reci | Glagolski oblik | | 6 | El Bekara 2:119 |","headingId":"pregled-jedanaest-razlika","headingText":"Pregled jedanaest razlika"},{"text":"ve la tus'elu nećeš biti pitan | ve la tes'el ne pitaj | Aktiv i pasiv | | 7 | El Bekara 2:191 | oblici od katele | oblici od katala | Glagolska osnova | | 8 | El Bekara 2:184 | miskin jednina | mesakin množina | Broj | | 9 | El Bekara 2:285 | kutubihi Njegove knjige | kitabihi Njegova knjiga | Jednina i množina | | 10 | El Hadid 57:24 | sadrži huve | bez huve | Prisustvo zamenice | | 11 | Merjem 19:19 | li ehebe da ti darujem | li jehebe da ti On daruje | Lice glagola | Uz to, u dva slučaja postoji i razlika u brojanju ajeta, kod El","headingId":"pregled-jedanaest-razlika","headingText":"Pregled jedanaest razlika"},{"text":"Bekare 2:119 i Ez Zuhrufa 43:19. Razlika u brojanju ajeta zaslužuje posebnu napomenu. Ona ne znači da neko ima tekst kojeg drugi nema, nego da se granica između dva ajeta postavlja na različito mesto. Tekst je isti, a brojevi se pomeraju. Uvrštavanje toga u spisak razlika u tekstu je obmanjujuće.","headingId":"pregled-jedanaest-razlika","headingText":"Pregled jedanaest razlika"},{"text":"Šta te razlike zapravo znače Uzmimo treći primer. Ajet u aktivnom obliku znači da vernik ne treba da pronevari ratni plen. U pasivnom obliku znači da poslanik ne bi bio taj kome se plen pronevari. Oba značenja su istinita, oba su u skladu sa ostatkom objave i nijedno ne poriče drugo. To je razlika raznolikosti, a ne razlika suprotstavljanja. Uzmimo deveti primer. Verovanje u Allahove knjige i verovanje u Allahovu knjigu ne isključuju se. Jedno govori o svim objavama, drugo o objavi kao pojmu. Uzmimo jedanaesti. Da ti darujem, kada to govori melek koji prenosi Božiju odluku, i da ti On daruje, kada se govori o samom Darovatelju, opisuju isti događaj sa dve strane.","headingId":"sta-te-razlike-zapravo-znace","headingText":"Šta te razlike zapravo znače"},{"text":"Uslovi priznatog učenja Ibn el Džezeri je uslove sveo na tri: 1. Verodostojan, neprekinut lanac prenošenja do Poslanika ﷺ. 2. Slaganje sa arapskim jezikom, makar u jednom njegovom obliku. 3. Slaganje sa osmanskim zapisom, makar posredno. Ono što ispunjava sva tri jeste Kur'an. Ono što ne ispunjava, nije, bez obzira na to ko ga prenosi. Ibn el Džezeri, En Nešr fil kiraatil ašr. Zerkani isto načelo razrađuje u Menahilul irfanu. Ez Zerkani, Menahilul irfan.","headingId":"uslovi-priznatog-ucenja","headingText":"Uslovi priznatog učenja"},{"text":"Zašto razlike uopšte postoje Ebu el Fadl er Razi i Ibn Kutejba obradili su svrhu tih razlika, a ona se svodi na sledeće: 1. Olakšanje arapskim plemenima različitih narečja, u vreme kada je pismenost bila retka. 2. Bogatstvo značenja , jer dva oblika istog ajeta daju dva istinita značenja umesto jednog. 3. Dokaz o prenosu , jer se razlike prenose otvoreno, sa navedenim lancima i imenima, umesto da budu prikrivene. Ova poslednja tačka je važna. Da je postojala namera da se tekst ujednači prikrivanjem, razlike ne bi bile pomno zabeležene, imenovane i vekovima predavane kao zasebna nauka. Njihova otvorena dokumentovanost sama je dokaz o pouzdanosti prenosa, a ne o njegovoj nesigurnosti.","headingId":"zasto-razlike-uopste-postoje","headingText":"Zašto razlike uopšte postoje"},{"text":"O Goldziherovoj primedbi Goldziher je razlike među učenjima protumačio kao posledicu nedostatka tačaka u ranom pismu, dakle kao naknadna očitavanja nejasnog zapisa. Ta pretpostavka previđa osnovnu činjenicu o prenosu: zapis nikada nije bio jedini nosilac teksta. Uz svaki poslani mushaf išao je i učač koji je ljude podučavao učenju, upravo zato što zapis sam po sebi nije bio dovoljan. Uz to, da su učenja nastajala pogađanjem iz nejasnog zapisa, očekivali bismo mnoštvo međusobno nesaglasnih oblika bez lanaca. Umesto toga imamo ograničen, imenovan i lančano potvrđen skup oblika, koji se svi uklapaju u isti zapis.","headingId":"o-goldziherovoj-primedbi","headingText":"O Goldziherovoj primedbi"},{"text":"Zaključak Jedanaest navedenih razlika, kada se pogledaju pojedinačno, svode se na razlike u samoglasniku, u glagolskom obliku, u broju imenice i u jednoj zamenici. Sve se uklapaju u isti zapis, sve imaju neprekinut lanac, i nijedna ne menja propis.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Kako-je-Ebu-Bekr-sakupio-Kuran","chunks":[{"text":"Iako su Zejd ibn Sabit i drugi ashabi Kur'an znali napamet, u sakupljanju su sledili precizan i pomno određen metod. Ništa se nije prihvatalo bez dva svedoka i bez zapisa nastalog u prisustvu Poslanika ﷺ, i to iz poslednjeg izlaganja. Najbolji pokazatelj te strogosti jeste to što ni Omer nije mogao da unese ono što je doneo, jer je bio sam.","headingId":"","headingText":""},{"text":"Osnovna postavka Iako bi bilo lako izmisliti bilo šta što nije bilo deo Kur'ana, i iako su Zejd ibn Sabit, koji ga je sastavio, i drugi ashabi Kur'an znali napamet, oni su u sakupljanju Kur'ana u vreme Ebu Bekra sledili precizan i pažljiv metod.","headingId":"osnovna-postavka","headingText":"Osnovna postavka"},{"text":"Prvo ko je nešto primio od Poslanika ﷺ, morao je to doneti Ko je od Allahovog Poslanika nešto primio od Kur'ana, neka nam to donese. Građa je bila zabeležena na svicima, pločicama i palminim listovima, a ništa se nije prihvatalo ni od koga dok za to ne posvedoče dva svedoka.","headingId":"prvo-ko-je-nesto-primio-od-poslanika-morao-je-to-doneti","headingText":"Prvo - ko je nešto primio od Poslanika ﷺ, morao je to doneti"},{"text":"Drugo ništa bez dva svedoka Ebu Bekr je naložio: Sedi kod vrata džamije, pa ko ti dovede dva svedoka za nešto iz Allahove Knjige, zapiši to.","headingId":"drugo-nista-bez-dva-svedoka","headingText":"Drugo - ništa bez dva svedoka"},{"text":"Šta se pod dvojicom svedoka mislilo Postoje različita tumačenja: da svedoci posvedoče da je ono što je zapisano bilo zapisano u prisustvu Allahovog Poslanika ﷺ, ili da posvedoče da je to jedan od načina na koji je Kur'an objavljen. Najjače objašnjenje polazi od toga da je Kur'an bio sačuvan u srcima mnogih ashaba, pa da bi, da su tražili svedočenje o pamćenju, našli desetine takvih. Upravo to pokazuje šta se tim uslovom postizalo. Svedoci nisu bili potrebni da bi se utvrdilo da je nešto Kur'an, jer je to ionako bilo poznato mnoštvu. Oni su bili potrebni da bi se utvrdilo da je taj zapis nastao pred Poslanikom ﷺ. Reč je, dakle, o proveri zapisa, a ne o proveri objave.","headingId":"sta-se-pod-dvojicom-svedoka-mislilo","headingText":"Šta se pod dvojicom svedoka mislilo"},{"text":"Treće Kur'an je zapisan na listovima Listovi na kojima je Kur'an sakupljen bili su kod Ebu Bekra dok mu Allah nije uzeo dušu, zatim kod Omera dok mu Allah nije uzeo dušu, a zatim kod Hafse bint Omer.","headingId":"trece-kuran-je-zapisan-na-listovima","headingText":"Treće - Kur'an je zapisan na listovima"},{"text":"Četvrto uslovi za prihvatanje donesenog 1. Morao je biti zapisan u prisustvu Poslanika ﷺ. Cilj im je bio da se ništa ne zapiše osim onoga što je zapisano u prisustvu Poslanika ﷺ, a ne samo po pamćenju. 2. Morao je biti utvrđen iz poslednjeg izlaganja , dakle iz onoga što je Poslaniku ﷺ izloženo u godini njegove smrti.","headingId":"cetvrto-uslovi-za-prihvatanje-donesenog","headingText":"Četvrto - uslovi za prihvatanje donesenog"},{"text":"Peto ajeti su zapisani u svojim surama Ajeti su zapisani u svojim surama, po redosledu i preciznosti koje su muslimani primili od Poslanika ﷺ.","headingId":"peto-ajeti-su-zapisani-u-svojim-surama","headingText":"Peto - ajeti su zapisani u svojim surama"},{"text":"Strogost metoda na delu Prvi koji je sakupio Kur'an bio je Ebu Bekr, a Zejd ga je zapisao. Ljudi bi dolazili Zejdu ibn Sabitu, a on ne bi zapisao nijedan ajet osim uz dvojicu pravednih svedoka. Upečatljiv primer jeste to što je Omer doneo jedan ajet, ali on nije zapisan, jer je Omer bio sam. Taj slučaj je najbolji odgovor na tvrdnju da je sakupljanje bilo proizvoljno. Omer je bio drugi čovek zajednice i budući halifa, a njegovo svedočenje nije bilo dovoljno, jer metod nije pravio izuzetke ni za koga.","headingId":"strogost-metoda-na-delu","headingText":"Strogost metoda na delu"},{"text":"Šta je tim metodom postignuto","headingId":"sta-je-tim-metodom-postignuto","headingText":"Šta je tim metodom postignuto"},{"text":"Saglasnost zajednice Ishod tog posla prihvatili su svi muslimani, bez prigovora. Alija ibn Ebu Talib, radijallahu anhu, pohvalio je Ebu Bekrov postupak i istakao njegovu zaslugu u tome. Ibn Ebu Davud, Kitabul mesahif. Ibn Hadžer se osvrnuo na vrednost uvođenja takvog postupka, dovodeći ga u vezu sa hadisom o onome ko uvede lepu praksu. Ibn Hadžer, Fethul bari. Ko uvede u islamu lepu praksu, ima njenu nagradu i nagradu onih koji po njoj postupaju nakon njega, a da se njihova nagrada nimalo ne umanji. Izvor: Sahih Muslim. Sahih Muslim, Knjiga o znanju.","headingId":"saglasnost-zajednice","headingText":"Saglasnost zajednice"},{"text":"Masovan prenos Broj svedoka na kojima je sakupljanje počivalo daleko je premašivao ono što se u bilo kojoj drugoj oblasti traži za utvrđivanje činjenice. To znači da sakupljeni tekst nije počivao na pojedinačnoj vesti nego na masovnom prenosu, u kojem je usaglašena greška nemoguća.","headingId":"masovan-prenos","headingText":"Masovan prenos"},{"text":"Jasno razgraničenje U sakupljeno je uneseno samo ono što je bilo potvrđeno kao kur'anski tekst. Izostavljeno je ono čije je učenje derogirano, kao i ono što je kod pojedinih ashaba bilo zapisano uz tekst kao tumačenje. To razgraničenje je važnije nego što na prvi pogled izgleda. Ono pokazuje da su ashabi razlikovali tri različite stvari: kur'anski tekst, derogirano učenje i zabeleženo tumačenje. Kasnije primedbe koje te tri stvari mešaju pripisuju ashabima zbrku koju oni sami nisu imali.","headingId":"jasno-razgranicenje","headingText":"Jasno razgraničenje"},{"text":"Osnova za ono što je usledilo Kada je Osman, radijallahu anhu, pristupio umnožavanju mushafa, zatražio je upravo te listove od Hafse i po njima dao prepisati primerke poslane u pokrajine. Postoji, dakle, neprekinut niz koji se može pratiti od pojedinačnih zapisa nastalih pred Poslanikom ﷺ do primeraka razaslatih po pokrajinama.","headingId":"osnova-za-ono-sto-je-usledilo","headingText":"Osnova za ono što je usledilo"}]},{"slug":"Kako-je-Kuran-sakupljen-tacke-znaci-i-dve-zbirke","chunks":[{"text":"Ceo put teksta može se pratiti korak po korak. Zapisivanje je počelo odmah, uz Poslanikovu ﷺ neposrednu proveru. Prva zbirka bila je sređivanje već postojećih zapisa, a druga ujednačavanje pisma. Tačke i vokalizacijski znaci uvedeni su kasnije, i o njima nikada niko nije tvrdio da su deo objave.","headingId":"","headingText":""},{"text":"Kako je primedba postavljena Primedba se obično gradi tako što se sve navedeno stavi u jednu vreću: zapisivanje na razbacanom materijalu, dve zbirke, spaljivanje ličnih primeraka, kasnije dodavanje tačaka i znakova, sve to zajedno kao dokaz nesigurnosti. Postupak je pogrešan zato što meša različite vrste stvari. Zapis teksta, sređivanje zapisa, ujednačavanje pisma i uvođenje pomoćnih znakova četiri su različite radnje sa četiri različita predmeta. Nabrajanje jedne za drugom stvara utisak nagomilane nesigurnosti, iako svaka od njih, kada se ispita zasebno, pokazuje suprotno.","headingId":"kako-je-primedba-postavljena","headingText":"Kako je primedba postavljena"},{"text":"Prvi stepen za Poslanikovog ﷺ života Zapisivanje je počelo sa prvom objavljenom surom i trajalo kroz svih dvadeset i tri godine objave. Pisari su zapisivali neposredno po Poslanikovom ﷺ diktatu, a on je zapisano proveravao. Materijal je bio ono što je bilo dostupno: pergament, koža, plećke, palmino lišće. To se ponekad navodi kao slabost, ali je zapravo sporedno, jer glavni nosilac teksta nije bio zapis.","headingId":"prvi-stepen-za-poslanikovog-zivota","headingText":"Prvi stepen - za Poslanikovog ﷺ života"},{"text":"Uloga pamćenja Arapi su i pre islama imali razvijenu kulturu pamćenja, na kojoj je počivala njihova poezija i njihova plemenska predanja. Dva svojstva samog teksta pamćenje su dodatno olakšala: 1. Zvučna građa Kur'ana, sa krajevima ajeta koji se rimuju i ritmom koji se lako zadržava. 2. Postupnost objave , koja je zajednici omogućavala da pamti u delovima, tokom dve decenije, umesto odjednom.","headingId":"uloga-pamcenja","headingText":"Uloga pamćenja"},{"text":"Lanac slušanja Prenos je od početka bio usmen: od Džibrila Poslaniku ﷺ, od Poslanika ﷺ ashabima, i dalje.","headingId":"lanac-slusanja","headingText":"Lanac slušanja"},{"text":"Godišnje ponavljanje Svake godine Poslanik ﷺ je pred Džibrilom ponavljao ceo dotad objavljeni tekst. U godini svoje smrti učinio je to dvaput. To ponavljanje ima ulogu ustanovljene provere. Ono je utvrđivalo i tekst i redosled ajeta unutar sura, i to godišnje, pred svedocima koji su i sami znali tekst napamet.","headingId":"godisnje-ponavljanje","headingText":"Godišnje ponavljanje"},{"text":"Drugi stepen prva zbirka, u vreme Ebu Bekra Povod: pogibija velikog broja hafiza u bici kod Jemame. Predlog: Omer ibn el Hattab, radijallahu anhu. Izvršilac: Zejd ibn Sabit, radijallahu anhu. Priroda posla: sređivanje već postojećih zapisa u jednu uređenu celinu, a ne novo pisanje. Ishod: listovi su čuvani kod Ebu Bekra, zatim kod Omera, zatim kod Hafse, radijallahu anhum.","headingId":"drugi-stepen-prva-zbirka-u-vreme-ebu-bekra","headingText":"Drugi stepen - prva zbirka, u vreme Ebu Bekra"},{"text":"Treći stepen druga zbirka, u vreme Osmana Povod: razilaženje u učenju među stanovnicima različitih pokrajina, na koje je upozorio Huzejfa ibn el Jeman, radijallahu anhu, nakon pohoda na Jermeniju i Azerbejdžan. Odbor: Zejd ibn Sabit na čelu, uz Abdullaha ibn ez Zubejra, Sa'da ibn Ebu Vekkasa i Abdur Rahmana ibn el Harisa ibn Hišama, radijallahu anhum.","headingId":"treci-stepen-druga-zbirka-u-vreme-osmana","headingText":"Treći stepen - druga zbirka, u vreme Osmana"},{"text":"Zašto baš Zejd na čelu Zejd ibn Sabit spajao je četiri svojstva koja se retko nalaze zajedno: 1. Bio je jedan od pisara objave. 2. Bio je hafiz. 3. Prisustvovao je poslednjem ponavljanju pred Džibrilom. 4. Već je izvršio prvo sakupljanje, pa je posao poznavao iznutra.","headingId":"zasto-bas-zejd-na-celu","headingText":"Zašto baš Zejd na čelu"},{"text":"Metod Traženo je dvostruko potvrđivanje: postojanje zapisa nastalog pred Poslanikom ﷺ i svedočenje dvojice o tome da je tako i zapisano. Jedan izuzetak je zabeležen: svedočanstvo Ebu Huzejme el Ensarija, radijallahu anhu, računato je kao dva, na osnovu Poslanikove ﷺ ranije izjave o njemu.","headingId":"metod","headingText":"Metod"},{"text":"Ciljevi 1. Ujednačiti pismo, kako bi svi primerci bili istovetni. 2. Ukloniti povod za sporove među stanovnicima različitih pokrajina. 3. Zadržati zapis koji podnosi utvrđene načine učenja.","headingId":"ciljevi","headingText":"Ciljevi"},{"text":"Razlika između dve zbirke | | Prva zbirka | Druga zbirka | | | | | | Povod | Gubitak hafiza | Razilaženje u učenju | | Cilj | Sabrati zapise na jedno mesto | Ujednačiti pismo | | Ishod | Jedan skup listova | Primerci poslati u pokrajine | | Pitanje koje rešava | Da li je sve zapisano | Da li svi imaju isti zapis | Ova razlika često se previđa. Druga zbirka nije ponovila prvu niti je ispravljala. Ona je rešavala potpuno drugo pitanje. Predstavljati ih kao dva pokušaja istog posla, od kojih je prvi navodno bio neuspešan, jeste izvrtanje onoga što izvori kažu.","headingId":"razlika-izmedju-dve-zbirke","headingText":"Razlika između dve zbirke"},{"text":"Četvrti stepen tačke, znaci i oznake Ovo je stepen oko kojeg se stvara najviše zabune, iako je najmanje sporan.","headingId":"cetvrti-stepen-tacke-znaci-i-oznake","headingText":"Četvrti stepen - tačke, znaci i oznake"},{"text":"Tačke koje razlikuju slova Rano arapsko pismo pisalo je pojedina slova istim potezom, a razlikovala su se po položaju u reči i po kontekstu. Tačke koje razlikuju slova uveli su tabiini, a među imenima koja se navode su Ebul Esved ed Du'eli, Nasr ibn Asim el Lejsi, Jahja ibn Ja'mer i Halil ibn Ahmed.","headingId":"tacke-koje-razlikuju-slova","headingText":"Tačke koje razlikuju slova"},{"text":"Vokalizacijski znaci Fetha, damma, kesra i sukun uvedeni su kao pomoć onima kojima arapski nije bio maternji jezik, kako se u učenju ne bi grešilo.","headingId":"vokalizacijski-znaci","headingText":"Vokalizacijski znaci"},{"text":"Znaci za zastajanje U mushafu se koriste znaci koji učaču pokazuju gde je bolje zastati, a gde ne: | Znak | Značenje | | | | | صلى | Dopušteno je zastati, ali je bolje nastaviti | | قلى | Dopušteno je nastaviti, ali je bolje zastati | | ج | Zastajanje i nastavljanje jednako su dopušteni | | لا | Ne treba zastajati | | م | Zastajanje je obavezno |","headingId":"znaci-za-zastajanje","headingText":"Znaci za zastajanje"},{"text":"Ostale oznake Brojevi ajeta u kružićima, bismila između sura, i oznake mesta na kojima se čini sedžda. Ključno je sledeće: nijedan musliman nikada nije tvrdio da su te oznake deo objave. One su opšte priznate kao pomoćno sredstvo, uvedeno naknadno, uz saglasnost učenjaka. Navoditi ih kao dokaz izmene teksta znači optuživati za skrivanje ono što je od početka bilo javno i priznato. Ebu Amr ed Dani obradio je pitanje zapisa u El Mukni'u. Ebu Amr ed Dani, El Mukni', str. 129, priredio Muhammed es Sadik Kamhavi. Zerkeši i Sujuti obradili su ceo predmet u svojim delima o kur'anskim naukama. Ez Zerkeši, El Burhan fi ulumil Kur'an, 1/241 i dalje; Es Sujuti, El Itkan fi ulumil Kur'an.","headingId":"ostale-oznake","headingText":"Ostale oznake"},{"text":"Raspored sura Raspored sura u mushafu nije prema redosledu objavljivanja nego prema uputi datoj za Poslanikovog ﷺ života, što je potvrđivano i godišnjim ponavljanjem.","headingId":"raspored-sura","headingText":"Raspored sura"},{"text":"Poređenje kada je nastao tekst Tore Poređenje je ovde umesno, jer se primedba iznosi upravo iz suprotnog tabora. Will Durant postavio je pitanje o poreklu teksta Tore. Will Durant, The Story of Civilization, tom 2, str. 356 i 367, u prevodu Muhammeda Bedrana. Biblijski izveštaj sam opisuje da je rukopis Zakona pronađen u hramu za vladavine cara Josije, i to preko sveštenika Helkije, nakon dugog razdoblja u kojem se za njega nije znalo. Nakon vavilonskog izgnanstva, obnova teksta vezuje se za Ezru. Ovo poređenje treba čitati precizno. Ono ne tvrdi da je biblijski tekst bezvredan niti da su ti izveštaji nužno negativni. Ono ukazuje samo na jedno: da je razmak između Musaa, alejhis selam, i sačuvanog teksta neuporedivo veći, sa","headingId":"poredjenje-kada-je-nastao-tekst-tore","headingText":"Poređenje - kada je nastao tekst Tore"},{"text":"prekidima koje sam tekst priznaje, dok je kod Kur'ana razmak između objave i ujednačenog zapisa manji od dve decenije, bez prekida u prenosu.","headingId":"poredjenje-kada-je-nastao-tekst-tore","headingText":"Poređenje - kada je nastao tekst Tore"},{"text":"Zaključak 1. Zapisivanje je počelo odmah i teklo je uporedo sa objavom, uz Poslanikovu ﷺ proveru. 2. Pamćenje je bilo glavni nosilac, a zapis potpora, a ne obrnuto. 3. Prva zbirka sredila je postojeće zapise, uz dvostruku potvrdu. 4. Druga zbirka ujednačila je pismo i rešila drugo pitanje od prvog. 5. Tačke i znaci uvedeni su naknadno, javno, kao pomoć čitanju, i nikada nisu smatrani objavom.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Ko-je-prvi-sakupio-Kuran","chunks":[{"text":"Verodostojan izveštaj utvrđuje da je prvi sakupljanje naredio Ebu Bekr, a izvršio ga je Zejd ibn Sabit. Predaje koje prvenstvo pripisuju Aliji, Omeru ili Salimu imaju prekinute lance. Najzanimljivije je to što upravo Alija, dobrim lancem kod Ibn Ebu Davuda, prvenstvo pripisuje Ebu Bekru.","headingId":"","headingText":""},{"text":"Zašto je pitanje uopšte sporno U izvorima se nailazi na više izveštaja koji prvenstvo u sakupljanju Kur'ana pripisuju različitim ashabima. Deo tog prividnog razilaženja potiče otuda što reč sakupljanje u arapskoj upotrebi ima više značenja: može značiti naučiti napamet, može značiti prikupiti sopstvene listove u lični primerak, a može značiti i zvanično sakupljanje na nivou zajednice. Razlikovanje ta tri značenja rešava veći deo prividnog spora. Da je neko za sebe prikupio listove u lični primerak, to ne bi bilo isto što i zvanično sakupljanje po nalogu halife, sa svedocima i utvrđenim merilima.","headingId":"zasto-je-pitanje-uopste-sporno","headingText":"Zašto je pitanje uopšte sporno"},{"text":"Ebu Bekr verodostojan izveštaj Predaja Zejda ibn Sabita, radijallahu anhu, o pogibiji učača kod Jemame i o Omerovom predlogu Ebu Bekru, prenosi se verodostojnim lancem. Prema njoj, Omer ibn el Hattab upozorio je na gubitak hafiza, Ebu Bekr je nakon oklevanja prihvatio predlog, a posao je poveren Zejdu.","headingId":"ebu-bekr-verodostojan-izvestaj","headingText":"Ebu Bekr - verodostojan izveštaj"},{"text":"Alijino svedočanstvo Predaja preko Abdul Hajra, od Alije ibn Ebu Taliba, radijallahu anhu, prenosi se dobrim lancem i u njoj Alija Ebu Bekru pripisuje najveću nagradu za sakupljanje Kur'ana. Ibn Ebu Davud, Kitabul mesahif; Es Sujuti je lanac ocenio kao dobar. Ovo je odlučujuće za pitanje prvenstva. Onaj kome se u drugim predajama pripisuje prvenstvo sam ga, i to najboljim lancem od sve razmatrane građe, pripisuje Ebu Bekru. Njegovo svedočanstvo ide protiv njega samog, što mu daje dodatnu težinu.","headingId":"alijino-svedocanstvo","headingText":"Alijino svedočanstvo"},{"text":"Predaje koje prvenstvo pripisuju Aliji","headingId":"predaje-koje-prvenstvo-pripisuju-aliji","headingText":"Predaje koje prvenstvo pripisuju Aliji"},{"text":"Preko Muhammeda ibn Sirina U toj predaji stoji da Alija nije oblačio ogrtač osim za džumu dok nije sakupio Kur'an. Lanac je slab i prekinut. Ibn Hadžer je predaju ocenio kao slabu i prekinutu.","headingId":"preko-muhammeda-ibn-sirina","headingText":"Preko Muhammeda ibn Sirina"},{"text":"Preko Ikrime U toj predaji stoji da se Alija zavetovao da neće oblačiti ogrtač osim za namaz dok sakupljanje ne dovrši. Lanac je prekinut iz razloga koji se lako proverava: Ikrima je rođen 25. godine po Hidžri, a događaj se odigrao 11. godine po Hidžri. Ikrima, dakle, nije mogao svedočiti o događaju koji se odigrao četrnaest godina pre njegovog rođenja, a u lancu nema nikoga ko bi tu prazninu popunio. To nije sitna tehnička primedba nego prekid koji predaju čini neupotrebljivom za utvrđivanje prvenstva.","headingId":"preko-ikrime","headingText":"Preko Ikrime"},{"text":"Kod Ibn Aštea Ibn Ašte prenosi drugačiju verziju, u kojoj se navodi da je Alijino sakupljanje obuhvatalo i derogirajuće i derogirane ajete. Ibn Ašte, El Mesahif. To upravo potvrđuje razliku o kojoj je bilo reči na početku. Reč je o ličnom primerku sa dodatnim beleškama, a ne o zvaničnom mushafu zajednice.","headingId":"kod-ibn-astea","headingText":"Kod Ibn Aštea"},{"text":"Predaja koja prvenstvo pripisuje Omeru Preko Hasana prenosi se da je Omer naredio sakupljanje nakon što je saznao da je poginuo onaj ko je čuvao određeni ajet. Lanac je prekinut. Ibn Hadžer se osvrnuo na tumačenje te predaje i ukazao na to da se ona može razumeti u okviru poznatog izveštaja, dakle kao Omerov predlog Ebu Bekru, a ne kao zasebno prvenstvo. Ibn Hadžer.","headingId":"predaja-koja-prvenstvo-pripisuje-omeru","headingText":"Predaja koja prvenstvo pripisuje Omeru"},{"text":"Predaja koja prvenstvo pripisuje Salimu Preko Ibn Burejde prenosi se da je Salim, oslobođeni rob Ebu Huzejfe, radijallahu anhu, bio prvi koji je Kur'an sakupio u mushaf, i da se zavetovao da neće oblačiti ogrtač dok to ne dovrši. Sujuti je tu predaju ocenio kao prekinutu. Es Sujuti. Alusi je osporio Sujutijevu ocenu. Ebul Meali Mahmud Šukri el Alusi, umro 1342. po Hidžri. Ovde postoji stvarno razilaženje u ocenjivanju, i to treba reći otvoreno umesto prikazivati stvar jednostavnijom nego što jeste. Međutim, čak i da se prihvati Alusijeva ocena, ta predaja ne bi bila u sukobu sa Ebu Bekrovim prvenstvom, jer bi govorila o ličnom prikupljanju, a ne o zvaničnom sakupljanju sa svedocima i merilima provere.","headingId":"predaja-koja-prvenstvo-pripisuje-salimu","headingText":"Predaja koja prvenstvo pripisuje Salimu"},{"text":"Zaključak | Kome se pripisuje | Izvor predaje | Stanje lanca | | | | | | Ebu Bekr | Zejd ibn Sabit | Verodostojan | | Ebu Bekr | Abdul Hajr od Alije | Dobar | | Alija | Muhammed ibn Sirin | Slab i prekinut | | Alija | Ikrima | Prekinut | | Omer | Hasan | Prekinut | | Salim | Ibn Burejda | Prekinut, uz razilaženje u oceni | Kada se predaje poređaju po snazi lanaca, slika je jasna. Ono što je najbolje potvrđeno jeste Ebu Bekrovo prvenstvo, a to potvrđuje i sam Alija.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Kuran-4-82-i-deset-kiraeta","chunks":[{"text":"Prigovor da deset kiraeta protivreči ajetu En Nisa 4:82 pada na svakom nivou klasične kur'anske nauke. Ihtilaf se deli na tri vrste: ihtilaf protivrečnosti, ihtilaf nejednakosti i ihtilaf sklada. Prve dve vrste poriču se Kur'anu, dok razlika u kiraetima spada u treću, dakle u razliku raznolikosti, a ne suprotstavljanja.","headingId":"","headingText":""},{"text":"Ajet o kojem je reč Sura En Nisa 4:82 A zašto oni ne razmisle o Kur'anu? Da je on od nekog drugog, a ne od Allaha, sigurno bi u njemu našli mnoge protivrečnosti. Ajet postavlja merilo opovrgljivosti: da je Kur'an ljudskog porekla, unutrašnja protivrečnost bila bi uočljiva.","headingId":"ajet-o-kojem-je-rec","headingText":"Ajet o kojem je reč"},{"text":"Taberijev komentar Jer da je od nekog drugog, a ne od Boga, njegovi propisi bi se razlikovali, njegova značenja bi protivrečila jedno drugom, a jedni delovi bi otkrivali pokvarenost drugih. Izvor: Taberi. Taberi, Džamiul bejan. Katada, u Taberijevom prenosu, navodi: „Božiji govor se ne razlikuje, on je istina i u njemu nema laži, dok se govor ljudi razlikuje.\" Katada, preneseno kod Taberija.","headingId":"taberijev-komentar","headingText":"Taberijev komentar"},{"text":"Ibn Tejmijje i Ibn el Džezeri Među muslimanima nema spora o tome da sedam harfova na kojima je Kur'an objavljen ne povlače protivrečnost niti suprotstavljanje u značenju. Izvor: Ibn Tejmijje. Ibn Tejmijje. Razlika na koju se ovde misli jeste razlika raznolikosti i različitosti, a ne razlika suprotstavljanja i protivrečnosti. Izvor: Ibn el Džezeri. Ibn el Džezeri.","headingId":"ibn-tejmijje-i-ibn-el-dzezeri","headingText":"Ibn Tejmijje i Ibn el-Džezeri"},{"text":"Tri vrste ihtilafa kod Džessasa 1. Ihtilaf protivrečnosti , gde jedna od dve stvari iziskuje pokvarenost druge. 2. Ihtilaf nejednakosti , gde je jedan deo rečit, a drugi loš i bezvredan. 3. Ihtilaf sklada , dakle pozitivan vid raznolikosti u kojem sve ostaje usklađeno, poput razlike u načinima učenja i dužini ajeta. Prve dve vrste poriču se Kur'anu, i to je jedan od pokazatelja njegove čudesnosti. El Džessas. Do iste podele nezavisno dolazi i Dani, što pokazuje da nije reč o usamljenom stavu, nego o ustaljenom okviru u klasičnom tefsiru i nauci o kiraetima. Ed Dani.","headingId":"tri-vrste-ihtilafa-kod-dzessasa","headingText":"Tri vrste ihtilafa kod Džessasa"},{"text":"Ibn Kutejba Svi ti načini su govor Uzvišenog Boga, koje je Pouzdani Duh spustio Njegovom Poslaniku ﷺ. Postoje dve vrste razlike: razlika različitosti i razlika protivrečnosti. Razlika protivrečnosti nije dopuštena. Izvor: Ibn Kutejba. Ibn Kutejba.","headingId":"ibn-kutejba","headingText":"Ibn Kutejba"},{"text":"Zašto ajet kaže „mnoge\" Šejh Ibn Usejmin pojašnjava: Njegove reči „mnoge protivrečnosti\" objašnjavaju stvarnost onoga što je od nekog drugog, a ne od Boga. To nije uslov u smislu da bi, kada bi bio od Boga, u njemu našli malo protivrečnosti. Izvor: Ibn Usejmin. Ibn Usejmin. Zekerijja el Ensari objašnjava: „Ograničavanje na mnoštvo služi da se pojača dokazivanje veze, u smislu: da je od nekog drugog, a ne od Boga, u njemu bi našli mnoge protivrečnosti, a kamoli malo.\" Zekerijja el Ensari. Zejnudin er Razi zaključuje isto: „Odredba mnoštva služi naglašavanju nužne veze, kao da se kaže: da je od nekog drugog, a ne od Boga, u njemu bi našli mnoge protivrečnosti, a kamoli malo.\" Zejnudin er Razi.","headingId":"zasto-ajet-kaze-mnoge","headingText":"Zašto ajet kaže „mnoge\""},{"text":"Kurtubi o tome šta ajet isključuje To ne obuhvata razlike u izrazu kiraeta, u izrazu primera, u značenjima, niti u dužini sura i ajeta. Misli se na razliku protivrečnosti i nejednakosti. Izvor: Kurtubi. Kurtubi, El Džami li ahkamil Kur'an.","headingId":"kurtubi-o-tome-sta-ajet-iskljucuje","headingText":"Kurtubi o tome šta ajet isključuje"},{"text":"Ibn Ašur Ibn Ašur navodi dva moguća značenja ihtilafa: unutrašnju tekstualnu neusklađenost, ili protivrečnost između onoga što Kur'an otkriva o licemerima i same stvarnosti. O uslovnoj logici navodi: „Budući da je od Allaha, u njemu suštinski nema nikakve protivrečnosti.\" Ibn Ašur, Et Tahrir vet tenvir.","headingId":"ibn-asur","headingText":"Ibn Ašur"},{"text":"Dodatna korist kod Kirmanija Kirmani primećuje da to pobija one među rafidijama koji tvrde da se značenje Kur'ana ne može razumeti osim tumačenjem Poslanika ili imama. El Kirmani.","headingId":"dodatna-korist-kod-kirmanija","headingText":"Dodatna korist kod Kirmanija"},{"text":"Primer razlike u kiraetima Razlika između oblika miskin i mesakin dobar je primer razlike raznolikosti. Sura El Kehf 18:79 Što se one lađe tiče, ona je vlasništvo siromaha koji rade na moru. Jedno čitanje daje jedninu, a drugo množinu. Ta dva čitanja se ne isključuju, nego se dopunjuju: lađa je pripadala više siromaha, a među njima i pojedincu. Nijedno čitanje ne poriče ono drugo, pa nema ihtilafa protivrečnosti.","headingId":"primer-razlike-u-kiraetima","headingText":"Primer razlike u kiraetima"},{"text":"Zaključak Prigovor da deset kiraeta protivreči ajetu 4:82 pada, jer ajet poriče protivrečnost i nejednakost, a ne raznolikost. Razlika u kiraetima spada upravo u onu vrstu razlike koju klasična nauka naziva razlikom sklada.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Mentikut-tajr-i-jezicka-primedba","chunks":[{"text":"Tvrdi se da je glagol nataka u arapskom svojstven samo ljudima i da se ne može primeniti na ptice. To pobija svaki veliki arapski rečnik: El Mu'džemul vesit, El Muhit, El Gani i Muhtarus sihah svi navode upotrebu za ptice i za predmete koji proizvode zvuk. Zamahšeri u El Keššafu izričito kaže da se odnosi na sve čime se proizvodi zvuk.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Tvrdi se da je Kur'an načinio jezičku grešku upotrebivši izraz mentikut tajr, dakle govor ptica, jer da je glagol nataka svojstven samo ljudima i da se ne može primeniti na ptice ili životinje.","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Prvo šta kažu arapski rečnici Glagol nataka koristi se u klasičnom i savremenom arapskom i za ljude, i za ptice, pa i za nežive predmete. 1. El Mu'džemul vesit: „Kaže se: ptica je progovorila, ili: lauta je progovorila, u značenju: proizvela je zvuk.\" 2. El Muhit: „Ptica ili lauta proizvela je zvuk.\" 3. El Gani: „Ud je proizveo zvuk.\" 4. Muhtarus sihah: „I njihove reči: nije ni nem ni govoreći.\" 5. Rečnik savremenog arapskog: „Mentik je imenica izvedena od glagola govoriti, u značenju: govor, jezik, a može se upotrebiti i za ono što nije čovek.\" Mentik: sve čime se proizvode zvuci, bilo pojedinačni ili složeni, korisni ili ne. Izvor: Zamahšeri. Ez Zamahšeri, El Keššaf. Arapi su govorili: golub je progovorio,","headingId":"prvo-sta-kazu-arapski-recnici","headingText":"Prvo - šta kažu arapski rečnici"},{"text":"a svaka vrsta ptica razume svoje zvuke. El Bikai u Nazmud dureru navodi: „Razumevanje onoga što svaka ptica hoće kada proizvede zvuk, a mentik je ono čime ona proizvodi zvuk, bilo pojedinačno ili složeno.\" El Bikai, Nazmud durer.","headingId":"prvo-sta-kazu-arapski-recnici","headingText":"Prvo - šta kažu arapski rečnici"},{"text":"Drugo zašto mentik, a ne kelam Postavlja se i dalje pitanje: zašto je Kur'an upotrebio izraz mentikut tajr, sa imenicom mentik, umesto da jednostavno kaže kelamut tajr? Reč mentik nosi isto značenje kao nutk, dakle izgovor i govor, ali je mentik takozvani mimski masdar. Ono što mimski masdar razlikuje od običnog masdara jeste to što mimski masdar naglašava sam događaj koji opisuje i pojačava njegovo značenje preko onoga što prenosi obični masdar. Obični masdar označava apstraktan događaj, dok mimski masdar obavlja istu funkciju i više od toga, jer je njegovo ukazivanje na događaj snažnije, a značenje naglašenije. Upravo je to jedan od razloga zašto se mimski masdari često javljaju u Kur'anu. Izbor oblika mentik umesto kelam ili nutk, dakle, nije","headingId":"drugo-zasto-mentik-a-ne-kelam","headingText":"Drugo - zašto mentik, a ne kelam"},{"text":"slučajan, nego je namerno retoričko uzdizanje.","headingId":"drugo-zasto-mentik-a-ne-kelam","headingText":"Drugo - zašto mentik, a ne kelam"},{"text":"Ajet o kojem je reč Sura En Neml 27:16 I Sulejman naslede Davuda i reče: O ljudi, dato nam je da razumemo govor ptica i svašta nam je dato.","headingId":"ajet-o-kojem-je-rec","headingText":"Ajet o kojem je reč"}]},{"slug":"Muksit-i-kasit-jezicka-greska-u-tvrdnji-o-protivrecnosti","chunks":[{"text":"Tvrdnja o protivrečnosti počiva na tome da se dve različite arapske reči smatraju istom rečju. Muksit dolazi od četvrtog glagolskog oblika akseta, koji znači postupati pravedno. Kasit dolazi od prvog oblika kaseta, koji znači činiti nepravdu. Dva različita glagola, dva suprotna značenja, dve različite reči.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Iznosi se tvrdnja da Kur'an sam sebi protivreči, jer na jednom mestu kaže da Allah voli one koji su pravedni, a na drugom da oni koji su, navodno, isti ti, budu gorivo za Džehennem. Cela primedba počiva na tome što u latiničnoj transkripciji reči muksit i kasit deluju srodno.","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Ajeti o kojima je reč Sura El Maida 5:42 A ako im budeš sudio, sudi im pravedno; Allah, uistinu, voli pravedne. Sura El Hudžurat 49:9 I budite pravedni, Allah, zaista, pravedne voli. Sura El Džinn 72:15 A oni koji su skrenuli s Pravog puta, oni će gorivo za Džehennem biti.","headingId":"ajeti-o-kojima-je-rec","headingText":"Ajeti o kojima je reč"},{"text":"Razlika između dve reči Arapski jezik gradi značenja iz trosuglasničkih korena, a različiti glagolski oblici izvedeni iz istog korena mogu nositi i suprotna značenja. Akseta je četvrti glagolski oblik i znači postupati pravedno, suditi pravično, dati svakome njegovo pravo. Aktivni particip tog glagola je muksit , u množini muksitun , dakle pravednici. Akademija arapskog jezika u Kairu, El Mu'džemul vesit, treće izdanje, 1985. Kaseta je prvi glagolski oblik i znači činiti nepravdu, tlačiti, skrenuti s istine. Aktivni particip tog glagola je kasit , u množini kasitun , dakle nasilnici. Akademija arapskog jezika u Kairu, El Mu'džemul vesit, treće izdanje, 1985. Ova pojava u arapskom jeziku nije neobična. Četvrti glagolski oblik ponekad nosi takozvano oduzimajuće značenje, dakle znači ukloniti ono što","headingId":"razlika-izmedju-dve-reci","headingText":"Razlika između dve reči"},{"text":"prvi oblik označava. Kaseta znači činiti nepravdu, a akseta znači ukloniti nepravdu, odnosno postupati pravedno. To nisu dve upotrebe iste reči, nego dva različita glagola.","headingId":"razlika-izmedju-dve-reci","headingText":"Razlika između dve reči"},{"text":"Zašto primedba ne stoji Reči nisu iste ni u pisanju arapskim pismom, ni u izgovoru, ni u gramatičkom obliku. Da bi primedba imala ikakvu težinu, morala bi pokazati da Kur'an istu reč, u istom obliku, koristi u dva međusobno isključiva značenja u istom kontekstu. To ovde nije slučaj. Ono što izgleda kao sličnost postoji samo u pojednostavljenoj latiničnoj transkripciji, u kojoj se razlika između dva glagolska oblika gubi.","headingId":"zasto-primedba-ne-stoji","headingText":"Zašto primedba ne stoji"},{"text":"Zaključak Reč je o primedbi koja nastaje iz nepoznavanja arapske morfologije. Onaj ko pretpostavlja da su muksit i kasit ista reč, prvo bi trebalo da proveri iz kog glagola svaka od njih dolazi. Kada se to učini, cela tvrdnja o protivrečnosti nestaje.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Osam-tvrdnji-o-iskrivljenju-Kurana","chunks":[{"text":"Osam tvrdnji obrađenih ovde ne dele isti položaj. Neke počivaju na izmišljenim predajama, neke na verodostojnim predajama koje se pogrešno tumače, a neke na izvorima koji ne postoje. Zbog toga se ne mogu odbaciti jednim potezom, nego svaka mora biti ispitana zasebno, sa svojim izvorom i ocenom.","headingId":"","headingText":""},{"text":"Prva tvrdnja Abdul Melik ibn Mervan i El Fatiha Izvor: Zuhri prenosi da su rane halife učile malik , a da je Mervan uveo malik sa alifom, dakle maliki . Odgovor: Ibn Kesir je odbacio tu tvrdnju i naveo da je Mervan poznavao ispravan oblik. Ibn Kesir. Predaje od Umm Seleme, radijallahu anha, idu suprotno tvrdnji, a pojedine ukazuju na to da je Poslanik ﷺ učio upravo oblik koji se pripisuje kasnijoj izmeni. Presudno je stanje osmanskog zapisa. Taj zapis podnosi oba oblika istim potezom pera, jer alif u sredini reči u ranom pismu nije bio obavezan. Oba oblika su, dakle, priznata učenja unutar istog zapisa, a ne izmena teksta.","headingId":"prva-tvrdnja-abdul-melik-ibn-mervan-i-el-fatiha","headingText":"Prva tvrdnja - Abdul-Melik ibn Mervan i El-Fatiha"},{"text":"Druga tvrdnja Hadžadž ibn Jusuf Izvor: Abbad ibn Suhajb tvrdi da je Hadžadž promenio jedanaest slova u Osmanovom tekstu. Es Sidžistani, El Mesahif, str. 49. Odgovor: Abbada su odbacili svi vodeći hadiski kritičari. Buhari, Tirmizi, Ibn Hibban i Zehebi ocenili su ga kao odbačenog prenosioca. Predaja je, dakle, izmišljena. Zanimljivo je da je i šijski učenjak Ebul Kasim el Hui postavio isto pitanje: kako bi takve izmene mogle promaći istoričarima, hafizima i muslimanskim zajednicama razasutim na ogromnom prostoru. El Hui.","headingId":"druga-tvrdnja-hadzadz-ibn-jusuf","headingText":"Druga tvrdnja - Hadžadž ibn Jusuf"},{"text":"Treća tvrdnja dve dodatne sure kod Ubejja ibn Ka'ba Izvor: Više izveštaja, preko A'meša, Ibn Sirina i Abdur Rahmana ibn Ebzaa, navodi da je Ubejj ibn Ka'b, radijallahu anhu, u svom primerku imao još dve sure, El Hafd i El Hal'. Odgovor: Nijedan od tih izveštaja nije potvrđen verodostojnim lancem. Ti tekstovi javljaju se u kontekstu dove kunut, a ne u utvrđenim hadiskim zbirkama kao kur'anski tekst. Odlučujuće je sledeće: deset priznatih kiraeta koji vode do Ubejja ibn Ka'ba ne sadrže te dve sure. Da ih je on smatrao Kur'anom, prvi trag toga bio bi u učenjima koja se od njega prenose. Ebul Hasan el Ešari potvrdio je da se njegov primerak slagao sa utvrđenim tekstom.","headingId":"treca-tvrdnja-dve-dodatne-sure-kod-ubejja-ibn-kaba","headingText":"Treća tvrdnja - dve dodatne sure kod Ubejja ibn Ka'ba"},{"text":"Četvrta tvrdnja Ibn Mes'ud i dve poslednje sure Izvor: Zirr ibn Hubejš prenosi da je Ibn Mes'ud, radijallahu anhu, iz svog primerka izostavio sure El Felek i En Nas. Odgovor: Buharijeva predaja o tome je uopštena i ne sadrži izričitu izjavu, na šta je ukazao Ibn Hadžer. Ibn Hadžer. Više učenjaka, među kojima Nevevi, Ibn Hazm, Fahrudin er Razi i Bakillani, ocenilo je te izveštaje kao neuobičajene u samom tekstu predaje. Šest priznatih učača koji prenose od Ibn Mes'uda uključuju obe sure. Postoji i objašnjenje za samu prirodu njegovog primerka. Ibn Mes'ud nije zapisivao ceo tekst, nego one delove koje je čuo, a njegov primerak bio je lična beležnica, a ne mushaf zajednice. Izostanak nečega iz takvog primerka nije isto","headingId":"cetvrta-tvrdnja-ibn-mesud-i-dve-poslednje-sure","headingText":"Četvrta tvrdnja - Ibn Mes'ud i dve poslednje sure"},{"text":"što i poricanje.","headingId":"cetvrta-tvrdnja-ibn-mesud-i-dve-poslednje-sure","headingText":"Četvrta tvrdnja - Ibn Mes'ud i dve poslednje sure"},{"text":"Peta tvrdnja sura El Vilaja ili En Nurejn Izvor: Tvrdi se da je cela jedna sura izostavljena prilikom ujednačavanja. Odgovor: Za taj tekst ne postoji nijedan lanac prenošenja, čak ni slab. Ovo je najlakše proverljiva tačka u celom nizu. Onaj ko tvrdnju iznosi treba samo da navede lanac, bilo koji, ma koliko slab. Kada za nešto ne postoji ni slab lanac, to nije sporan materijal nego materijal koji ne postoji u predanju.","headingId":"peta-tvrdnja-sura-el-vilaja-ili-en-nurejn","headingText":"Peta tvrdnja - sura El-Vilaja ili En-Nurejn"},{"text":"Šesta tvrdnja hadis o petlu Izvor: Aiša, radijallahu anha, prenosi da su ajeti o kamenovanju i o dojenju bili na listu ispod njene postelje, i da je taj list nestao. Ibn Madže; Ed Darekutni; Et Taberani. Odgovor: Ibn Hazm je hadis ocenio kao verodostojan. Objašnjenje leži u derogaciji učenja: propisi su ostali poznati kroz pamćenje, a izgubljen je fizički list. Ibn Kutejba je obrazložio da je takav događaj u tadašnjim kućnim uslovima sasvim moguć. Ibn Kutejba. Ovde je važna razlika između lista i teksta. Gubitak jednog zapisanog lista ne dodiruje tekst koji hiljade ljudi znaju napamet. Ta razlika je upravo razlog zbog kojeg se ceo sistem prenosa oslanjao na pamćenje, a zapis koristio kao potporu.","headingId":"sesta-tvrdnja-hadis-o-petlu","headingText":"Šesta tvrdnja - hadis o petlu"},{"text":"Sedma tvrdnja jemenski rukopis Izvor: Nemački istraživači i članak Tobyja Lestera u The Atlantic Monthlyju iz januara 1999. godine, o starom jemenskom mushafu sa tragovima brisanja i pisanja preko. Toby Lester, The Atlantic Monthly, januar 1999. Odgovor: Tragovi ispravki u pojedinačnom rukopisu očekivana su pojava kod ručnog prepisivanja i sami po sebi ne govore o stanju teksta u zajednici. Verodostojnost teksta ne počiva na bilo kojem pojedinačnom rukopisu, nego na: 1. Istovetnosti teksta u svim muslimanskim krajevima istovremeno. 2. Neprekinutim lancima pamćenja. 3. Prenosu tumačenja uporedo sa tekstom. 4. Javnosti teksta, koja je svaku izmenu činila odmah primetnom. Metodološka primedba ovde je važnija od pojedinosti. Pojedinačan rukopis je jedan svedok. Kada jedan svedok protivreči mnoštvu međusobno nezavisnih svedoka, ispituje se","headingId":"sedma-tvrdnja-jemenski-rukopis","headingText":"Sedma tvrdnja - jemenski rukopis"},{"text":"taj jedan, a ne mnoštvo. Isto načelo primenjuje se u svakoj tekstualnoj kritici, pa i onoj koja se primenjuje na druge spise.","headingId":"sedma-tvrdnja-jemenski-rukopis","headingText":"Sedma tvrdnja - jemenski rukopis"},{"text":"Osma tvrdnja šijski izvori o El Vilaji i En Nurejnu Izvor: Delo Debistanul mezahib, koje se pripisuje Kejhusrevu Isfendijaru, nastalo u Indiji u sedamnaestom veku. Odgovor: En Nuri, koji se navodi kao glavni šijski izvor za to, sam je priznao da za taj tekst nije našao traga u šijskim knjigama. En Nuri. Delo El Mesalib, koje se navodi kao izvor i pripisuje Ibn Šehr Ašubu, istorijski ne postoji. Ajetullah Muhammed Hadi Ma'rifet nazvao je te tekstove grubim izmišljotinama, ukazujući na to da krše arapsku gramatiku. Muhammed Hadi Ma'rifet. Isfendijar je pripadao kejvanskoj sekti i prikupljao je ono što je čuo od običnog sveta, a et Tehrani je izneo mogućnost da je na taj tekst bilo i spoljašnjeg uticaja. Et Tehrani.","headingId":"osma-tvrdnja-sijski-izvori-o-el-vilaji-i-en-nurejnu","headingText":"Osma tvrdnja - šijski izvori o El-Vilaji i En-Nurejnu"},{"text":"Pregled | Tvrdnja | Na čemu počiva | Ishod ispitivanja | | | | | | Abdul Melik i El Fatiha | Zuhrijev izveštaj | Oba oblika su priznata učenja unutar istog zapisa | | Hadžadž | Abbad ibn Suhajb | Prenosilac odbačen kod svih kritičara | | Ubejjeve dve sure | Nepotvrđeni izveštaji | Nema verodostojnog lanca; kiraeti od njega ih nemaju | | Ibn Mes'ud | Zirr ibn Hubejš | Predaja uopštena; učenja od njega sadrže obe sure | | El Vilaja i En Nurejn | Ništa | Ne postoji nijedan lanac | | Hadis o petlu | Verodostojna predaja | Tačna, ali govori o listu, a ne o tekstu | | Jemenski rukopis | Jedan rukopis |","headingId":"pregled","headingText":"Pregled"},{"text":"Jedan svedok protiv mnoštva nezavisnih | | Debistanul mezahib | Delo iz 17. veka | Izvor koji navodi ne postoji; priznato i sa šijske strane |","headingId":"pregled","headingText":"Pregled"},{"text":"Zaključak Nijedna od osam tvrdnji ne opstaje kada joj se ispita izvor. Ono što ih povezuje nije zajednička građa nego zajednički postupak: iznošenje bez provere lanca i bez razlikovanja između ličnog primerka, derogiranog učenja i utvrđenog teksta.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Poslednje-ponavljanje-pred-Dzibrilom","chunks":[{"text":"Osmanovo sakupljanje imalo je jasno merilo, a ne proizvoljan izbor. U zapis je ušlo samo ono što je bilo potvrđeno u poslednjem ponavljanju pred Džibrilom, u godini Poslanikove ﷺ smrti. Ono što je do tada bilo derogirano nije uneseno. Zejd ibn Sabit, koji je poslu bio na čelu, tom ponavljanju je prisustvovao.","headingId":"","headingText":""},{"text":"Šta je bilo poslednje ponavljanje Svake godine Poslanik ﷺ je pred Džibrilom, alejhis selam, ponavljao dotad objavljeni tekst. U godini u kojoj je preselio, to ponavljanje obavljeno je dvaput. To poslednje ponavljanje imalo je tačno određenu ulogu: ono je utvrdilo konačno stanje teksta, sa svim derogacijama koje su do tada nastupile.","headingId":"sta-je-bilo-poslednje-ponavljanje","headingText":"Šta je bilo poslednje ponavljanje"},{"text":"Učenje ashaba bilo je jedno Ebu Abdur Rahman es Sulemi preneo je da je učenje ashaba bilo jedinstveno. El Begavi, Šerhus sunne, 4/525 526. Begavi, Ebu Muhammed el Husejn ibn Mes'ud el Ferra eš Šafi'i, umro 516. godine po Hidžri, priznati pravnik i znalac sunneta, preneo je i to da je Zejd ibn Sabit, radijallahu anhu, učio pred Poslanikom ﷺ. Tvrdnja da je učenje ashaba bilo jedno ne poriče postojanje utvrđenih razlika među harfovima. Ona se odnosi na to da među njima nije bilo suprotstavljenih tekstova niti spora o tome šta jeste, a šta nije Kur'an. Razlike o kojima je reč bile su unutar dopuštenog i sve su bile primljene, a ne suprotstavljene.","headingId":"ucenje-ashaba-bilo-je-jedno","headingText":"Učenje ashaba bilo je jedno"},{"text":"Zašto je to osnov osmanskog sakupljanja Kada je Osman, radijallahu anhu, okupio ljude za posao, izbor nije bio slučajan. Ibn Ebu Davud beleži da je okupio dvanaest ljudi iz Kurejša i ensarija, među kojima su bili Ubejj ibn Ka'b i Zejd ibn Sabit, radijallahu anhum. Ibn Ebu Davud, Kitabul mesahif, poglavlje o Osmanovom sakupljanju. Zejd ibn Sabit prisustvovao je poslednjem ponavljanju, i to je bio razlog zbog kojeg mu je posao poveren. Ovde se vidi da merilo nije bilo ni ugled, ni srodstvo, ni položaj. Merilo je bilo neposredno svedočenje konačnom stanju teksta. Onaj ko o tom stanju može svedočiti postavljen je na čelo, a ostali su bili provera njemu.","headingId":"zasto-je-to-osnov-osmanskog-sakupljanja","headingText":"Zašto je to osnov osmanskog sakupljanja"},{"text":"Šta je iz zapisa izostavljeno i zašto Iz zapisa je izostavljeno ono što u poslednjem ponavljanju nije bilo potvrđeno, dakle ono čije je učenje bilo derogirano. Izostavljeno je i ono što je kod pojedinih ashaba bilo zapisano uz tekst kao tumačenje. To znači da razlika između pojedinačnog primerka nekog ashaba i osmanskog mushafa nije dokaz da je nešto uklonjeno iz Kur'ana, nego pokazatelj da je merilo primenjeno. Ova pitanja obrađena su u klasičnim delima o kur'anskim naukama. Es Sujuti, El Itkan, 1/142; Ez Zerkeši, El Burhan, 1/237; El Ahrufus seb'a ve nuzulul kiraati minha, str. 270 271.","headingId":"sta-je-iz-zapisa-izostavljeno-i-zasto","headingText":"Šta je iz zapisa izostavljeno i zašto"},{"text":"Odgovor na tvrdnju o političkom potezu Iznosi se tvrdnja da je Osmanovo sakupljanje bilo politički potez radi nametanja jedinstva. Tri stvari govore protiv toga: 1. Merilo je bilo utvrđeno unapred , a ne prilagođavano ishodu. Traženo je slaganje sa poslednjim ponavljanjem, uz zapis i dva svedoka. 2. Sastav odbora bio je mešovit , iz Kurejša i iz ensarija, a ne skup ljudi iz jedne skupine. 3. Nije zabeleženo nijedno protivljenje među ashabima, uključujući one koji su prema Osmanu kasnije imali političke primedbe. Treća tačka je najteža za onoga ko iznosi tvrdnju o političkom potezu. Osman je kasnije bio predmet oštrih političkih prigovora, koji su prerasli u pobunu. Da je u postupanju sa mushafom bilo iole spornog, to bi bilo prvo","headingId":"odgovor-na-tvrdnju-o-politickom-potezu","headingText":"Odgovor na tvrdnju o političkom potezu"},{"text":"što bi mu se prigovorilo. Umesto toga, ni protivnici tu primedbu nisu izneli.","headingId":"odgovor-na-tvrdnju-o-politickom-potezu","headingText":"Odgovor na tvrdnju o političkom potezu"},{"text":"Pitanje Muhammeda ibn Sirina Muhammed ibn Sirin postavio je pitanje o razlozima odlaganja sakupljanja, i ono se ponekad navodi kao trag nesigurnosti. Reč je, međutim, o pitanju tumačenja postupka, a ne o osporavanju teksta. Postavljanje pitanja o tome zašto je nešto učinjeno tada, a ne ranije, jeste uobičajen naučni postupak i ne sadrži tvrdnju da je nešto pogrešno.","headingId":"pitanje-muhammeda-ibn-sirina","headingText":"Pitanje Muhammeda ibn Sirina"},{"text":"Zaključak Osmanovo sakupljanje bilo je primena jednog merila: ući u zapis može samo ono što je potvrđeno u poslednjem ponavljanju pred Džibrilom. To merilo objašnjava i šta je uneseno i šta nije, i čini nepotrebnim pretpostavku o proizvoljnom izboru.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Predaja-o-Omerovim-recima-o-tri-ajeta","chunks":[{"text":"Šejh Ahmed Šakir ocenio je predaju slabom zbog prekinutog lanca, jer Ubad ibn Abdullah nije prisustvovao sakupljanju Kur'ana, a najverovatnije nije ni sreo onoga od koga navodno prenosi. Isto je ocenio i šejh Šuajb el Arnaut. Utvrđena je Buharijeva predaja br. 4986, dok je ova neuobičajena i odstupajuća, i protivreči poznatom prenosu.","headingId":"","headingText":""},{"text":"Predaja o kojoj je reč Omer je rekao: Da su bila tri ajeta, načinio bih od njih zasebnu suru. Zato potražite suru iz Kur'ana i smestite ih u nju. Pa sam ih smestio na kraj sure Bera'a.","headingId":"predaja-o-kojoj-je-rec","headingText":"Predaja o kojoj je reč"},{"text":"Ocena Ahmeda Šakira Njen lanac je slab zbog prekida. Ubad ibn Abdullah je pouzdan, ali nije prisustvovao priči o sakupljanju Kur'ana. Štaviše, ne mislim da je sreo Harisa ibn Hurmu, a i da ga je sreo, hadis ne bi bio verodostojan, jer ga nije preneo od njega. Naprotiv, priču je preneo bez lanca prenošenja. Izvor: šejh Ahmed Šakir. Ahmed Šakir, provera hadisa Musneda, br. 1715. Hadis se nalazi kod Ibn Ebu Davuda, El Mesahif, str. 30, i kod Hejsemija u Medžmeuz zevaidu, gde je rekao: „Preneo ga je Ahmed, a u njemu je Ibn Ishak, koji čini tedlis, dok su ostali njegovi ljudi pouzdani.\" Ibn Ebu Davud, El Mesahif, str. 30; El Hejsemi, Medžmeuz zevaid. Ahmed Šakir je na to","headingId":"ocena-ahmeda-sakira","headingText":"Ocena Ahmeda Šakira"},{"text":"primetio: „Hafiz Hejsemi nije obratio pažnju na to da je predaja mursel.\" Ahmed Šakir. Šejh Šuajb el Arnaut naveo je: „Njen lanac prenošenja je slab.\" Šuajb el Arnaut.","headingId":"ocena-ahmeda-sakira","headingText":"Ocena Ahmeda Šakira"},{"text":"Šta je utvrđeno Ahmed Šakir naveo je da je utvrđeno ono što je preneo Buhari, br. 4986, u vezi sa poslednjim ajetima sure Bera'a. Ova predaja je, međutim, neuobičajena i odstupajuća, i protivreči utvrđenom i opštepoznatom prenosu u veri, a to je da je Kur'an Allahov Poslanik ﷺ preneo svome ummetu u poznatim, razgraničenim surama. Nije bilo na Omeru niti na bilo kome drugom da u Kur'anu bilo šta raspoređuje, da jedan ajet zamenjuje drugim, ili da samostalno sakuplja ajete i od njih pravi suru. To je i suštinski razlog zašto se ta predaja odbacuje: ona pretpostavlja ovlašćenje koje ashabi nisu ni imali ni tražili.","headingId":"sta-je-utvrdjeno","headingText":"Šta je utvrđeno"}]},{"slug":"Predaja-o-petlu-koji-je-pojeo-list","chunks":[{"text":"Predaja je odbačena i nije verodostojna, jer ide putem Muhammeda ibn Ishaka. Ahmed ibn Hanbel je izričito naveo da se hadis ne prihvata ako ga on jedini prenosi. Uz to, Kur'an je bio sačuvan u srcima, pa gubitak jednog lista ne bi mogao ništa oduzeti ni dodati. Sarahsi je primetio da se time ništa ne gubi iz srca onih koji su ga naučili napamet.","headingId":"","headingText":""},{"text":"Prvo usmeno očuvanje čini materijalni gubitak nevažnim Da je ta predaja tačna i da je jedan ajet Časnog Kur'ana izgubljen, zar muslimani ne bi mogli da napišu drugi list umesto onog koji je petao pojeo, tim pre što su u mushaf zapisali 6236 ajeta sa 77277 reči? Nijedan ajet Časnog Kur'ana nije objavljen a da se ashabi i Poslanik ﷺ nisu složili da ga nauče napamet. Zato to što je taj list pojeo petao ne može Kur'anu ništa oduzeti niti dodati, jer je on sačuvan u srcima. U tome je i suština. Prigovor pretpostavlja da je zapis bio jedini nosilac teksta. Ali kod Kur'ana zapis prati pamćenje, a ne obrnuto, pa uništenje jednog primerka ne dodiruje sam tekst.","headingId":"prvo-usmeno-ocuvanje-cini-materijalni-gubitak-nevaznim","headingText":"Prvo - usmeno očuvanje čini materijalni gubitak nevažnim"},{"text":"Drugo Poslanik ﷺ nije imao postelju Allahov Poslanik ﷺ nije imao postelju, jer se u verodostojnim predajama navodi da bi ustajao, a na mestu gde je spavao ostajali bi tragovi hasure. Nije, dakle, ni razumno da bi Kur'an stavljao ispod postelje, kada postelju uopšte nije ni imao.","headingId":"drugo-poslanik-nije-imao-postelju","headingText":"Drugo - Poslanik ﷺ nije imao postelju"},{"text":"Treće slabost lanca Ta predaja je odbačena i nije verodostojna, jer ide putem Muhammeda ibn Ishaka, od Abdullaha ibn Ebu Bekra, od Amre, od Aiše. Ako Ibn Ishak jedini prenosi neki hadis, prihvata li se? Rekao je: Ne, tako mi Allaha. Video sam ga kako prenosi jedan hadis od skupine, a nije razdvajao reči. Izvor: Ahmed ibn Hanbel. Ahmed ibn Hanbel, o Muhammedu ibn Ishaku. Sarahsi je naveo: „Aišin hadis teško da je verodostojan, jer se time ništa ne gubi iz srca onih koji su ga naučili napamet.\" Es Serahsi.","headingId":"trece-slabost-lanca","headingText":"Treće - slabost lanca"},{"text":"Tedlis Muhammeda ibn Ishaka Ista predaja javlja se i u obliku u kojem se navodi da je list pojela domaća životinja, kod Ibn Madže pod brojem 1944, i tu pada iz istog razloga. Muhammed ibn Ishak je po saglasnosti kritičara mudellis , dakle prenosilac koji prikriva svoje izvore, prenoseći izrazom an , bez izričitog navođenja da je čuo. Nesai ga je uvrstio među one koji nisu jaki. En Nesai, Ed Duafa vel metrukun, str. 211. Sujuti ga navodi među mudellisima i spominje Ibn Meinovo oslabljivanje. Es Sujuti, Esmaul mudellisin, str. 81 82. Ibn Hadžer i Šuajb el Arnaut potvrđuju tedlis uprkos opštim pohvalama koje je inače imao. Tahrir Takribit tehzib, tom 3, str. 211 212. Pravilo glasi: kada mudellis prenosi","headingId":"tedlis-muhammeda-ibn-ishaka","headingText":"Tedlis Muhammeda ibn Ishaka"},{"text":"izrazom an , njegova predaja nije dokaz dok se ne utvrdi da je tekst zaista čuo od onoga koga navodi. Albani je to pravilo izričito primenio i ovde. El Albani. Važno je razumeti zašto to pravilo postoji. Mudellis ne izmišlja tekst nego preskače karike u lancu. Ako je karika koju je preskočio bila slaba, cela predaja je slaba, a mi to iz zapisanog lanca ne možemo videti. Zato se od mudellisa traži izričito navođenje slušanja. To nije pooštravanje pravila radi ovog slučaja, nego opšte merilo koje se primenjuje na svakog prenosioca te vrste.","headingId":"tedlis-muhammeda-ibn-ishaka","headingText":"Tedlis Muhammeda ibn Ishaka"},{"text":"Ocene same predaje Alusi je taj sadržaj nazvao izmišljotinom. El Alusi, Ruhul meani, 11/140. Ibn Hazm ga je nazvao otvorenom laži. Ibn Hazm. Hemdani je predaju oslabio. El Hemdani.","headingId":"ocene-same-predaje","headingText":"Ocene same predaje"},{"text":"Verzija u Musnedu Postoji i verzija u Musnedu, ali ni ona ne prolazi. Šuajb el Arnaut odbacio je i nju, iz dva razloga: zato što je prenosi jedan jedini prenosilac, bez ijednog lanca koji bi ga potkrepio, i zbog problema u samom tekstu predaje. Musned Ahmed, tom 43, str. 342 343, uz napomene Šuajba el Arnauta.","headingId":"verzija-u-musnedu","headingText":"Verzija u Musnedu"},{"text":"Četvrto izgubljene knjige u samoj Bibliji Biblija i sama priznaje postojanje knjiga i poslanica koje su izgubljene, što priznaju i njeni sopstveni izučavaoci. 2. Kraljevima 22:8 Nađoh knjigu zakona u domu Gospodnjem. Brojevi 21:14 Zato se kaže u knjizi o ratovima Gospodnjim. 2. Samuilova 1:18 Eto, zapisano je u knjizi Pravednoga. 1. Korinćanima 5:9 Pisah vam u poslanici da se ne mešate s kurvarima. Reč je o poslanici koja nije sačuvana.","headingId":"cetvrto-izgubljene-knjige-u-samoj-bibliji","headingText":"Četvrto - izgubljene knjige u samoj Bibliji"}]},{"slug":"Predaja-o-planini-Kaf","chunks":[{"text":"Ibn Kesir tu predaju izričito svrstava u izmišljotine sinova Israilovih. Lanci koji se pripisuju Ibn Abbasu nisu verodostojni: u njima su nepoznati prenosioci, kao i Omer ibn Sabah, za kojeg Buhari prenosi da je priznao da je izmišljao, a kojeg su Ebu Hatim er Razi i Ibn Hibban ocenili odbačenim i izmišljačem.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Hrišćani tvrde da Kur'an sadrži mitove, pozivajući se na predaju koju prenose pojedini raniji učenjaci, a koja spominje zelenu planinu od dragog kamena koja okružuje Zemlju, poznatu kao planina Kaf.","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Prvo slovo kaf je jedno od skraćenih slova Slovo kaf jedno je od skraćenih slova koja stoje na početku sure Kaf. Prenosi se od nekih ranijih da su rekli: kaf se odnosi na planinu koja okružuje čitavu Zemlju, poznatu kao planina Kaf. To je, a Allah najbolje zna, među izmišljotinama sinova Israilovih. Izvor: Ibn Kesir. Ibn Kesir, Tefsirul Kur'anil azim. Ibn Kesir dalje navodi: „Kao što su ovom ummetu, uprkos njegovim velikim učenjacima, hafizima i imamima, lažno pripisivane laži na Poslanika ﷺ, zbog dužine vremena i prenošenja, koliko se to tek moglo dogoditi sinovima Israilovim?\" Ibn Kesir, isto delo. Ovo je ključno. Ta predaja nije kur'anski tekst niti hadis, nego tumačenje pojedinaca, koje je i sam Ibn Kesir označio kao","headingId":"prvo-slovo-kaf-je-jedno-od-skracenih-slova","headingText":"Prvo - slovo kaf je jedno od skraćenih slova"},{"text":"preuzeto iz izrailijjata. Prigovor se, dakle, ne odnosi na Kur'an, nego na odbačeno tumačenje.","headingId":"prvo-slovo-kaf-je-jedno-od-skracenih-slova","headingText":"Prvo - slovo kaf je jedno od skraćenih slova"},{"text":"Drugo slabost lanaca Predaje koje se pripisuju Ibn Abbasu u vezi sa planinom Kaf nisu verodostojne. Predaja iz dela El Azama od Isfahanija ide preko Mukatila ibn Hajjana, Ikrime i Ibn Abbasa, ali sadrži dve presudne mane: 1. Jedan prenosilac je nepoznat, a Halef ibn Mejmun ne može se potvrditi. 2. Omer ibn Sabah utvrđen je kao nepouzdan. Buhari prenosi njegovo priznanje: „Ja sam izmislio hutbu Poslanika ﷺ.\" Ebu Hatim er Razi i Ebu Ahmed ocenili su ga kao munkerul hadis, dakle odbačenim. Ebu Hatim ibn Hibban naveo je: „On izmišlja hadise i pripisuje ih pouzdanim prenosiocima.\" Ibn Hibban, o Omeru ibn Sabahu.","headingId":"drugo-slabost-lanaca","headingText":"Drugo - slabost lanaca"},{"text":"Zaključak Ta predaja počiva na nepouzdanim i osporenim izvorima i mora se odbaciti.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Razlike-u-rukopisima-odgovor-Brubakeru","chunks":[{"text":"Razlike koje postoje između pojedinih kur'anskih rukopisa i današnjeg teksta objašnjavaju se nenamernim prepisivačkim greškama, i to trima vrstama zabune: slušnom, vidnom i misaonom. Za razlikovanje nenamerne greške od namerne izmene postavljaju se četiri merila: sličnost, usamljenost čitanja, veličina razlike i odsustvo bilo kakve doktrinarne pobude.","headingId":"","headingText":""},{"text":"Tri vrste prepisivačke zabune 1. Slušna zabuna. Kada prepisivač piše rukopis po diktatu, čitač izgovori reč, a prepisivač je pogrešno čuje zbog glasovne sličnosti dve reči. Primer je zamena oblika jamelun oblikom jamehun. 2. Vidna zabuna. Javlja se u dva oblika: greška sličnih završetaka i greška sličnih početaka. 3. Misaona zabuna. Prepisivačev um zaokupljen je izrazom sličnim onome koji prepisuje, pa dolazi do nenamerne zamene. Budući da su prepisivači bili hafizi, mogli su pomešati ajete sličnog izraza.","headingId":"tri-vrste-prepisivacke-zabune","headingText":"Tri vrste prepisivačke zabune"},{"text":"Četiri merila za razlikovanje 1. Sličnost, dakle postojanje bliskog mesta u samom Kur'anu koje objašnjava zamenu. 2. Usamljenost čitanja, dakle to što se javlja samo u jednom rukopisu. 3. Veličina jedinice razlike. 4. Odsustvo bilo kakve doktrinarne pobude. Ovo poslednje merilo je ključno. Namerna izmena teksta pretpostavlja razlog: neko menja tekst da bi nešto dokazao ili sakrio. Ako se ne može pokazati nikakva korist od navodne izmene, tvrdnja o namernom iskrivljenju ostaje bez svoje osnovne pretpostavke.","headingId":"cetiri-merila-za-razlikovanje","headingText":"Četiri merila za razlikovanje"},{"text":"Rukopisi o kojima je reč 1. Sanski rukopis br. 1, sa kraja prvog veka 2. MS.474.2003 3. BnF Arabe 341 4. Rukopis iz Topkapi saraja 5. NLR Marcel 8 6. MIA.2014.491, Muzej islamske umetnosti u Dohi 7. BnF Arabe 340","headingId":"rukopisi-o-kojima-je-rec","headingText":"Rukopisi o kojima je reč"},{"text":"Sanski rukopis primer misaone zabune Kur'anski tekst glasi: Sura Et Tevba 9:80 Molio ti oprost za njih ili ne molio, molio čak i sedamdeset puta, Allah im neće oprostiti. U rukopisu izostaje izraz „sedamdeset puta\". To se objašnjava misaonom zabunom sa bliskim mestom: Sura El Munafikun 63:6 Isto im je, molio ti oprosta za njih ili ne molio, Allah im, zaista, neće oprostiti.","headingId":"sanski-rukopis-primer-misaone-zabune","headingText":"Sanski rukopis - primer misaone zabune"},{"text":"Rukopis MS.474.2003 Prepisivač je počeo da piše oblik jušrikun, „od onoga što pridružuju\", a zatim se ispravio i napisao jesifun, „od onoga što opisuju\". Delimično zadržan oblik reči i sama ispravka u istom potezu jesu upravo ono što se očekuje kod nenamerne greške. Namerni krivotvoritelj ne ostavlja trag sopstvenog kolebanja na pergamentu. Uz to, čitanje iz rukopisa na tom mestu daje gramatički nesuvislu rečenicu, neusklađenu sa okolnim tekstom, što takođe upućuje na grešku, a ne na nameru.","headingId":"rukopis-ms4742003","headingText":"Rukopis MS.474.2003"},{"text":"Primedba o korenu r z k Brubaker izdvaja ispravke na rečima iz korena ر ز ق. Odgovara se poređenjem učestalosti grešaka kod drugih korena, poput خ ل ق, koji se odnosi na stvaranje, kao i kod same reči Allah, gde se javljaju slični obrasci. Broj deset, dakle, sam po sebi ništa ne dokazuje, jer se isti obrazac javlja i kod reči za koje niko ne tvrdi da su menjane.","headingId":"primedba-o-korenu-r-z-k","headingText":"Primedba o korenu r-z-k"},{"text":"Pojedinačni primeri","headingId":"pojedinacni-primeri","headingText":"Pojedinačni primeri"},{"text":"BnF Arabe 341, El Bekara 2:60 Slova kaf i fa u osnovi se pišu istovetno, pa smislena zamena nije ni bila moguća. Kao objašnjenje se predlaže probijanje mastila sa poleđine lista, sa reči bima.","headingId":"bnf-arabe-341-el-bekara-260","headingText":"BnF Arabe 341, El-Bekara 2:60"},{"text":"Rukopis iz Topkapi saraja, El Bekara 2:25 Da li je ovo bila obična prepisivačka greška zbog ponavljanja rasm oblika slova fa? Izvor: IQSA, novembar 2016, str. 4. IQSA, novembar 2016, str. 4.","headingId":"rukopis-iz-topkapi-saraja-el-bekara-225","headingText":"Rukopis iz Topkapi saraja, El-Bekara 2:25"},{"text":"NLR Marcel 8, El A'raf 7:160 Predlaže se misaona zabuna sa El Bekarom 2:57, koja je gotovo istovetna, ali koristi oblik alejkum umesto alejhim.","headingId":"nlr-marcel-8-el-araf-7160","headingText":"NLR Marcel 8, El-A'raf 7:160"},{"text":"MIA.2014.491 Izbrisano područje veće je od sadašnjeg teksta, što se pripisuje zabuni sa dužim uporednim izrazom o namazu i zekatu.","headingId":"mia2014491","headingText":"MIA.2014.491"},{"text":"Primedba na preostale primere Za preostale primere navodi se da su predstavljeni isečenim slikama koje onemogućavaju poređenje, da se ne nudi nikakva pobuda za navodno iskrivljenje, i da se ne pruža nikakav dokaz o tome šta je u tekstu stajalo pre brisanja.","headingId":"primedba-na-preostale-primere","headingText":"Primedba na preostale primere"},{"text":"Zaključak 1. Za obrazac sa korenom r z k ne nudi se nikakvo suvislo objašnjenje. 2. Nijedan primer nije potkrepljen sa više rukopisa. 3. Isti koren ostaje netaknut na drugim mestima u tim istim rukopisima. 4. Postoji razlika između namernih čitanja i ispravljenih grešaka. Različite pojedinačne ispravke iste reči, u različitim tekstovima i različitim rukopisima, nisu odgovor na pitanje usamljenih čitanja. Izvor: Razlike u kur'anskim rukopisima, prof. Ahmed eš Šami","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Razlozi-sakupljanja-Kurana-u-vreme-Osmana","chunks":[{"text":"Povod nije bila sumnja u tekst nego posledica širenja države. Ashabi su se razišli po pokrajinama, stanovnici svakog kraja naučili su učenje svog učitelja, a tek kada su se vojske iz udaljenih krajeva srele u istom pohodu, otkrilo se da jedni drugima ne priznaju ono što nisu čuli. Spor je zamalo prerastao u sukob.","headingId":"","headingText":""},{"text":"Prvi razlog širenje države Nakon osvajanja, ashabi su se razišli po pokrajinama: u Šam, u Irak, u Egipat, u Jemen. Svaki od njih podučavao je stanovnike svog kraja onom učenju koje je sam primio. Stanovnici svake pokrajine tako su naučili jedno učenje, i to učenje jedino i poznavali. Ovde treba biti precizan oko toga šta se zapravo dogodilo. Nijedan od tih učitelja nije podučavao nešto pogrešno. Svaki je prenosio ono što je primio, a sve što su prenosili bilo je utvrđeno. Problem nije nastao u onome što se učilo, nego u tome što niko nije čuo ono što je učio drugi.","headingId":"prvi-razlog-sirenje-drzave","headingText":"Prvi razlog - širenje države"},{"text":"Drugi razlog spor je počeo da se prenosi Ebu Kilaba opisuje kako su razilaženja rasla, prelazeći sa učitelja na učenike. Ibn Ebu Davud, Kitabul mesahif. Jezid ibn Muavija en Nehai svedoči o sporu u džamiji oko učenja jednog mesta u suri El Bekara. Ibn Ebu Davud, Kitabul mesahif. Ono što je zabrinjavalo nije bila razlika sama po sebi, nego to što su pojedini počeli jedni druge da optužuju za grešku, pa i za nevernstvo. Prenosi se da je Alija ibn Ebu Talib, radijallahu anhu, za taj spor rekao da je blizu nevernstvu. Ibn Ebu Davud, Kitabul mesahif.","headingId":"drugi-razlog-spor-je-poceo-da-se-prenosi","headingText":"Drugi razlog - spor je počeo da se prenosi"},{"text":"Treći razlog pohod na Jermeniju i Azerbejdžan Ovo je bio neposredan povod. Dvadeset i pete godine po Hidžri, u pohodu na Jermeniju i Azerbejdžan, susrele su se vojske iz Šama i iz Iraka. Huzejfa ibn el Jeman, radijallahu anhu, video je razliku u učenju između stanovnika Šama i stanovnika Iraka, i spor koji je iz toga nastao. Sahih Buhari, Knjiga o vrednostima Kur'ana. Vratio se Osmanu, radijallahu anhu, i zatražio da se stvar reši pre nego što se zajednica raziđe u Knjizi kao što su se razišli oni pre njih. Isti događaj prenose i Zejd ibn Sabit i Enes ibn Malik, radijallahu anhuma. Et Tahavi, Te'vilu muškilil asar; prenos Ibn Šihaba. Vojni pohod bio je mesto na kojem se stvar","headingId":"treci-razlog-pohod-na-jermeniju-i-azerbejdzan","headingText":"Treći razlog - pohod na Jermeniju i Azerbejdžan"},{"text":"morala pokazati, jer je jedino tamo bilo ljudi iz svih krajeva na jednom mestu. To objašnjava zašto se problem pojavio tek tada, iako je nastajao godinama. Do tada nije postojala prilika da stanovnici udaljenih pokrajina čuju jedni druge.","headingId":"treci-razlog-pohod-na-jermeniju-i-azerbejdzan","headingText":"Treći razlog - pohod na Jermeniju i Azerbejdžan"},{"text":"Šta je Osman učinio Zatražio je listove od Hafse, radijallahu anha, i dao da se po njima prepišu primerci. Odredio je da se zapiše jedan harf, kurejšijski, koji je bio okvir za utvrđena učenja. Poslao je primerke u pokrajine, i uz svaki od njih učača koji je ljude podučavao učenju. Naredio je da se ostali primerci povuku iz upotrebe, kako bi se uklonio povod sporu.","headingId":"sta-je-osman-ucinio","headingText":"Šta je Osman učinio"},{"text":"Kako je to primljeno Nije zabeleženo nijedno protivljenje među ashabima. Alija ibn Ebu Talib izjavio je da bi, da Osman to nije učinio, on to sam učinio. Ova izjava je važna zbog onoga što se kasnije dogodilo. Osman je postao predmet oštrih političkih prigovora koji su prerasli u pobunu i njegovo ubistvo. Da je u postupanju sa mushafom bilo iole spornog, to bi bilo prvo što bi mu se prigovorilo. Umesto toga, ta stavka nije se pojavila ni kod njegovih protivnika. O ovim događajima pisali su i Zehebi, Mekki ibn Ebu Talib, Ibn Hadžer, Ibn es Sem'ani i Jakut.","headingId":"kako-je-to-primljeno","headingText":"Kako je to primljeno"},{"text":"Šta ovaj događaj pokazuje Prigovarači ga navode kao dokaz nesigurnosti. Kada se pogleda šta se u njemu zaista dogodilo, on pokazuje suprotno: 1. Zajednica je razliku odmah primetila. Nije prošla nezapaženo niti je bila prikrivena. 2. Reagovalo se odmah , a ne nakon naraštaja. 3. Merilo je bilo utvrđeno , a ne izmišljeno u tom trenutku: traženi su zapis nastao pred Poslanikom ﷺ i svedoci. 4. Postupak je bio javan i prihvaćen bez protivljenja.","headingId":"sta-ovaj-dogadjaj-pokazuje","headingText":"Šta ovaj događaj pokazuje"},{"text":"Zaključak Osmanovo sakupljanje bilo je odgovor na posledicu širenja države, a ne na sumnju u tekst. Ono što se navodi kao dokaz nesigurnosti zapravo je zabeležen slučaj u kojem je zajednica razliku prepoznala, o njoj otvoreno raspravljala i rešila je po utvrđenom merilu, u roku od jedne generacije od objave.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Rec-vaki-i-elif-u-rukopisima","chunks":[{"text":"Drevne kur'anske rukopise treba čitati prema izgovoru njihovog vremena, a ne prema današnjem pravopisu. Kur'an se oduvek prenosio i usmeno, sa naraštaja na naraštaj, pa pravopisna razlika u rukopisima nikada nije uticala na izgovor. Prisustvo ili odsustvo dugog elifa u reči vaki, dakle, nije iskrivljenje.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Tvrdi se da je reč vaki u Kur'anu iskrivljena, jer se u pojedinim rukopisima piše sa dugim elifom, a u drugima bez njega.","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Prvo drevni pravopis Drevni kur'anski rukopisi pisani su prema drevnim pravopisnim načinima i drevnim oblicima arapskog pisma. Te drevne rukopise treba čitati prema izgovoru njihovog vremena, a ne prema našem sadašnjem izgovoru.","headingId":"prvo-drevni-pravopis","headingText":"Prvo - drevni pravopis"},{"text":"Primeri drevnih pravopisnih običaja 1. Udvojena slova pisana jednom. U drevnom pravopisu udvojeno slovo često se pisalo samo jednom, iako se izgovaralo udvojeno. 2. Dugi elif i mesni izgovor. Pisanje ili izostavljanje dugog elifa zavisilo je od pravopisne prakse, a ne od izgovora.","headingId":"primeri-drevnih-pravopisnih-obicaja","headingText":"Primeri drevnih pravopisnih običaja"},{"text":"Pravopisna razlika nije iskrivljenje Obe skupine čitaju istu reč istim izgovorom, čak i kada je pišu drugačije. To se vidi i danas. U savremenom arapskom svetu postoje mesne pravopisne razlike u pisanju istih reči, a izgovor ostaje isti. Isto važi i za reč zina, koja se u različitim krajevima piše na više načina, uz nepromenjen izgovor.","headingId":"pravopisna-razlika-nije-iskrivljenje","headingText":"Pravopisna razlika nije iskrivljenje"},{"text":"Načelo Kur'an se oduvek čuvao usmeno, prenosio se sa naraštaja na naraštaj glasom, a pravopisna razlika u rukopisima nikada nije uticala na izgovor. To je suština odgovora. Pisani zapis kod Kur'ana nije jedini nosilac teksta, nego oslonac usmenom prenosu. Zato pravopisna razlika u rukopisu ne dodiruje sam tekst, jer se tekst prenosi i nezavisno od zapisa.","headingId":"nacelo","headingText":"Načelo"},{"text":"Zaključak Prisustvo ili odsustvo dugog elifa u reči vaki, u različitim kur'anskim rukopisima, nije iskrivljenje, nego pravopisna razlika koja ne dodiruje izgovor niti značenje. Izvorni tekst na ovom mestu ne navodi imena, datume niti oznake pojedinih rukopisa, nego govori o drevnim rukopisima uopšteno.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Sedam-harfova","chunks":[{"text":"Arapska plemena imala su prepoznate razlike u izgovoru, izrazu i gramatičkoj upotrebi, koje su učenjaci nazivali lugat, dakle jezici. Objava Kur'ana uzela je u obzir tu jezičku stvarnost, naročito zbog plemena nenaviklih na kurejšijsko narečje, i to kroz sedam harfova. Hadis o Omeru i Hišamu ibn Hakimu potvrđuje da je sam Poslanik ﷺ odobrio različita učenja.","headingId":"","headingText":""},{"text":"Arapska narečja i pojam lugat U klasičnim arapskim raspravama reč لغة ne označava nužno potpuno odvojene jezike, poput arapskog naspram persijskog. Ona može označavati plemenska narečja, obrasce izgovora, gramatičke upotrebe ili prepoznate jezičke navike pojedinih arapskih plemena.","headingId":"arapska-narecja-i-pojam-lugat","headingText":"Arapska narečja i pojam lugat"},{"text":"Farahidi o jezicima Arapa Uzvišeni Allah objavio je Kur'an na jeziku svakog roda među Arapima. Izvor: El Farahidi. El Farahidi, El Džumel fin nahv. Ta prilagođenost očuvala je čudesnu rečitost Kur'ana i jedinstvo značenja, uz istovremeno uvažavanje jezičke raznolikosti.","headingId":"farahidi-o-jezicima-arapa","headingText":"Farahidi o jezicima Arapa"},{"text":"Kur'an i narečja Izrazi koji kasnijim čitaocima deluju neobično bili su zapravo ispravni kod prepoznatih arapskih plemena. Budući da su pravila arapske gramatike naknadno izvedena iz Kur'ana, govora i poezije, prosuđivati Kur'an po pojednostavljenim kasnijim pravilima znači zanemariti širu jezičku stvarnost. Ono što deluje kao greška može biti zakonita narečna upotreba.","headingId":"kuran-i-narecja","headingText":"Kur'an i narečja"},{"text":"Sedam harfova kao olakšica Uzvišeni Allah objavio je Svoju Knjigu Svome Poslaniku ﷺ na sedam harfova, kao olakšicu Svome ummetu, naročito onim plemenima koja nisu bila navikla na kurejšijsko narečje. Harfovi predstavljaju odobrenu prilagodljivost tokom objave, a ne svođenje na sedam narečja.","headingId":"sedam-harfova-kao-olaksica","headingText":"Sedam harfova kao olakšica"},{"text":"Hadis o Omeru i Hišamu ibn Hakimu Čuo sam Hišama ibn Hakima kako uči suru El Furkan drugačije nego što me je Poslanik ﷺ podučio. Obojica smo pred Poslanikom proučili svoje verzije. Poslanik je obe potvrdio, rekavši za svako učenje: Ovako je objavljeno. Zatim je rekao: Doista je Kur'an objavljen na sedam harfova, pa učite ono što vam je lakše. Izvor: Omer ibn el Hattab. Malik, El Muvetta, br. 472; Sahih Buhari; Sahih Muslim; Sunen Nesai. Ista predaja nalazi se i u Sahihu Buharije, sa naglaskom: „Doista je ovaj Kur'an objavljen na sedam harfova.\" Time se potvrđuje da je sam Poslanik ﷺ podučavao i odobravao te načine učenja.","headingId":"hadis-o-omeru-i-hisamu-ibn-hakimu","headingText":"Hadis o Omeru i Hišamu ibn Hakimu"},{"text":"Objašnjenje Poslanik ﷺ tražio je olakšicu u pogledu učenja jer su u ummetu bili i starci, i deca, i ljudi različitih sposobnosti učenja. Sedam harfova predstavljalo je milost i olakšicu, a ne protivrečnost ili iskrivljenje, uz očuvanje značenja i božanskog porekla.","headingId":"objasnjenje","headingText":"Objašnjenje"},{"text":"Tri klasična razvrstavanja razlika Učenjaci su pokušali da odrede koje su to vrste razlika obuhvaćene sedmoricom harfova.","headingId":"tri-klasicna-razvrstavanja-razlika","headingText":"Tri klasična razvrstavanja razlika"},{"text":"Ibn el Džezeri | Br. | Vrsta razlike | | | | | 1 | Razlika u samoglasniku, bez promene značenja i oblika | | 2 | Razlika u samoglasniku koja menja značenje, ali ne oblik | | 3 | Razlika u slovima koja menja značenje, ali ne oblik | | 4 | Razlika u obliku, bez promene značenja | | 5 | Zamena reči ili slova | | 6 | Razlika u redosledu, pomeranje unapred ili unazad | | 7 | Razlika u dodavanju ili izostavljanju |","headingId":"ibn-el-dzezeri","headingText":"Ibn el-Džezeri"},{"text":"Razi | Br. | Vrsta razlike | | | | | 1 | Oblici imenice jednina, dvojina, množina, rod | | 2 | Glagolski oblici i pripisivanje radnje | | 3 | Padežni završeci | | 4 | Dodavanje i izostavljanje | | 5 | Redosled reči | | 6 | Zamena slova ili reči | | 7 | Narečja izgovor, naginjanje, naglašavanje |","headingId":"razi","headingText":"Razi"},{"text":"Ibn Kutejba | Br. | Vrsta razlike | | | | | 1 | Padežni završeci bez promene oblika i značenja | | 2 | Gramatička analiza koja menja značenje, ali ne oblik | | 3 | Razlika u slovima bez promene završetaka | | 4 | Razlika koja menja i oblik i značenje | | 5 | Razlika u obliku bez promene značenja | | 6 | Razlika u redosledu reči | | 7 | Dodavanje i izostavljanje | Poklapanje ova tri spiska zanimljivije je od njihovih razlika. Trojica učenjaka iz različitih razdoblja, radeći nezavisno, došla su do gotovo istih kategorija. To ukazuje na to da razvrstavanje nije naknadno smišljeno da bi se nešto objasnilo, nego da opisuje građu","headingId":"ibn-kutejba","headingText":"Ibn Kutejba"},{"text":"koja im je stvarno bila pred očima.","headingId":"ibn-kutejba","headingText":"Ibn Kutejba"},{"text":"Pravna korist razlika Ovo je deo koji se najčešće previđa, a najviše govori. Razjašnjenje nejasnog propisa. Pitanje nasleđivanja u slučaju kelale razjašnjava se poređenjem dvaju oblika učenja. Spajanje dva propisa. Kod propisa o čišćenju nakon menstruacije, dva oblika učenja daju dva uslova koja se zajedno primenjuju. Dva propisa za dve situacije. Kod abdesta, dva oblika učenja odnose se na pranje u jednom slučaju i potiranje u drugom. Otklanjanje pogrešnog zaključka. Kod naredbe o odlasku na džumu, jedan oblik učenja isključuje pogrešno razumevanje o načinu odlaska. Ova tačka obrće smer prigovora. Ako razlike među učenjima pružaju pravnu korist, razjašnjavaju višeznačnosti i međusobno se dopunjuju, onda one nisu tragovi kvara nego uređena građa. Kvar ne razjašnjava propise nego ih zamagljuje.","headingId":"pravna-korist-razlika","headingText":"Pravna korist razlika"},{"text":"Šta sedam harfova ne znači 1. Ne znači sedam kiraeta. Priznatih kiraeta ima deset, a ne sedam, i njihov broj nastao je kasnije, iz izbora imama učača. 2. Ne znači da svaka reč ima sedam oblika. Razlike su prisutne na različitim mestima, a ne na svakom mestu istovremeno. 3. Ne znači sedam različitih tekstova. Reč je o vrstama razlike unutar istog teksta.","headingId":"sta-sedam-harfova-ne-znaci","headingText":"Šta sedam harfova ne znači"},{"text":"Zaključak Arapska plemena imala su prepoznate razlike u narečjima, koje su klasični gramatičari nazivali lugat. Objava Kur'ana uzela je u obzir tu jezičku raznolikost kroz sedam harfova. Hadis o Omeru i Hišamu potvrđuje da je Poslanik ﷺ odobrio različita učenja, i da to nisu kasnije izmišljotine. Sedam harfova, dakle, jača, a ne slabi očuvanje Kur'ana, jer pokazuje božanski dopuštenu jezičku raznolikost unutar jedne sačuvane objave.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Svedocanstva-orijentalista-o-ocuvanju-teksta","chunks":[{"text":"Vrednost ovih svedočanstava nije u tome što potvrđuju islamsko učenje o objavi, jer ga većina navedenih autora nije prihvatala. Vrednost je u tome što se ljudi suprotstavljenih polazišta slažu oko jednog uskog i proverivog pitanja: da je tekst kroz rukopisni prenos ostao stabilan.","headingId":"","headingText":""},{"text":"Kako čitati ovaj pregled Pre svega treba biti pošten prema onome što ovi navodi jesu i prema onome što nisu. Nijedan od navedenih autora nije time prihvatio da je Kur'an Božija objava. Većina njih zadržala je oštro kritički stav prema islamu u celini, a pojedini su pisali i otvoreno neprijateljski. Njihove izjave odnose se isključivo na jedno pitanje: na stabilnost teksta kroz vekove prepisivanja. Predstavljati ih kao priznanje poslanstva bilo bi izvrtanje. Upravo zbog toga te izjave imaju težinu. Kada neko ko ima razloga da nađe zamerku ne nalazi je na određenom mestu, to o tom mestu govori više nego pohvala saveznika.","headingId":"kako-citati-ovaj-pregled","headingText":"Kako čitati ovaj pregled"},{"text":"Pregled | Autor | Delo | O čemu svedoči | | | | | | Laura Veccia Vaglieri | Odbrana islama, str. 58 59 | Tekst je ostao neizmenjen, a pamti ga mnoštvo ljudi | | Bosworth Smith | Navedeno delo, str. 69 | Knjiga jedinstvena po verodostojnosti i celovitosti | | Elwood Morris Wherry | Commentary of the Quran, tom 1, str. 349 | Najtačniji i najverodostojniji od svetih spisa | | Nasri Salhab | Susret hrišćanstva i islama, str. 337 | Nijedna knjiga pre štampe nije čuvana sa toliko pažnje | | Rom Landau | Islam and the Arabs, str. 296 297 | Tekst je stigao netaknut kroz Osmanovu redakciju | | William Muir | The Life of","headingId":"pregled","headingText":"Pregled"},{"text":"Mahomet, str. 22 23, izdanje iz 1912. | Tekst očuvan preko dvanaest vekova bez izmene | | Stanley Lane Poole | Selection from the Quran | Nema izmena kroz trinaest vekova | | Reynold A. Nicholson | A Literary History of the Arabs, str. 143 | Verodostojnost teksta van svake sumnje | | Edward Henry Palmer | The Qur'an, uvod, str. 70 | Osmanov tekst ostao je merodavan bez izuzetka | | R. V. C. Bodley | The Messenger, str. 6 | Jedino delo nepromenjeno preko dvanaest vekova | | Enciklopedija Britanika | odrednica o Muhammedu ﷺ | Najviše učena knjiga na svetu | | Thomas Walker Arnold | The Islamic Faith, str. 9 | Tekst sadrži stvarne Poslanikove ﷺ","headingId":"pregled","headingText":"Pregled"},{"text":"reči | | Ernest Renan | Napomene o istorijama religija | Sačuvan bez najmanje izmene | | Basanta C. Bose | navedena dela | Nije ni postojala prilika za izmenu |","headingId":"pregled","headingText":"Pregled"},{"text":"Zašto se ti autori slažu Njihovo slaganje ne počiva na verskom uverenju nego na građi koja im je bila pred očima. Prvo , rukopisni nalazi. Rani rukopisi koji su im bili dostupni slagali su se međusobno u tekstu, za razliku od stanja u rukopisnoj tradiciji drugih spisa, u kojoj su se navikli na obiman aparat varijanti. Drugo , uporedno pamćenje. Tekst nije prenosila samo pisarska struka nego i mnoštvo ljudi koji su ga znali napamet, što je stvorilo dvostruku kontrolu kakva drugde ne postoji. Treće , kratkoća razmaka. Između objave i ujednačenog zapisa proteklo je manje od dve decenije, a između zapisa i najstarijih sačuvanih rukopisa gotovo ništa.","headingId":"zasto-se-ti-autori-slazu","headingText":"Zašto se ti autori slažu"},{"text":"Zašto to nisu obična pozajmljena mišljenja Navedeni autori nisu do svojih zaključaka došli oslanjajući se na muslimanske izvore. Oni su primenili istu tekstualno kritičku metodologiju kojom su se bavili biblijskim rukopisima: upoređivanje rukopisa, praćenje porodica tekstova, izdvajanje varijanti i njihovo razvrstavanje po vrsti. To je važno zbog očekivanja s kojima su prilazili. Ta škola razvila se upravo na traženju tragova izmene u tekstu, i u tome je bila uspešna kod drugih spisa. Kada isti postupak, u istim rukama, na ovom tekstu ne daje isti ishod, razlika nije u postupku nego u građi.","headingId":"zasto-to-nisu-obicna-pozajmljena-misljenja","headingText":"Zašto to nisu obična pozajmljena mišljenja"},{"text":"Šta ovaj argument ne dokazuje Ovaj argument ima jasnu granicu i treba je poštovati. On pokazuje da je tekst koji danas imamo isti onaj koji je zapisan u sedmom veku. On ne pokazuje, i ne može pokazati, da je taj tekst od Boga. To je zasebno pitanje, sa zasebnim dokazima. Ograničenost tvrdnje ovde je prednost, a ne slabost. Tvrdnja koja ostaje unutar onoga što građa podnosi teže se obara od tvrdnje koja tu granicu prekorači.","headingId":"sta-ovaj-argument-ne-dokazuje","headingText":"Šta ovaj argument ne dokazuje"},{"text":"Zaključak Sporovi o poreklu i tumačenju Kur'ana i dalje traju i biće ih dokle god bude ljudi. Ali pitanje da li je tekst kroz vekove ostao isti nije spor između vera nego pitanje koje se rešava rukopisima i uporednim čitanjem. O tom pitanju se, kako pregled pokazuje, slažu i oni kojima to nije bilo u interesu.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Taskentski-rukopis-i-prikrivene-ispravke","chunks":[{"text":"Taškentski primerak se Osmanu samo pripisuje. Iznesene slike prikrivaju tragove uobičajenih prepisivačkih ispravki, koje su u nauci o rukopisima poznata i priznata pojava. Uz to, uz to iznošenje nije priložena dokumentacija rukopisa, poput pečata, potpisa ili isprave, što je osnovno pravilo te nauke.","headingId":"","headingText":""},{"text":"Prvo gde se rukopis zaista nalazi Taj Kur'an je zaista bio u Samarkandu, ali je prenet u Sankt Peterburg, a sada se nalazi u Taškentu. Rukopis koji se vezuje za Osmana ibn Affana nalazi se u Kairu, dok se taškentski primerak njemu samo pripisuje. To je prva stvar koju treba razlučiti. Rasprava se vodi o primerku koji nosi pripisivanje, a ne o utvrđenom Osmanovom mushafu, pa se zaključci sa jednog ne mogu preneti na drugi.","headingId":"prvo-gde-se-rukopis-zaista-nalazi","headingText":"Prvo - gde se rukopis zaista nalazi"},{"text":"Drugo nauka o proveri rukopisa Sve drevne knjige pisane su rukom, jer tada nije bilo štampe. Jedan od načina ispravljanja, kada dođe do izostavljanja, jeste da se izostavljeno dopiše na margini, bilo pri dnu bilo sa strane. Navode se tri traga ispravki koji su prikriveni: 1. Linija povučena kroz slovo elif u jednoj reči. 2. Mala uspravna slova u ajetu o zabranjenim životinjama. 3. Slova koja su ostala vidljiva nakon pokušaja isecanja slike. Suština je u tome što su tragovi ispravki uobičajena i priznata pojava u rukopisnoj tradiciji. Prikazati ih kao skriveno otkriće moguće je samo ako se izostavi kontekst nauke o rukopisima, u kojoj je margina upravo mesto na koje se ispravka i dopisuje.","headingId":"drugo-nauka-o-proveri-rukopisa","headingText":"Drugo - nauka o proveri rukopisa"},{"text":"Treće izostala dokumentacija Jedno od načela te nauke jeste da istraživač uz svoje istraživanje objavi i dokumentaciju rukopisa. Dokumentacija se obično nalazi na prvoj ili poslednjoj strani rukopisa, u vidu pečata, potpisa ili isprave o rukopisu.","headingId":"trece-izostala-dokumentacija","headingText":"Treće - izostala dokumentacija"},{"text":"Četvrto poređenje sa izvornim taškentskim rukopisom Izvorni rukopis odlikuje se osobenim kufskim pismom, uz razlike u vođenju poteza i u rukopisu pisara u odnosu na verziju koja se iznosi.","headingId":"cetvrto-poredjenje-sa-izvornim-taskentskim-rukopisom","headingText":"Četvrto - poređenje sa izvornim taškentskim rukopisom"}]},{"slug":"Tvrdnja-da-je-El-Ahzab-imala-dvesta-ajeta","chunks":[{"text":"Sve navedene predaje su slabe: prva zbog Ibn Lehie, druga zbog Abdullaha ibn Šerika el Amirija, treća preko Jezida ibn Ebu Zijada i Asima ibn Behdele. Sujuti ih u El Itkanu izričito svrstava pod ono čije je učenje derogirano, a propis ostao. Uz to, Kur'an iziskuje neprekinut masovan prenos, a ne pojedinačne vesti.","headingId":"","headingText":""},{"text":"Prva predaja od Aiše Sura El Ahzab učila se u vreme Poslanika ﷺ u dvesta ajeta, a mi smo bili u stanju proučiti samo ono što sada imamo. Izvor: El Itkan, 3:82. Es Sujuti, El Itkan, 3:82. U lancu je Ibn Lehia, kojeg su učenjaci oštro kritikovali. 1. Buhari je naveo da ga je Jahja ibn Seid napustio. 2. Ibn Mehdi je rekao: „Ja od njega ništa ne prenosim.\" 3. Ibn Mein je rekao: „Bio je slab i njegov hadis nije pouzdan.\" 4. Džuzdžani je zaključio: „Na njegov hadis ne treba se oslanjati.\"","headingId":"prva-predaja-od-aise","headingText":"Prva predaja - od Aiše"},{"text":"Druga predaja od Huzejfe Proučio sam suru El Ahzab Poslaniku ﷺ i zaboravio sam sedamdeset ajeta iz nje koje nisam našao. Izvor: Ed Durrul mensur, 6:559. Es Sujuti, Ed Durrul mensur, 6:559. U lancu je Abdullah ibn Šerik el Amiri, koji je sporan među učenjacima. 1. Džuzdžani ga je nazvao lažljivcem. 2. Nesai je naveo da nije jak. 3. Ibn Hibban je ukazao na njegove krajnje šijske sklonosti, navodeći da je „od pouzdanih prenosilaca prenosio ono što ne liči na hadis pouzdanih\".","headingId":"druga-predaja-od-huzejfe","headingText":"Druga predaja - od Huzejfe"},{"text":"Treća predaja od Omera, Ubejja ibn Ka'ba i Ikrime Ubejj ibn Ka'b izvestio je da je sura El Ahzab bila bliska po dužini suri El Bekara i da je sadržala ajet o kamenovanju. Es Sujuti, El Itkan, 3:82. Lanci koji idu preko Jezida ibn Ebu Zijada i Asima ibn Behdele su slabi. Ibn Mein je za Jezida rekao: „Slab je u hadisu.\" Ibn Sa'd je za Asima naveo: „Bio je pouzdan, osim što je često grešio u svom hadisu.\"","headingId":"treca-predaja-od-omera-ubejja-ibn-kaba-i-ikrime","headingText":"Treća predaja - od Omera, Ubejja ibn Ka'ba i Ikrime"},{"text":"Tumačenje derogacija učenja Imam Sujuti te predaje izričito svrstava pod naslov „Ono čije je učenje derogirano, a propis nije\". Es Sujuti, El Itkan fi ulumil Kur'an. Izraz „učili smo\" upravo ukazuje na derogirane ajete. Omer je sa minbera rekao: „Kamenovanje je u Allahovoj Knjizi, obaveza onima koji počine blud ako su u braku.\" Treba primetiti šta predaje o Omeru zapravo sadrže. One govore isključivo o ajetu o kamenovanju, a ne o dužini sure. Povezivanje tih predaja sa tvrdnjom o dvesta ajeta jeste spajanje dveju različitih stvari.","headingId":"tumacenje-derogacija-ucenja","headingText":"Tumačenje - derogacija učenja"},{"text":"Razilaženje među učenjacima Pojedini učenjaci odbacuju samu mogućnost derogacije učenja uz zadržavanje propisa. Zerkeši je naveo: „Nemoguće je derogirati učenje, a da propis ostane, jer se propis ne utvrđuje bez učenja.\" Ez Zerkeši. Ibn Hadžer je ukazao da Kur'an iziskuje neprekinut masovan prenos, a ne pojedinačne vesti. Ibn Hadžer.","headingId":"razilazenje-medju-ucenjacima","headingText":"Razilaženje među učenjacima"},{"text":"Sažetak 1. Predaja od Aiše je slaba zbog nepouzdanosti Ibn Lehie. 2. Predaja od Huzejfe je slaba zbog spornog položaja Abdullaha ibn Šerika el Amirija. 3. Predaje koje se pripisuju Omeru odnose se samo na ajet o kamenovanju, a ne na dužinu sure. 4. Predaja od Ubejja ibn Ka'ba slaba je preko Jezida ibn Ebu Zijada i Asima ibn Behdele, a i kada bi se prihvatila, označavala bi derogaciju učenja. Nema, dakle, nikakvog dokaza o gubitku ili iskrivljenju kur'anskog teksta koji se prenosi masovnim prenosom.","headingId":"sazetak","headingText":"Sažetak"}]},{"slug":"Tvrdnja-da-je-Ibn-Abbas-rekao-da-je-pisar-pogresio","chunks":[{"text":"Nijedna od dvadeset pet predaja koje se navode nije verodostojna. U njihovim lancima stoje lažljivci, nepoznati prenosioci, ljudi koji nikada nisu sreli one od kojih navodno prenose, i hronološki nemoguće veze. Jedna od njih je čak štamparska greška, jer sporni izraz uopšte ne postoji u izvornom rukopisu. Uz to, nekoliko tih predaja zapravo potvrđuju ispravnost kur'anskog oblika teste'nisu.","headingId":"","headingText":""},{"text":"Ajet o kojem je reč Sura En Nur 24:27 O vernici, u tuđe kuće ne ulazite dok dopuštenje ne dobijete i dok ukućane ne pozdravite. U ajetu stoji oblik teste'nisu. Tvrdi se da je Ibn Abbas rekao da bi trebalo da stoji teste'zinu i da je posredi pisarska greška.","headingId":"ajet-o-kojem-je-rec","headingText":"Ajet o kojem je reč"},{"text":"Kurtubijeva ocena To nije ispravno od Ibn Abbasa niti od drugih. Izvor: Kurtubi. El Kurtubi, El Džami li ahkamil Kur'an.","headingId":"kurtubijeva-ocena","headingText":"Kurtubijeva ocena"},{"text":"Pregled slabosti tih predaja Predaje se mogu razvrstati po vrsti mane:","headingId":"pregled-slabosti-tih-predaja","headingText":"Pregled slabosti tih predaja"},{"text":"Prekinuti lanci 1. Džafer ibn Ijas nije ništa čuo od Mudžahida. Šu'be je izričito naveo: „Džafer ibn Ijas nije ništa čuo od Mudžahida, to je samo zapis.\" Ni Buhari ni Muslim nisu uvrstili njegove predaje od Mudžahida. 2. Lanac koji ide do Seida ibn Džubejra prekida se kod njega i ne doseže do Ibn Abbasa. 3. Alija ibn Ebu Talha nikada nije čuo od Ibn Abbasa, o čemu postoji saglasnost hadiskih učenjaka.","headingId":"prekinuti-lanci","headingText":"Prekinuti lanci"},{"text":"Lažljivci u lancu 1. Džabir ibn Jezid el Džu'fi zabeležen je kao lažljivac čije predaje učenjaci odbacuju. 2. Hammad ibn es Saib el Kelbi je zabeležen lažljivac, a Ebu Salih je priznao: „Sve što sam preneo bila je laž.\" 3. Džuvejbir ibn Seid el Belhi optužen je za laž, a njegov hadis se odbacuje. 4. Jakub ibn Ishak el Muharrami, kojeg su oslabili Darekutni i Ebul Husejn ibn el Munadi.","headingId":"lazljivci-u-lancu","headingText":"Lažljivci u lancu"},{"text":"Nepoznati prenosioci 1. Bejheki je jednu predaju preneo preko nepoznatog šejha, a prenosilac Ebu Nasr ibn Katada ostaje neutvrđen. 2. Muaz ibn Sulejman je jednostavno nepoznat, pa se o njegovoj pouzdanosti ništa ne zna.","headingId":"nepoznati-prenosioci","headingText":"Nepoznati prenosioci"},{"text":"Hronološki nemoguće veze 1. Seid ibn Mensur umro je 227. godine po Hidžri, a Bejheki je rođen 384. godine, dakle 157 godina kasnije. 2. Ibrahim en Nehai rođen je oko 47. godine, a Abdullah ibn Mes'ud umro je 32. godine. 3. A'meš je rođen 61. godine, a Ibn Mes'ud umro je 32. godine. 4. Ubejj ibn Ka'b umro je 30. godine, a Ikrima je rođen najranije 25. godine, pa od njega nije mogao čuti.","headingId":"hronoloski-nemoguce-veze","headingText":"Hronološki nemoguće veze"},{"text":"Prenošenje po sećanju Ebu Avana je prenosio po sećanju. Ebu Hatim er Razi naveo je: „Njegove knjige su ispravne, ali kada bi prenosio po sećanju, često je grešio.\" Vredi obratiti pažnju: upravo ta predaja Ebu Avane glasi „Traženje dozvole znači traženje dozvole, kako mislim, pa pisari u tome nisu pogrešili.\" Ona, dakle, poriče grešku, iako se navodi kao dokaz za nju.","headingId":"prenosenje-po-secanju","headingText":"Prenošenje po sećanju"},{"text":"Štamparska greška U štampanom izdanju Bejhekijevog dela Šuabul iman stoji izraz o pisarevoj grešci. Napomena u izdanju Er Rušd navodi: „Ono što je u zagradama izostavljeno je iz izvornika.\" Taj izraz, dakle, uopšte ne postoji u izvornom rukopisu, nego su ga slagači pogrešno dodali.","headingId":"stamparska-greska","headingText":"Štamparska greška"},{"text":"Predaje koje potvrđuju ispravnost teksta Nekoliko predaja zapravo pokazuje suprotno od onoga radi čega se navode. U njima Ibn Abbas ukazuje na to da su pisari u udaljenim krajevima odstupali i pisali teste'zinu umesto ispravnog teste'nisu. To, dakle, nije greška u Kur'anu, nego greška prepisivača u dalekim oblastima, koja protivreči mushafu ashaba.","headingId":"predaje-koje-potvrdjuju-ispravnost-teksta","headingText":"Predaje koje potvrđuju ispravnost teksta"},{"text":"Ocene učenjaka Ko god je preneo da je Ibn Abbas to rekao, taj napada islam i novotar je u veri, a Ibn Abbas je čist od te izjave. Učači nisu preneli nijedno drugo učenje osim teste'nisu. Izvor: Ez Zerkani. Ez Zerkani, Menahilul irfan fi ulumil Kur'an, 1/388. Prof. dr Arefa ibn Tantavi naveo je: „Prenošenje toga od Ibn Abbasa nije verodostojno.\" Arefa ibn Tantavi, 1/284. Sam Bejheki je, nakon što je preneo te dve predaje, prokomentarisao: „Opšte učenje dokazano je neprekinutim prenosom, pa je ono preče.\" El Bejheki, Šuabul iman.","headingId":"ocene-ucenjaka","headingText":"Ocene učenjaka"},{"text":"Svedočanstvo kiraeta Kanonski učači koji su učenje primili neposredno od Ibn Abbasa, dakle Ebu Amr, Ibn Kesir i Nafi, svi uče teste'nisu. Nijedan od sedmorice kanonskih učača ne uči teste'zinu.","headingId":"svedocanstvo-kiraeta","headingText":"Svedočanstvo kiraeta"},{"text":"Drugi deo primedbe značenje reči teste'nisu Prigovor glasi: kako traženje bliskosti može prethoditi pozdravu i ulasku? Odgovor je da bliskost ovde znači nastojanje da se razume stanje onoga u čiju kuću želite ući. Kada pokucate na vrata i domaćin izađe, prvo čitate njegovo lice i izraz: da li mu je drago vaše društvo ili je u nekoj neprilici. Posmatrate izraz lica, glas i pokrete. Ako osetite da je zauzet ili da ne želi društvo, ne treba da ulazite, nego da odete, kako mu ne biste bili teret.","headingId":"drugi-deo-primedbe-znacenje-reci-testenisu","headingText":"Drugi deo primedbe - značenje reči teste'nisu"},{"text":"Zaključak Nijedna od navedenih predaja nije verodostojna. Zajedno gledano, one sadrže lažljivce i izmišljače u lancu, nepoznate prenosioce, prenosioce koji nikada nisu sreli one od kojih navodno prenose, prenosioce čiji se hadis prihvata samo iz njihovih knjiga a koji su ovde prenosili po pokvarenom sećanju, štamparske greške dodate u rukopise u kojima sporni izraz ne postoji, a u više slučajeva i predaje koje zapravo potvrđuju ispravnost kur'anskog teksta.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Tvrdnja-da-je-Merjem-bila-udata-za-Josifa","chunks":[{"text":"Glagol ahsanet ne znači „udala se\". Njegovo osnovno jezičko značenje jeste sačuvati, zaštititi, utvrditi. Iz tog osnovnog značenja izvode se tri različita posebna značenja, a koje od njih važi na nekom mestu, određuje isključivo kontekst. Taberi izričito navodi da se na oba mesta koja se spominju o Merjem radi o čednosti.","headingId":"","headingText":""},{"text":"Sadržaj tvrdnje Kadijanije tvrde da je Merjem, alejhes selam, bila udata za Josifa drvodelju, i to izvode iz kur'anskog glagola ahsanet , koji se, po njihovom tumačenju, odnosi na udaju. Ta tvrdnja im je potrebna kao deo šireg pokušaja da se Isaovo, alejhis selam, rođenje svede na uobičajeno rođenje.","headingId":"sadrzaj-tvrdnje","headingText":"Sadržaj tvrdnje"},{"text":"Ajeti o kojima je reč Sura El Enbija 21:91 A i onu koja je sačuvala devičanstvo svoje, u njoj život udahnusmo i nju i sina njezina znamenjem svetovima učinismo. Sura Et Tahrim 66:12 I Merjemu, kćer Imranovu, koja je nevinost svoju sačuvala, a Mi smo u njeno telo život udahnuli.","headingId":"ajeti-o-kojima-je-rec","headingText":"Ajeti o kojima je reč"},{"text":"Osnovno značenje korena Koren h s n u arapskom jeziku nosi značenje utvrđivanja i zaštite. Otuda i reč hisn , tvrđava, i tahsin , utvrđivanje. Glagolski oblik ahsanet doslovno znači: sačuvala je, zaštitila je, utvrdila je. To je ključna tačka. Značenje udaje nije osnovno značenje tog korena, nego jedno od izvedenih. Onaj ko iz oblika ahsanet odmah izvodi udaju, preskače osnovno značenje i bira jedno od izvedenih, i to bez ikakvog razloga iz konteksta.","headingId":"osnovno-znacenje-korena","headingText":"Osnovno značenje korena"},{"text":"Tri izvedena značenja reči muhsana Reč muhsana u kur'anskoj upotrebi nosi, zavisno od konteksta, jedno od tri značenja: 1. Čednost žena koja je sebe sačuvala. 2. Brak žena koju brak štiti. 3. Sloboda slobodna žena, nasuprot ropkinji. Sva tri značenja izviru iz iste osnove: reč je o nekome ili nečemu što je zaštićeno. Razlikuju se samo po tome čime je zaštita ostvarena.","headingId":"tri-izvedena-znacenja-reci-muhsana","headingText":"Tri izvedena značenja reči muhsana"},{"text":"O ajetu En Nisa 4:24 Sura En Nisa 4:24 I udate žene, osim onih koje zarobite. Tvrdi se da su svi učenjaci saglasni da muhsanat na tom mestu znači udate žene, pa se odatle izvodi da ta reč uvek znači udatu. Ta tvrdnja o saglasnosti nije tačna. Među priznatim pravnicima tabiina bilo je razilaženja o tome šta reč na tom mestu tačno obuhvata, a među njima se navode Ubejda ibn Amr i Tavus ibn Kejsan. Et Taberi, Džami'ul bejan. I kada bi saglasnost o tom mestu postojala, ona ne bi ništa dokazivala. Da reč u jednom kontekstu znači jedno, ne znači da u svakom kontekstu znači isto. Upravo je to greška u zaključivanju na kojoj cela tvrdnja počiva.","headingId":"o-ajetu-en-nisa-424","headingText":"O ajetu En-Nisa 4:24"},{"text":"Taberijev stav Taberi navodi da je izvorno jezičko značenje te reči zaštita i sprečavanje, i da to osnovno značenje obuhvata sva izvedena. Za oba mesta koja se odnose na Merjem, dakle za 66:12 i 21:91, Taberi izričito navodi da je značenje čednost. Et Taberi, Džami'ul bejan, uz komentar sura El Enbija i Et Tahrim.","headingId":"taberijev-stav","headingText":"Taberijev stav"},{"text":"Zašto kontekst isključuje udaju Oba ajeta u istoj rečenici nastavljaju time da je u nju udahnut život i da su ona i njen sin znamenje svetovima. Ako bi se ahsanet razumelo kao udaja, ajet bi glasio da se udala, pa je zato u nju udahnut duh i zato je postala znamenje. To ne bi bilo nikakvo znamenje, jer u rođenju deteta unutar braka nema ničega neobičnog. Sam kur'anski opis, dakle, isključuje to tumačenje. Ono što se navodi kao znamenje jeste upravo to da je začeće nastupilo bez muškarca.","headingId":"zasto-kontekst-iskljucuje-udaju","headingText":"Zašto kontekst isključuje udaju"},{"text":"Zaključak Tvrdnja počiva na jednom glagolu kojem se pripisuje jedno od njegovih izvedenih značenja, i to ono koje kontekst izričito isključuje. Osnovno značenje korena, tumačenje Taberija i sama građa ajeta idu u suprotnom smeru.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Tvrdnja-o-Abdullahu-ibn-Ebu-Serhu","chunks":[{"text":"Verodostojna predaja taj izraz vezuje za Omera ibn el Hattaba, koji ga je izgovorio slušajući diktat, a Poslanik ﷺ je potvrdio da je upravo tako i objavljeno. Verzija koja se vezuje za Muaza ibn Džebela slaba je zbog Džabira el Džu'fija, a verzija sa Abdullahom ibn Ebu Serhom, na koju se prigovarači oslanjaju, vodi jedino do Kelbija, koji je i sam priznao da je lagao.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Tvrdi se da je izraz „pa neka je uzvišen Allah, najlepši Stvoritelj\" izgovorio pisar, a da nije objavljen Poslaniku ﷺ. Sura El Mu'minun 23:14 I onda ga, kao drugo stvorenje, oživimo. Pa neka je uzvišen Allah, najlepši Stvoritelj!","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Prvo izraz ne povlači nikakvo mnoštvo stvoritelja U semitskim jezicima, u arapskom, hebrejskom i sirijskom aramejskom, koji su svi kćeri zajedničkog semitskog jezika, glagol halaka znači dovesti nešto u postojanje iz već postojećih sastojaka, dok enšee znači dovesti nešto u postojanje ni iz čega. Samo Allah čini ovo drugo. Ljudsko stvaranje uvek je ono prvo. Otuda izraz najlepši Stvoritelj ne pretpostavlja druge stvoritelje u Božijem smislu, nego se odnosi na oblikovanje iz postojeće građe, u kojem i ljudi učestvuju. Time otpada i pretpostavka na kojoj primedba počiva.","headingId":"prvo-izraz-ne-povlaci-nikakvo-mnostvo-stvoritelja","headingText":"Prvo - izraz ne povlači nikakvo mnoštvo stvoritelja"},{"text":"Drugo tri predaje i njihove ocene","headingId":"drugo-tri-predaje-i-njihove-ocene","headingText":"Drugo - tri predaje i njihove ocene"},{"text":"Prva predaja Omer ibn el Hattab, verodostojna Verodostojna predaja utvrđuje da je Omer ibn el Hattab, radijallahu anhu, čuvši ajet koji se diktira, bio ponesen da ga dovrši, a Poslanik ﷺ je potvrdio da je upravo tako i bilo objavljeno. El Kurtubi, Tefsirul Kurtubi, tom 12, str. 110; Es Sujuti, El Itkan, tom 1, str. 128.","headingId":"prva-predaja-omer-ibn-el-hattab-verodostojna","headingText":"Prva predaja - Omer ibn el-Hattab, verodostojna"},{"text":"Druga predaja Muaz ibn Džebel, slaba Predaja koja tu izjavu pripisuje Muazu ibn Džebelu slaba je. U njenom lancu je Džabir el Džu'fi, prenosilac čije se predaje ne prihvataju. Ibn Ebu Hatim, navedeno u El Itkan, tom 3, str. 346.","headingId":"druga-predaja-muaz-ibn-dzebel-slaba","headingText":"Druga predaja - Muaz ibn Džebel, slaba"},{"text":"Treća predaja Abdullah ibn Ebu Serh, izmišljena To je predaja na koju se kritičari oslanjaju, a ona u celini vodi do jednog jedinog izvora, do Kelbija.","headingId":"treca-predaja-abdullah-ibn-ebu-serh-izmisljena","headingText":"Treća predaja - Abdullah ibn Ebu Serh, izmišljena"},{"text":"Dodatak detaljna ocena lanaca Pored tri navedene predaje, u raspravi se javljaju i pojedinačni lanci koje treba oceniti zasebno, jer se često navode kao potvrda jedni drugima.","headingId":"dodatak-detaljna-ocena-lanaca","headingText":"Dodatak - detaljna ocena lanaca"},{"text":"Lanac kod Isbahanija Prenosi se preko Sulejmana ibn Ahmeda, Ebu Bekra ibn Sehla, Abdul Ganija, Musaa ibn Abdur Rahmana, Ibn Džurejdža i Ataa, do Ibn Abbasa. Drugi put ide preko Mukatila i Dahhaka, do Ibn Abbasa. El Isbahani, Fedailul hulefail erbea, str. 87 88. Primedbe na taj lanac: Musa ibn Abdur Rahman označen je kao poznati lažljivac. El Kamil fi duafair ridžal, 8/66. Ibn Džurejdž je mudellis, a ovde nije izričito naveo da je čuo od Ataa. Mukatil ibn Sulejman ocenjen je kao lažljivac. Dahhak nije čuo od Ibn Abbasa, pa je i taj put prekinut. Priređivač Salih ibn Muhammed el Akil predaju je oslabio.","headingId":"lanac-kod-isbahanija","headingText":"Lanac kod Isbahanija"},{"text":"Lanac kod Taberanija Prenosi se preko Abdur Rahmana ibn Amra Ebu Zur'e, Adema ibn Ebu Ijasa, Šejbana, Džabira i Amira eš Ša'bija, do Zejda ibn Sabita, a sadržaj se vezuje za Muaza ibn Džebela. Et Taberani, El Mu'džemul evsat, 5/56. Primedbe: Džabir el Džu'fi je slab prenosilac. El Ukajli, Ed Duafa. Ibn Hadžer je predaju oslabio. Priređivač en Nešatri ocenio ju je kao krajnje slabu, čak i uz potkrepljujuće predaje.","headingId":"lanac-kod-taberanija","headingText":"Lanac kod Taberanija"},{"text":"Lanac kod Ebu Davuda et Tajalisija Prenosi se preko Hammada ibn Seleme i Alije ibn Zejda, do Enesa ibn Malika. Musned Ebu Davuda et Tajalisija, 1/46 47. Primedbe: Alija ibn Zejd ibn Džud'an je slab prenosilac, a Zehebi je o njemu sabrao ocene Šu'be, Hammada ibn Zejda, Ahmeda, Jahjaa ibn Kattana, Buharija, Ebu Hatima, el Fesevija i Ibn Huzejme. Ez Zehebi, Mizanul i'tidal. Priređivač et Turki naveo je da je prenos slab zbog Alije ibn Zejda. Ovde je važno uočiti kako se slabi lanci međusobno ne leče. Kada se tri predaje navode kao potvrda jedna drugoj, a svaka od njih pada zbog zasebnog imenovanog prenosioca, njihovo gomilanje ne stvara snagu. Potkrepljivanje deluje samo kada je slabost blaga i različite vrste,","headingId":"lanac-kod-ebu-davuda-et-tajalisija","headingText":"Lanac kod Ebu Davuda et-Tajalisija"},{"text":"a ne kada u lancima stoje ljudi ocenjeni kao lažljivci.","headingId":"lanac-kod-ebu-davuda-et-tajalisija","headingText":"Lanac kod Ebu Davuda et-Tajalisija"},{"text":"Treće ko je Kelbi Sam Kelbi je priznao: Šta god ste od mene preneli, od Ebu Saliha, od Ibn Abbasa, to je laž. Nemojte to prenositi. Izvor: Kelbi. Ibn Adijj, El Kamil, tom 6, str. 115 116. Nesai je naveo: „Muhammed ibn es Saib Ebun Nadr el Kelbi je metruk, dakle napušten u hadisu.\" Sa'di je naveo: „Muhammed ibn es Saib je lažljivac i propalica.\" Reč je, dakle, o prenosiocu koji je za sopstvene predaje izjavio da su laž. Cela tvrdnja o pisarevoj izmeni počiva na njemu.","headingId":"trece-ko-je-kelbi","headingText":"Treće - ko je Kelbi"},{"text":"Zaključak Oni koji tvrde da je pisar iskrivio Kur'an snose teret dokazivanja, dakle dužni su da za tu tvrdnju pruže verodostojan lanac prenošenja.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Tvrdnja-o-ajetu-borite-se-kao-sto-ste-se-borili","chunks":[{"text":"Predaja je slaba i njen lanac je prekinut, jer Sevr ibn Zejd nije sreo Ibn Abbasa: Sevr je umro 153. godine, a Ibn Abbas 68. godine po Hidžri. Uz to, različite verzije donose različit tekst, što pokazuje da je reč o prenošenju po značenju, a ne o doslovnom kur'anskom prenosu. Kur'an, međutim, iziskuje neprekinut, masovan prenos reč po reč.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Tvrdi se da je Kur'an iskrivljen uklanjanjem izraza „kao što ste se borili prvi put\".","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Prvo slabost lanca Lanac je prekinut, jer Sevr ibn Zejd nije sreo Ibn Abbasa, iako se navodi kao njegov izvor. Sevr je umro 153. godine po Hidžri, a Ibn Abbas 68. godine, dakle razlika je 85 godina. Više verzija kružilo je preko Abdul Aziza ed Deravardija, koji je poznat po greškama i slabom pamćenju. On je u lanac pogrešno umetnuo ime Ikrime. Bakillani je naveo: „Sve te predaje su pojedinačne vesti koje se ne mogu potvrditi.\" El Bakillani. Kur'an iziskuje mutevatir, dakle neprekinut i masovan prenos, a ne pojedinačne vesti, jer Kur'an iziskuje prenošenje reč po reč. Same verzije te predaje razlikuju se u tekstu: u jednoj stoji „Borite se kao što ste se borili prvi put\", a u drugoj","headingId":"prvo-slabost-lanca","headingText":"Prvo - slabost lanca"},{"text":"„Borite se za Allaha istinskom borbom\". Ta razlika sama po sebi pokazuje da je reč o prenošenju po značenju, a ne o doslovnom kur'anskom tekstu, koji se prenosi nepromenjen.","headingId":"prvo-slabost-lanca","headingText":"Prvo - slabost lanca"},{"text":"Drugo predaja protivreči istoriji Predaja se oslanja na to da je Omer bio nesklon jednom plemenu, ali istorijski podaci govore drugačije. Omer je pripadnike Benu Mugire postavljao na vodeće položaje. Primeri su Malik ibn el Haris, postavljen za namesnika u Hauranu 15. godine po Hidžri, zatim Halid ibn Velid, nazvan isukanom Allahovom sabljom, kao i Umm Selema, žena Poslanika ﷺ, iz plemena Benu Mahzum. Ibn el Kajjim je naveo: „Svaki hadis koji kritikuje Emevije jeste laž.\" Ibnul Kajjim.","headingId":"drugo-predaja-protivreci-istoriji","headingText":"Drugo - predaja protivreči istoriji"},{"text":"Treće šta znači da je nešto „ispalo\" Izraz znači da je naredba objavljena, ali da učenje nije bilo obavezno. Reč kur'an ima više značenja: može označavati sam Časni Kur'an, a može označavati i čitanje nečega. Izraz „ispalo\" znači „nije obavezno učiti u namazu\", a ne „izgubljeno je ili iskrivljeno\". To je slično kudsi hadisu, gde značenje obavezuje na postupanje, ali učenje u namazu nije propisano. Alija ibn Ebu Talib imao je svitak sa hadisima koji bi učio, a on nije bio deo Časnog Kur'ana. To pokazuje da ono što se čita ne mora biti kur'anski tekst.","headingId":"trece-sta-znaci-da-je-nesto-ispalo","headingText":"Treće - šta znači da je nešto „ispalo\""},{"text":"Četvrto tri istorijske napomene 1. Razgovor između Omera i Abdur Rahmana odigrao se pre nego što je Osman ibn Affan prepisao Kur'an, pa se Osman ne može optužiti za iskrivljenje. 2. Ebu Bekr nije uklonio nijedan od sedam harfova Allahove Knjige, nego je objedinio svih sedam. 3. Ni Omer ni Abdur Rahman taj izraz nisu uvrstili u sastavljeni tekst, jer su dobro znali da nije deo Allahove Knjige.","headingId":"cetvrto-tri-istorijske-napomene","headingText":"Četvrto - tri istorijske napomene"},{"text":"Peto tvrdnja o Aišinom primerku Haris el Muhasibi tvrdio je da je Aišin primerak sadržao taj izraz, ali za to nije pružio dokaz. Budući da je Muhasibi rođen 170. godine po Hidžri, a Aiša umrla mnogo ranije, ta tvrdnja nema dokumentovanu potvrdu.","headingId":"peto-tvrdnja-o-aisinom-primerku","headingText":"Peto - tvrdnja o Aišinom primerku"},{"text":"Zaključak Predaja je slaba, njen lanac je prekinut i nije verodostojna. Uz to, protivreči poznatoj istoriji, a same njene verzije protivreče jedna drugoj u tekstu.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Tvrdnja-o-citanju-hadab-dzehennema","chunks":[{"text":"Za tvrdnju da su ashabi učili hadab umesto hasab ne postoji nijedan potvrđen dokaz. Najranije pripisivanje javlja se u Farahidijevom rečniku El Ajn, bez ikakvog lanca prenošenja. Ferra ga zatim pripisuje Ibn Abbasu preko Ibn Ebu Jahjaa, koji je ocenjen kao lažljivac i koji je rođen oko 32 godine nakon Ibn Abbasa. Svi kasniji pisci to samo ponavljaju, a većina njih su jezikoslovci, a ne šerijatski učenjaci.","headingId":"","headingText":""},{"text":"Ajet o kojem je reč Sura El Enbija 21:98 I vi, i oni kojima se, pored Allaha, klanjate, bićete gorivo u Džehennemu, a u njega ćete doista ući. Tvrdi se da su ashabi i žene Poslanika ﷺ učili hadab umesto hasab.","headingId":"ajet-o-kojem-je-rec","headingText":"Ajet o kojem je reč"},{"text":"Prvo poreklo tvrdnje Najranije pripisivanje javlja se u rečniku El Ajn od Farahidija, ali bez ikakvog lanca prenošenja i bez izvora. El Farahidi, El Ajn. Ferra je zatim tvrdio da je Ibn Abbas učio hadab, pozivajući se na Ibn Ebu Jahjaa. Ibn Ebu Jahja, punim imenom Ibrahim ibn Muhammed ibn Sem'an, opisan je kod ranih učenjaka kao mutezilija, džehmija, kaderija, onaj koji čini tedlis i lažljivac, koji je izmišljao predaje. Rođen je oko 32 godine nakon Ibn Abbasa, pa mu nije bio savremenik. Sve što sledi zavisi upravo od tog jednog pripisivanja. Kasniji pisci, poput Zedždžadža, Ibn Durejda, Ibn Uzejra es Sidžistanija, Gulama Sa'leba i Ezherija, tu nepotvrđenu tvrdnju prenose kroz naraštaje, ali je niko od njih nije nezavisno proverio.","headingId":"prvo-poreklo-tvrdnje","headingText":"Prvo - poreklo tvrdnje"},{"text":"Većina onih koji to čitanje spominju bili su jezikoslovci, a ne šerijatski stručnjaci, i nameravali su da raspravljaju o jezičkom značenju, a ne da tvrde da je reč o stvarnom kur'anskom učenju.","headingId":"prvo-poreklo-tvrdnje","headingText":"Prvo - poreklo tvrdnje"},{"text":"Drugo tvrdnja protiv Aiše Maturidi je tu tvrdnju izneo o Aiši, bez ikakvog dokaza i bez dokumentacije. Maturidi je živeo u trećem i četvrtom veku po Hidžri, dakle vekovima nakon Aiše, i nije naveo nikakav dokumentovan izvor.","headingId":"drugo-tvrdnja-protiv-aise","headingText":"Drugo - tvrdnja protiv Aiše"},{"text":"Treće ostala pripisivanja bez dokaza 1. Ibrahim el Harbi tvrdio je da je Alija ibn Ebu Talib učio drugačije, bez valjanog dokaza. 2. Taberi je to pripisao i Aliji i Aiši, bez potkrepljujuće dokumentacije. 3. Gulam Sa'leb , jezikoslovac iz trećeg veka, pripisao je to Aiši bez dokaza. 4. Ibn Džinni je u delu El Muhtesib to pripisao Aliji, Aiši, Ibn Zubejru, Ubejju ibn Ka'bu i Ikrimi, bez dokaza. Njegovo pripisivanje Ibn Zubejru i Ubejju ibn Ka'bu nema presedana u ranijoj literaturi. Kao jezikoslovac, on je zašao izvan svoje struke. 5. Ibn el Dževzi , koji je pisao u šestom veku, dakle oko 400 godina nakon tih ljudi, pripisao je slaba čitanja Urvi, Ikrimi, Ibn Ja'meru i Ibn Ebu Abli,","headingId":"trece-ostala-pripisivanja-bez-dokaza","headingText":"Treće - ostala pripisivanja bez dokaza"},{"text":"bez ikakvog dokaza. 6. Alusi je u Ruhul meaniju to pripisao Aliji, Ubejju, Aiši, Ibn Zubejru i Zejdu ibn Aliji. Rođen je 1200 godina nakon ashaba i nije priložio nikakvu dokumentaciju. 7. Muhammed Abdul Halik Udejma , u četrnaestom veku po Hidžri, izneo je slična pripisivanja bez neprekinutog lanca. 8. Sehavi je hadab sa zvučnim dad pripisao Ibn Mes'udu. Rođen je 800 godina nakon njegove smrti, nije naveo izvor, i prvi je izneo baš to pripisivanje, koje se suštinski razlikuje od prethodnika.","headingId":"trece-ostala-pripisivanja-bez-dokaza","headingText":"Treće - ostala pripisivanja bez dokaza"},{"text":"Četvrto Taberijeva slaba predaja Taberi prenosi predaju o tome da je Ibn Abbas učio sa slovom dad, lancem: „Ahmed ibn Jusuf, od Kasima, od Ibrahima ibn Muhammeda, od Osmana ibn Abdullaha, od Ikrime, od Ibn Abbasa.\" U tom lancu je Ibrahim ibn Muhammed ibn Sem'an, poznat kao Ibrahim ibn Ebu Jahja el Eslemi, utvrđen kao lažljivac koji je prikrivao imena prenosilaca. Njegovo prenošenje u obliku anna dodatno slabi pouzdanost, pa predaja u potpunosti otpada. Osman ibn Abdullah, odnosno Osman ibn Mejmun el Adevi, bio je sporan među učenjacima. Oslabili su ga Jahja ibn Seid el Kattan i Nesai, a Darekutni ga je svrstao u kategoriju koja ukazuje na slabost. Ibn Hadžer ga je ocenio prihvatljivim, što znači slab, uz uslov","headingId":"cetvrto-taberijeva-slaba-predaja","headingText":"Četvrto - Taberijeva slaba predaja"},{"text":"potkrepljenja, kojeg u ovoj usamljenoj predaji nema.","headingId":"cetvrto-taberijeva-slaba-predaja","headingText":"Četvrto - Taberijeva slaba predaja"},{"text":"Peto Taberijeva druga predaja Sam Taberi prenosi i drugu predaju, u kojoj Ibn Abbas uči hasab, dakle onako kako stoji u današnjem Kur'anu. Lanac glasi: „Ibn Sinan el Kazzaz, od Hasana ibn Husejna el Aškera, od Ebu Kudejne, od Ataa ibn es Saiba, od Seida ibn Džubejra, od Ibn Abbasa.\" Isti izvor, dakle, donosi obe predaje. Pozivati se na slabiju, a prećutati onu koja se poklapa sa današnjim tekstom, nije čitanje izvora nego biranje iz njega.","headingId":"peto-taberijeva-druga-predaja","headingText":"Peto - Taberijeva druga predaja"},{"text":"Šesto Sujutijeva greška Sujuti je tvrdio da Taberi prenosi da je Mudžahid učio hasab. Uvidom u Taberijev tekst vidi se da se tamo nalazi samo Mudžahidovo tumačenje reči hasab u značenju drva, a ne samo to čitanje kao varijanta.","headingId":"sesto-sujutijeva-greska","headingText":"Šesto - Sujutijeva greška"},{"text":"Sedmo kako to čitanje ocenjuju sami učenjaci 1. Ebul Muzaffer es Sem'ani: „I takođe, među neuobičajenim: hadab džehennema sa zvučnim, pokretnim dad. Što se tiče poznatog hasab džehennema, to je ono što se baca u vatru.\" 2. Es Suhejli: „Prenosi se hadab džehennema sa zvučnim dad u neuobičajenim učenjima.\" 3. Es Semin el Halebi: „Pročitano je kao neuobičajeno.\" 4. Ebu Bekr el Haddad: „U neuobičajenom učenju.\" Svi ga, dakle, izričito svrstavaju u neuobičajena, odstupajuća učenja.","headingId":"sedmo-kako-to-citanje-ocenjuju-sami-ucenjaci","headingText":"Sedmo - kako to čitanje ocenjuju sami učenjaci"},{"text":"Zaključak Čitanja hadab i hatab spadaju u odstupajuća čitanja koja nemaju ni dokaz ni ispravan lanac prenošenja. Reč je o nepotvrđenim glasinama koje su kružile kroz učenjačke tekstove, bez ikakve stvarne muslimanske prakse.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Tvrdnja-o-dva-ajeta-koja-nisu-zapisana","chunks":[{"text":"Predaja ima dve mane u istom lancu: Ibn Lehia je oslabljen, a Ebu Sufjan el Kilai je nepoznat prenosilac. Svaka od te dve mane zasebno je dovoljna da predaja ne bude dokaz. Uz to, ona protivreči verodostojnoj predaji od Ibn Abbasa kod Buharija, u kojoj stoji da Poslanik ﷺ nije ostavio ništa osim onoga što je između dve korice.","headingId":"","headingText":""},{"text":"Sadržaj tvrdnje Navodi se predaja u kojoj stoji da su postojala dva ajeta koja nisu uneta u mushaf, a koja su govorila o onima koji su verovali, iselili se i borili imecima i životima, i o onima koji su ih primili i pomogli. Izvor je Ebu Ubejdovo delo o vrednostima Kur'ana. Ebu Ubejd, Fedailul Kur'an, str. 301. Lanac ide: Ibn Ebu Merjem, od Ibn Lehie, od Jezida ibn Amra el Meafirija, od Ebu Sufjana el Kilaija, od Mesleme ibn Muhalleda el Ensarija.","headingId":"sadrzaj-tvrdnje","headingText":"Sadržaj tvrdnje"},{"text":"Prvo predaja nije verodostojna","headingId":"prvo-predaja-nije-verodostojna","headingText":"Prvo - predaja nije verodostojna"},{"text":"Prva mana Ibn Lehia Abdullah ibn Lehia oslabljen je u hadisu. Zehebi je o njemu sabrao ocene kritičara. Ez Zehebi, Mizanul i'tidal, tom 4, str. 166. Njegova slabost vezuje se, između ostalog, za to što su mu knjige izgorele, nakon čega je prenosio iz pamćenja, sa greškama.","headingId":"prva-mana-ibn-lehia","headingText":"Prva mana - Ibn Lehia"},{"text":"Druga mana Ebu Sufjan el Kilai Ebu Sufjan el Kilai je medžhul , dakle nepoznat prenosilac, o kojem nema ocene kritičara. Ibn Kesir je izneo pravilo da se predaje nepoznatih prenosilaca ne prihvataju. Ibn Kesir, El Ba'isul hasis, str. 92. Ibn es Salah je uslove verodostojnosti postavio tako da isključuju takav lanac. Ebu Amr Ibn es Salah, Ulumul hadis, str. 11 i 111. Vredi zastati kod pojma nepoznatog prenosioca, jer se često pogrešno razume. To ne znači da je čovek bio loš, nego da o njemu nema dovoljno podataka da bi se ocenio. Kada se ne zna da li je bio precizan, nema osnova da se njegova predaja prihvati. Teret dokazivanja je na onome ko predaju iznosi, a ne obrnuto.","headingId":"druga-mana-ebu-sufjan-el-kilai","headingText":"Druga mana - Ebu Sufjan el-Kilai"},{"text":"Drugo protivreči verodostojnoj predaji Nije ostavio ništa osim onoga što je između dve korice. Izvor: Ibn Abbas, radijallahu anhuma. Sahih Buhari, br. 5019. Isto potvrđuje i Muhammed ibn el Hanefijje. Sahih Buhari. Ibn Hadžer je upravo to poglavlje razumeo kao odgovor na tvrdnje o izgubljenom Kur'anu. Ibn Hadžer el Askalani, Fethul bari, tom 11, str. 251. Sudar je ovde neposredan. Verodostojna predaja tvrdi da ničega drugog nema, slaba predaja tvrdi da ima. Kada se dve predaje sudare, prednost ima jača. To nije izbor po sklonosti nego pravilo koje se primenjuje uvek, i koje bi jednako važilo da je slabija predaja išla u suprotnom smeru.","headingId":"drugo-protivreci-verodostojnoj-predaji","headingText":"Drugo - protivreči verodostojnoj predaji"},{"text":"Treće i kada bi bila verodostojna Pretpostavimo, radi rasprave, da je predaja verodostojna. Ni tada ne bi značila ono što se iz nje izvodi. Sujuti takve slučajeve svrstava pod derogaciju učenja. Es Sujuti, El Itkan, tom 4, str. 1454 i 1462. To znači da bi reč bila o tekstu koji je jedno vreme bio učen, pa je njegovo učenje stavljeno van snage još za Poslanikovog ﷺ života. Takav tekst nije izgubljen nego je uklonjen odlukom Onoga koji ga je i objavio.","headingId":"trece-i-kada-bi-bila-verodostojna","headingText":"Treće - i kada bi bila verodostojna"},{"text":"Četvrto dosledna primena merila Onaj ko ovu predaju prihvata mora objasniti zašto je prihvata. Ako je prihvata zato što je zapisana u nekoj knjizi, onda mora prihvatiti i sve ostalo što je u knjigama zapisano, uključujući i ono što ide protiv njegove tvrdnje, a toga je neuporedivo više. Ako je prihvata nakon provere lanca, onda mora pokazati kako lanac sa oslabljenim i nepoznatim prenosiocem tu proveru prolazi. Ovo je pitanje doslednosti, a ne retorički obrt. Merilo mora biti isto pre nego što se zna šta će dati. Uzimanje predaje bez provere kada odgovara, i traženje provere kada ne odgovara, nije metod nego biranje ishoda.","headingId":"cetvrto-dosledna-primena-merila","headingText":"Četvrto - dosledna primena merila"},{"text":"Zaključak Predaja pada na dve nezavisne mane u lancu, protivreči verodostojnoj predaji kod Buharija, a i kada bi se prihvatila, značila bi derogaciju učenja, a ne gubitak teksta.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Tvrdnja-o-Ibn-Abbasu-i-Zemlji-na-vodi","chunks":[{"text":"Ne postoji nijedan valjan dokaz da je Ibn Abbas tako protumačio taj ajet. To tumačenje prvi mu je pripisao Vahidi u delu Et Tefsirul basit, ali je Vahidi živeo u petom veku po Hidžri, a Ibn Abbas u prvom, dakle između njih su stotine godina. Fahrudin er Razi u šestom i Kurtubi u sedmom veku samo su tu tvrdnju prepisali, bez ikakvog lanca prenošenja.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Navodi se ajet: Sura El Hidžr 15:19 A Zemlju smo prostrli. Tvrdi se da je Ibn Abbas taj ajet protumačio rečima: „Prostrli smo Zemlju po površini vode.\"","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Odgovor Ne postoji nijedan valjan dokaz da je Ibn Abbas tako protumačio taj ajet. Ta izjava je raširena u pojedinim tefsirskim knjigama, ali bez ikakvog dokaza i bez potpore.","headingId":"odgovor","headingText":"Odgovor"},{"text":"Lanac pripisivanja Prvi koji je tu izjavu pripisao Ibn Abbasu bio je Vahidi, u delu Et Tefsirul basit. Vahidi je, međutim, živeo u petom veku po Hidžri, a Ibn Abbas u prvom veku. Između njih su, dakle, stotine godina. Zatim je došao Fahrudin er Razi i preneo istu glasinu, lažno pripisanu Ibn Abbasu. Razi je živeo u šestom veku po Hidžri. Potom je došao Kurtubi, koji je živeo u sedmom veku, i preneo isti podatak, bez provere njegove verodostojnosti.","headingId":"lanac-pripisivanja","headingText":"Lanac pripisivanja"},{"text":"Ocena Vahidi je to preuzeo iz neproverenih glasina svog vremena i nije naveo nikakav lanac prenošenja. Vahidi, Razi i Kurtubi tu su izjavu pripisali Ibn Abbasu bez ikakvog dokaza i bez lanca prenošenja. To je dovoljno da se ta predaja obori i da se pokaže njena slabost i nedostatak autoriteta. Vredi primetiti obrazac koji se u ovoj kategoriji ponavlja: tvrdnja se prvi put javlja vekovima nakon onoga kome se pripisuje, bez lanca, a zatim se njena težina gradi samim ponavljanjem kod kasnijih pisaca. Broj onih koji je prenose ne nadomešta odsustvo prenosnog lanca.","headingId":"ocena","headingText":"Ocena"}]},{"slug":"Tvrdnja-o-izmeni-El-Fatihe","chunks":[{"text":"Osmanski mushafi tu reč pišu bez elifa, a taj zapis dopušta oba učenja, i malik i melik. Nije, dakle, reč o izmeni, nego o rasmu koji nosi dva verodostojna učenja. Predaju o jedanaest Hadždžadžovih izmena prenosi Abbad ibn Suhajb, kojeg je Buhari nazvao odbačenim, a Ibn el Medini rekao da mu je hadis propao. Tu tvrdnju odbacuje čak i šijski učenjak Huji.","headingId":"","headingText":""},{"text":"Prvo tvrdnja o El Fatihi Tvrdi se da je Mervan ibn el Hakem izmenio učenje reči u ajetu o Danu sudnjem u suri El Fatiha. Ibn Kesir je ocenio da Zuhrijeva tvrdnja nije potkrepljena, navodeći da je Mervan znao ispravnost onoga što uči, a da Ibn Šihab to nije video. Ibn Kesir. Više prenosa dokumentuje da su ashabi, pa i sam Poslanik ﷺ, taj izraz učili bez elifa. Osmanski mushafi svi su se složili da se ta reč piše bez elifa, a taj zapis dopušta oba učenja. U tome je ceo odgovor. Rasm bez elifa nije zapis jednog učenja koje je neko naknadno promenio, nego zapis koji istovremeno nosi oba verodostojna učenja. To je upravo ono načelo po kojem je","headingId":"prvo-tvrdnja-o-el-fatihi","headingText":"Prvo - tvrdnja o El-Fatihi"},{"text":"osmanski mushaf i pisan.","headingId":"prvo-tvrdnja-o-el-fatihi","headingText":"Prvo - tvrdnja o El-Fatihi"},{"text":"Drugo tvrdnja o Hadždžadžovim izmenama Tvrdi se da je Hadždžadž izmenio Osmanov mushaf prilikom tačkovanja. Prenosilac Abbad ibn Suhajb, koji je izvestio o jedanaest navodnih izmena, ocenjen je nepouzdanim kod više hadiskih učenjaka. Alija ibn el Medini rekao je: „Njegov hadis je propao.\" Buhari je rekao: „Odbačen je.\" Alija ibn el Medini; El Buhari, o Abbadu ibn Suhajbu. Šijski učenjak Huji tu tvrdnju odbacuje kao neverovatnu: Ta tvrdnja liči na bunilo grozničavog i na izmišljotine pomahnitalog. Izvor: El Huji. El Huji. Vredi primetiti odakle to odbacivanje dolazi. Huji je dvanaestoimamski šijski učenjak, dakle nije pristrasan u korist Emevija, a ipak tu tvrdnju odbacuje kao neozbiljnu. Uz to, imam Sidžistani nije napisao knjigu pod naslovom „Ono što je Hadždžadž izmenio u","headingId":"drugo-tvrdnja-o-hadzdzadzovim-izmenama","headingText":"Drugo - tvrdnja o Hadždžadžovim izmenama"},{"text":"Osmanovom mushafu\", kako se ponekad navodi.","headingId":"drugo-tvrdnja-o-hadzdzadzovim-izmenama","headingText":"Drugo - tvrdnja o Hadždžadžovim izmenama"},{"text":"Treće tvrdnja o dodatnim surama kod Ubejja ibn Ka'ba Hrišćani i kur'anisti tvrde da je Ubejjev primerak sadržao dve dodatne sure. Verodostojna učenja koja se prenose preko Ibn Mes'uda te sure ne sadrže, iako su njegovi prenosioci učili pred njim. Uz to, lični mushaf Ibn Mes'uda bio je izborni, a najbolji dokaz za to jeste činjenica da u njemu nije zapisao ni suru El Fatihu. Taj podatak je odlučujući. Niko ne tvrdi da je Ibn Mes'ud poricao El Fatihu. Ako, dakle, odsustvo neke sure iz njegovog ličnog primerka ne znači poricanje u jednom slučaju, ne može značiti ni u drugom. Njegov primerak bio je lična beležnica, a ne zvanični mushaf. Bakillani je naveo da je Ibn Mes'ud poricao da se","headingId":"trece-tvrdnja-o-dodatnim-surama-kod-ubejja-ibn-kaba","headingText":"Treće - tvrdnja o dodatnim surama kod Ubejja ibn Ka'ba"},{"text":"te sure nalaze u mushafu, a ne da su Kur'an. El Bakillani.","headingId":"trece-tvrdnja-o-dodatnim-surama-kod-ubejja-ibn-kaba","headingText":"Treće - tvrdnja o dodatnim surama kod Ubejja ibn Ka'ba"}]},{"slug":"Tvrdnja-o-pisarskoj-gresci-u-ajetu-o-svetlosti","chunks":[{"text":"Predaja na koju se prigovor oslanja sadrži unutrašnju protivrečnost, jer Ibn Abbas navodno ukazuje na drugačije učenje, ali sam nikada tako nije učio. Klasični učenjaci su te predaje oslabili. Uz to, mushaf se prenosi masovnim prenosom kroz mnoštvo istovremeno raspoređenih primeraka, u kojem neispravljena pisarska greška nije moguća.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Tvrdi se da je izvorno učenje ajeta glasilo „primer svetlosti vernika\", a da je pisar pogrešio i zapisao ono što danas stoji u mushafu. Sura En Nur 24:35 Allah je izvor svetlosti nebesa i Zemlje! Primer svetlosti Njegove je udubina u zidu u kojoj je svetiljka, svetiljka je u kandilju, a kandilj je kao zvezda blistava.","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Prvo predaja protivreči sama sebi Predaja pripisuje Ibn Abbasu ukazivanje na drugačiji oblik učenja, ali istovremeno stoji da on sam nikada tako nije učio. To je ozbiljna unutrašnja protivrečnost. Ako je Ibn Abbas smatrao da je izvorno učenje drugačije, njegovo sopstveno učenje bilo bi prvi dokaz za to. Sve što je od njega preneseno kroz priznate lance učenja sadrži tekst kakav je u mushafu.","headingId":"prvo-predaja-protivreci-sama-sebi","headingText":"Prvo - predaja protivreči sama sebi"},{"text":"Drugo klasični učenjaci su te predaje oslabili Ibn Tejmijje se osvrnuo na predaje ovog tipa i ukazao na njihovu slabost. Ibn Tejmijje, Medžmu'ul fetava, 15/255. Sujuti ih u El Itkanu ne prihvata kao osnov za tvrdnju o izmeni teksta. Es Sujuti, El Itkan fi ulumil Kur'an, 2/2. Ebu Hajjan el Endelusi u svom tefsiru raspravlja o navedenim oblicima i ne uzima ih kao alternativu utvrđenom tekstu. Ebu Hajjan el Endelusi, El Bahrul muhit, 6/418.","headingId":"drugo-klasicni-ucenjaci-su-te-predaje-oslabili","headingText":"Drugo - klasični učenjaci su te predaje oslabili"},{"text":"Treće masovni prenos isključuje pisarsku grešku Mushaf se ne prenosi jednim primerkom niti jednim lancem. Osman, radijallahu anhu, poslao je primerke u glavne pokrajine, a uz svaki od njih i učača koji je ljude podučavao učenju. Pisarska greška u jednom primerku bila bi otkrivena istog trenutka kada bi se uporedila sa ostalim primercima i sa učenjem hiljada ljudi koji su tekst znali napamet. Da bi tvrdnja o grešci stajala, morala bi se pretpostaviti istovetna greška u svim primercima istovremeno, i to greška koju niko od hafiza nije primetio. To nije istorijski scenario nego nemogućnost. Ez Zerkani je ukazao na to da je masovni prenos kur'anskog teksta uslov njegove verodostojnosti, i da se ono što se ne prenosi masovno ne smatra","headingId":"trece-masovni-prenos-iskljucuje-pisarsku-gresku","headingText":"Treće - masovni prenos isključuje pisarsku grešku"},{"text":"Kur'anom. Ez Zerkani, Menahilul irfan, 1/391 392. Ibn el Džezeri je isto načelo primenio na kiraete: prihvata se samo ono što ima verodostojan lanac, slaže se sa osmanskim zapisom i odgovara arapskom jeziku. Ibn el Džezeri, En Nešr fil kiraatil ašr, 1/178, 1/122.","headingId":"trece-masovni-prenos-iskljucuje-pisarsku-gresku","headingText":"Treće - masovni prenos isključuje pisarsku grešku"},{"text":"Četvrto Ibn Abbas je Kur'an učio od samih sakupljača Ibn Abbas, radijallahu anhuma, učio je Kur'an od Zejda ibn Sabita i od Ubejja ibn Ka'ba. To su upravo ljudi koji su učestvovali u zapisivanju i sakupljanju mushafa. Ovde se prigovor sam potkopava. Onaj ko se navodi kao svedok protiv teksta učio je taj tekst od onih koji su ga zapisali. Da je smatrao da su pogrešili, to bi prigovorio njima, a ne bi njihovo učenje prenosio dalje.","headingId":"cetvrto-ibn-abbas-je-kuran-ucio-od-samih-sakupljaca","headingText":"Četvrto - Ibn Abbas je Kur'an učio od samih sakupljača"},{"text":"Peto Ibn Abbas je bio mlađi ashab Ibn Abbas je pripadao mlađim ashabima i bio je učenik učača, a ne izvor nezavisan od njih. Ez Zehebi navodi lance učenja preko kojih se prenosi njegovo učenje, i u njima nema oblika koji prigovor pretpostavlja. Muhammed ez Zehebi, Ma'rifetul kurra'il kibar, 1/57, 1/45.","headingId":"peto-ibn-abbas-je-bio-mladji-ashab","headingText":"Peto - Ibn Abbas je bio mlađi ashab"},{"text":"Šesto šta su onda ti oblici Oblici koji se pripisuju Mudžahidu i Ubejju ibn Ka'bu mogu se objasniti na dva načina, a nijedan ne podrazumeva grešku u tekstu: 1. Reč je o tumačenju , dakle o objašnjenju značenja ajeta koje je zapisano uz tekst, kako je bio običaj kod pojedinih ashaba. 2. Reč je o derogiranom učenju , dakle o obliku koji je jedno vreme učen, pa je njegovo učenje derogirano. Nijedno od toga ne znači da je današnji tekst nastao greškom pisara.","headingId":"sesto-sta-su-onda-ti-oblici","headingText":"Šesto - šta su onda ti oblici"},{"text":"Zaključak Prigovor stoji ili pada na jednoj predaji koja sama sebi protivreči i koju klasični učenjaci nisu prihvatili. Nasuprot njoj stoji tekst koji se od prvog dana prenosi masovno, istovremeno u više pokrajina, u pisanom i usmenom obliku.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Tvrdnja-o-pisarskoj-gresci-u-El-Isra-17-23","chunks":[{"text":"Odgovor počiva na četiri odvojena razloga, od kojih je svaki dovoljan sam za sebe: svi lanci predaje su slabi, klasični mufessiri su je izričito odbacili, ona protivreči učenju koje se prenosi masovnim prenosom, a između dva navodno sukobljena čitanja i nema razlike u značenju.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Tvrdi se da je izvorno učenje glasilo ve vessa rabbuke , dakle „i preporučio je Gospodar tvoj\", a da je pisar pogrešio i zapisao ve kada rabbuke , dakle „i odredio je Gospodar tvoj\". Sura El Isra 17:23 Gospodar tvoj zapoveda da se samo Njemu klanjate i da roditeljima dobročinstvo činite. Objašnjenje koje se uz to nudi jeste da je tobože jedno slovo ispalo prilikom prepisivanja.","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Gde se ta predaja nalazi Predaja se navodi kod Seida ibn Mensura, preko Seida ibn Džubejra, od Ibn Abbasa, radijallahu anhuma. Slične verzije zabeležili su Taberi, Ebu Ubejd i Ibn el Munzir, a spominju je Ibn el Dževzi u Zadul mesiru, Razi u svom tefsiru, Ibn Adil u El Lubabu i Taberi. Et Taberi, Džami'ul bejan, tom 15, str. 63; Ibn el Dževzi, Zadul mesir, tom 4, str. 155; Er Razi, Mefatihul gajb, tom 10, str. 30.","headingId":"gde-se-ta-predaja-nalazi","headingText":"Gde se ta predaja nalazi"},{"text":"Prvo slabost lanaca","headingId":"prvo-slabost-lanaca","headingText":"Prvo - slabost lanaca"},{"text":"Lanac preko Jahjaa ibn Isaa Ibn Hibban ga je uvrstio u Tabekatul medžruhin, navodeći da je slabog pamćenja i da je često grešio, te da se njegove predaje ne uzimaju kao dokaz. Ibn Hibban, Tabekatul medžruhin.","headingId":"lanac-preko-jahjaa-ibn-isaa","headingText":"Lanac preko Jahjaa ibn Isaa"},{"text":"Lanac preko Hišama ibn Bešira Hišam ibn Bešir poznat je kao mudellis, dakle prenosilac koji prikriva svoje izvore, a ovde prenosi izrazom an , bez izričitog navođenja da je čuo. Ibn Hadžer, Takribut tehzib. Tedlis je ovde presudan. Kada mudellis prenosi izrazom an, njegova predaja se ne prihvata dok se ne utvrdi da je tekst zaista čuo od onoga koga navodi. U ovom lancu to nije utvrđeno, a u njemu se nalazi i Ebu Ishak el Kufi, koji je takođe ocenjen kao slab. Ebu Hatim je odbio mogućnost da je Ibn Abbas to uopšte izjavio. Ebu Hatim, prenosi Et Taberani u svom tefsiru.","headingId":"lanac-preko-hisama-ibn-besira","headingText":"Lanac preko Hišama ibn Bešira"},{"text":"Drugo izričito odbacivanje kod učenjaka Razi je tu tvrdnju nazvao krajnje nategnutom i označio je kao veliki napad na veru, ukazujući na to da protivreči masovno prenesenom učenju. Er Razi, Mefatihul gajb, tom 10, str. 30. Ibn el Dževzi je naveo da je to suprotno saglasnosti i da tome ne treba poklanjati pažnju. Ibn el Dževzi, Zadul mesir, tom 4, str. 155. Zerkani je tvrdnje te vrste nazvao jeftinim spletkama koje izmišljaju neprijatelji islama. Ez Zerkani, Menahilul irfan, tom 1, str. 269. Isti stav zauzeli su Ibn Adil i Ibn el Enbari, koji je ukazao i na slabost lanaca i na protivrečnost sa masovnim prenosom.","headingId":"drugo-izricito-odbacivanje-kod-ucenjaka","headingText":"Drugo - izričito odbacivanje kod učenjaka"},{"text":"Treće protivrečnost sa masovnim prenosom Ebu Hajjan potvrđuje da se učenje ve kada rabbuke masovno prenosi, i to upravo od Ibn Abbasa, kao i od Hasana el Basrija i Katade. Ebu Hajjan el Endelusi, El Bahrul muhit. Ovde ponovo dolazi do unutrašnje protivrečnosti prigovora. Isti onaj Ibn Abbas kome se pripisuje primedba prenosi utvrđeno učenje kroz priznate lance. Pojedinačna vest ne može poništiti ono što se prenosi masovno.","headingId":"trece-protivrecnost-sa-masovnim-prenosom","headingText":"Treće - protivrečnost sa masovnim prenosom"},{"text":"Četvrto između dva značenja i nema sukoba Glagol kada u arapskom jeziku obuhvata više značenja: presuditi, narediti, hteti, dovršiti, učiniti i zapovediti. Glagol vessa znači zapovedio, preporučio. Da kada nosi značenje naredbe i presude, a ne samo neizbežne odredbe, pokazuju i drugi ajeti: Sura El Ahzab 33:36 Kada Allah i Poslanik Njegov nešto odrede, onda ni vernik ni vernica nemaju pravo po svom nahođenju postupiti. Sura En Nisa 4:65 I ne budu se zbog presude tvoje u dušama svojim nikakve tegobe osećali. Ferra je upravo tu jezičku širinu glagola kada i obrazložio. El Ferra, Meanil Kur'an. Značenje ajeta je, dakle, isto bilo da se čita jednim ili drugim glagolom, pa nema ničega što bi navodna izmena uopšte promenila. Sura El","headingId":"cetvrto-izmedju-dva-znacenja-i-nema-sukoba","headingText":"Četvrto - između dva značenja i nema sukoba"},{"text":"Hidžr 15:9 Mi, uistinu, Kur'an objavljujemo i zaista ćemo Mi nad njim bdeti!","headingId":"cetvrto-izmedju-dva-znacenja-i-nema-sukoba","headingText":"Četvrto - između dva značenja i nema sukoba"},{"text":"Zaključak Prigovor pada na četiri nivoa istovremeno. Lanci su slabi, učenjaci su ga odbacili, protivreči masovnom prenosu, a i kada bi sve to bilo drugačije, dva čitanja ne bi nosila različit propis niti različito značenje.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Tvrdnja-o-pravopisnim-greskama-u-Kuranu","chunks":[{"text":"Tvrdnja da Kur'an sadrži pravopisne greške počiva na tome što se drevni arapski pravopis prosuđuje po kasnijim, savremenim pravilima. Marijn van Puten je poređenjem kur'anskog teksta sa natpisima, papirusima i arapskim dokumentima tog doba zaključio da su pravopisna pravila s početka islama odgovarala kur'anskom načinu pisanja. Savremeni arapski pravopis je kasniji razvoj, a Kur'an čuva raniju pisanu tradiciju.","headingId":"","headingText":""},{"text":"Sadržaj tvrdnje Kritičari navode oblike poput musajtir, džennat, Ibraham i salah i tvrde da su to pravopisne greške, jer se razlikuju od kasnije ustaljenog arapskog pravopisa. To, međutim, nisu greške. Oni odražavaju rane arapske pravopisne običaje, koji su postojali pre nego što su kasnija pravopisna pravila ustaljena.","headingId":"sadrzaj-tvrdnje","headingText":"Sadržaj tvrdnje"},{"text":"Van Puten i kur'anski pravopis Holandski istraživač Marijn van Puten, stručnjak za semitsku lingvistiku i jezičku istoriju arapskog na Univerzitetu u Lajdenu, napisao je delo The Language of the Quranic Consonantal Text. On je uporedio kur'anski tekst sa natpisima, papirusima i arapskim dokumentima tog doba, i zaključio da su pravopisna pravila s početka islama odgovarala kur'anskom načinu pisanja. Pravopisni i jezički oblik koji se nalazi u osmanskom Kur'anu jasno se javlja i u ranim arapskim upravnim dokumentima, dakle u papirusima. Izvor: Van Puten. Marijn van Putten, The Language of the Quranic Consonantal Text, str. 218. Proučavanjem osobenih pravopisnih odlika u nizu ranih kur'anskih rukopisa, Van Puten je pokazao da svi ti rukopisi vode poreklo od jednog jedinog pisanog izvora, čije","headingId":"van-puten-i-kuranski-pravopis","headingText":"Van Puten i kur'anski pravopis"},{"text":"su pravopisne odlike kroz vekove precizno i pažljivo prepisivane. Izvor: Van Puten. Marijn van Putten, isto delo, str. 8. Taj način pisanja, dakle, nije bio pojedinačni napor niti greška, nego je namerno prenošen unutar dosledne pravopisne tradicije tog vremena. Van Puten koristi izraz „razborito prepisano\", što poriče zamisao da su te pravopisne razlike prepisivačke greške.","headingId":"van-puten-i-kuranski-pravopis","headingText":"Van Puten i kur'anski pravopis"},{"text":"Zašto se kur'anski pravopis razlikuje od savremenog Kur'anski pravopis razlikuje se od savremenog zato što Kur'an čuva rani arapski pravopisni sistem. Savremena arapska pravopisna pravila ustaljena su kasnije. Pogrešno je, dakle, drevni kur'anski pravopis prosuđivati po kasnijim pravopisnim običajima.","headingId":"zasto-se-kuranski-pravopis-razlikuje-od-savremenog","headingText":"Zašto se kur'anski pravopis razlikuje od savremenog"},{"text":"Primeri 1. Salah i salawa. Salawa je kur'anski oblik, sa slovom vav umesto elifa. Upotreba vava umesto skraćenog elifa bila je uobičajena u drevnom arapskom pravopisu. 2. Hajah i hajawa. Isto kao gore, skraćeni elif zamenjen je vavom. 3. Ibrahim i Ibraham. Ovde je izostavljeno slovo ja. Rani pravopis često je izostavljao srednji elif. Uz to, šamsko učenje to ime izgovara kao Ibraham. 4. Ni'mah i ni'mat. Izostavljanje vezanog ta ili njegova zamena običnim ta prepuštali su se slobodi ranih pravopisnih običaja. Izraz sunnetullah u Kur'anu piše se bez vezanog ta. Imam Sehavi je naveo: „Razlog takvog pisanja jeste da se ukaže na učenje Ibraham, a izostavljanje elifa jedan je vid skraćivanja.\" Es Sehavi.","headingId":"primeri","headingText":"Primeri"},{"text":"Ibn Haldun o istoriji arapskog pisma U ranim danima islama arapsko pismo nije bilo doseglo vrhunce preciznosti i izvrsnosti… zbog udaljenosti Arapa od zanatstva. Pogledaj šta se zbog toga dogodilo u pravopisu Kur'ana. Izvor: Ibn Haldun. Ibn Haldun, Mukaddima. Ibn Haldun ovde ne kaže da Kur'an sadrži greške. On objašnjava da je rano arapsko pisanje imalo svoj pravopisni stupanj, pre kasnijeg tehničkog usavršavanja i ustaljivanja.","headingId":"ibn-haldun-o-istoriji-arapskog-pisma","headingText":"Ibn Haldun o istoriji arapskog pisma"},{"text":"Rani natpisi i papirusi Ugovori i sporazumi pisani su istim pravopisom kao i Kur'an, pre nego što su se sistemi pisanja kasnije razvili. Natpis o Muavijinoj brani, datiran u 58. godinu po Hidžri, odnosno 678. godinu, koristi pravopis kur'anskog tipa, sa oblikom binihi umesto banahu. Marijn van Putten, o natpisu o Muavijinoj brani, 58. h. Ako se pravopis kur'anskog tipa javlja i u ranim arapskim upravnim dokumentima i natpisima, onda to nije kur'anska greška, nego jednostavno način na koji se arapski u tom razdoblju pisao.","headingId":"rani-natpisi-i-papirusi","headingText":"Rani natpisi i papirusi"},{"text":"Oblik musajtir Musajtir pripada hidžaskom narečju i plemenu Esed, dok je musajtar iz temimskog narečja. Kur'anski oblik musajtir, dakle, odražava ugledno hidžasko narečje, a ne grešku. Izvor: Van Puten. Marijn van Putten, isto delo, str. 156. Uz to, svako slovo sin iza kojeg sledi ta moglo je preći u sad, po glasovnom pravilu koje se naziva isti'la.","headingId":"oblik-musajtir","headingText":"Oblik musajtir"},{"text":"Zašto osmanski pravopis nije osavremenjen Nakon što su dodata nova pravopisna pravila i nakon što se arapsko pismo razvilo, postavilo se pitanje da li osavremeniti pravopis osmanskog mushafa. To su pitali imama Malika. Pitanje: Treba li Kur'an pisati prema novom pravopisu koji su ljudi razvili? Odgovor: Ne, treba ga pisati onako kako je izvorno pisan. Izvor: imam Malik. Sujuti, El Itkan, tom 2, str. 443. Kada je upitan o slovima u Kur'anu, o vavu, elifu i drugima, da li ih menjati ako se nađu, odgovorio je: „Ne.\" To prenosi i Dani u El Muknia, uz napomenu da se učenjaci u tome nisu razišli. Ed Dani, El Mukni. U vreme imama Ahmeda ibn Hanbela, kada je upitan o preuzimanju pravopisa koji","headingId":"zasto-osmanski-pravopis-nije-osavremenjen","headingText":"Zašto osmanski pravopis nije osavremenjen"},{"text":"su uveli gramatičari, rekao je: „Zabranjeno je suprotstaviti se imamskom mushafu, dakle osmanskom tekstu, u bilo kojem vavu, jau, elifu ili bilo čemu drugom.\" Ahmed ibn Hanbel.","headingId":"zasto-osmanski-pravopis-nije-osavremenjen","headingText":"Zašto osmanski pravopis nije osavremenjen"},{"text":"Ahmed el Džellad o kur'anskom pravopisu Ovo istraživanje pokazuje da je kur'anski pravopis višeslojan, a da razlike vode poreklo iz razdoblja pre ustaljivanja arapskog pravopisa. Pokušaj da se svako kur'ansko pisanje objasni ustaljenim savremenim pravopisnim pravilima pogrešan je. Objasniti ga može jedino istorijsko razumevanje predislamske pravopisne raznolikosti. Izvor: Ahmed el Džellad. Ahmad al Jallad, str. 15.","headingId":"ahmed-el-dzellad-o-kuranskom-pravopisu","headingText":"Ahmed el-Džellad o kur'anskom pravopisu"},{"text":"Zaključak Tvrdnja da Kur'an sadrži pravopisne greške počiva na slaboj i anahronoj pretpostavci, na tome da se drevni arapski pravopis prosuđuje po kasnijem savremenom arapskom pravopisu. Istraživanja ranih kur'anskih rukopisa, papirusa, natpisa i semitske lingvistike pokazuju da kur'anski pravopis odražava drevnu i doslednu arapsku pravopisnu tradiciju. Savremeni arapski pravopis je kasniji razvoj. Kur'an čuva raniju pisanu tradiciju.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Usmeni-prenos-Kurana-zasto-je-pamcenje-iznad-zapisa","chunks":[{"text":"Kod većine tekstova zapis je osnov, a usmeno prenošenje pomoć. Kod Kur'ana je obrnuto: učenje primljeno od učitelja je osnov, a zapis potpora. Zato je Osman uz svaki poslani mushaf poslao i učača, i zato su učenjaci izričito zabranjivali uzimanje Kur'ana samo iz knjige.","headingId":"","headingText":""},{"text":"Primanje traži slušanje Sura El A'raf 7:204 A kada se uči Kur'an, vi ga slušajte i ćutite da biste bili pomilovani. Naredba je usmerena na slušanje, a ne na čitanje, i to određuje način na koji se tekst prima.","headingId":"primanje-trazi-slusanje","headingText":"Primanje traži slušanje"},{"text":"Kada bi svi primerci nestali Zapis se može spaliti, izgubiti ili oštetiti. Ono što je u prsima ne može. U verodostojnoj predaji stoji da je Allah Poslaniku ﷺ objavio da je Kur'an takva knjiga koja se uči i kada je onaj ko je uči ne gleda u zapis, i da je vodom nije moguće isprati. Sahih Muslim, Knjiga o Džennetu. Ova osobina nije uzgredna. Ona menja samu prirodu pitanja o očuvanju. Kod teksta koji postoji samo u prepisima, pitanje glasi koliko su prepisi verni izvorniku. Kod teksta koji u svakom naraštaju u celini postoji u pamćenju hiljada ljudi, pitanje glasi da li su ti ljudi svi istovremeno pogrešili na isti način.","headingId":"kada-bi-svi-primerci-nestali","headingText":"Kada bi svi primerci nestali"},{"text":"Učenje sudi zapisu, a ne zapis učenju Ovo je tačka koja se najčešće izvrće. Osmanski zapis bio je bez tačaka i bez znakova za samoglasnike. On sam po sebi nije mogao odrediti kako se reč izgovara. Ono što je to određivalo bilo je primljeno učenje. Zapis je bio okvir koji je primljena učenja podnosio, a ne izvor iz kojeg su se ona izvodila. Odatle sledi važna posledica za tumačenje ranih rukopisa. Kada se u rukopisu nađe oblik koji odstupa, pitanje nije šta taj rukopis dopušta da se pročita, nego da li za taj oblik postoji lanac učenja. Bez lanca, to je pisarska pojava, a ne učenje.","headingId":"ucenje-sudi-zapisu-a-ne-zapis-ucenju","headingText":"Učenje sudi zapisu, a ne zapis učenju"},{"text":"Zašto je onda uopšte zapisano Zapisivanje pojedinačnih delova teklo je uporedo sa objavom, pred Poslanikom ﷺ. Sakupljanje razbacanih zapisa u jednu celinu usledilo je nakon bitke kod Jemame, u kojoj je poginuo veliki broj hafiza. Sahih Buhari, br. 4679, predaja Zejda ibn Sabita. Povod je, dakle, bio strah od gubitka nosilaca pamćenja, a ne sumnja u pamćenje kao takvo.","headingId":"zasto-je-onda-uopste-zapisano","headingText":"Zašto je onda uopšte zapisano"},{"text":"Osman je uz mushafe poslao učače Ovo je jedan od najrečitijih postupaka u celoj istoriji prenosa. Kada je Osman, radijallahu anhu, poslao primerke u pokrajine, uz svaki od njih poslao je i učača koji je ljude podučavao učenju. Da je zapis bio dovoljan, taj korak ne bi imao smisla. Slanje čoveka uz knjigu znači priznanje da knjiga sama ne prenosi ono što treba preneti. Taj postupak je, dakle, zvanično potvrđivanje da je usmeno primanje osnov.","headingId":"osman-je-uz-mushafe-poslao-ucace","headingText":"Osman je uz mushafe poslao učače"},{"text":"Sami ashabi stavljali su pamćenje iznad zapisa Ebu Seid el Hudri, radijallahu anhu, odbijao je zapisivanje i isticao praksu pamćenja. El Hatib el Bagdadi, Takjidul ilm. Ibn Mes'ud, radijallahu anhu, isticao je da je sure primio neposredno od Poslanika ﷺ, usmeno. Sahih Buhari, 6/102; Sahih Muslim, 4/1912.","headingId":"sami-ashabi-stavljali-su-pamcenje-iznad-zapisa","headingText":"Sami ashabi stavljali su pamćenje iznad zapisa"},{"text":"Učenjaci su zabranjivali učenje samo iz knjige Sulejman ibn Musa zabranjivao je uzimanje Kur'ana samo iz zapisa. Er Ramehurmuzi, El Muhaddisul fasil, 1/211. Seid ibn Abdul Aziz zabranjivao je učenje od onih koji su naučili iz mushafa bez učitelja. Ibn Ebu Hatim, El Džerhu vet ta'dil, 2/31. Ibn Tejmijje je isticao oslanjanje na ono što je u prsima, a ne na primerke. Ibn Tejmijje, Medžmu'ul fetava, 13/400. Ebul Akif Muhammed Emin naveo je da je lanac prenošenja nužan i da je izvođenje učenja zaključivanjem zabranjeno. Umdetul hullan šerhu Zubdetil irfan. Poslednja tačka je najstroža i najvažnija. Zabranjeno je izvoditi oblik učenja zaključivanjem, čak i kada je jezički ispravan i kada se uklapa u zapis. Mora biti primljen. To je merilo","headingId":"ucenjaci-su-zabranjivali-ucenje-samo-iz-knjige","headingText":"Učenjaci su zabranjivali učenje samo iz knjige"},{"text":"koje sprečava upravo ono za šta se prigovarači boje: da neko sam od sebe uvede oblik koji nije prenesen.","headingId":"ucenjaci-su-zabranjivali-ucenje-samo-iz-knjige","headingText":"Učenjaci su zabranjivali učenje samo iz knjige"},{"text":"Lanac ide do Džibrila Poslanik ﷺ nije Kur'an primio zapisan nego usmeno, od Džibrila, alejhis selam. Isti način prenosa nastavio se dalje, pa i danas svaki učač koji dobija idžazet ima imenovan niz učitelja koji vodi unazad do Poslanika ﷺ. Ibn el Džezeri istakao je prednost onoga što je u prsima nad onim što je u primercima. Ibn el Džezeri, En Nešr fil kiraatil ašr, 1/6.","headingId":"lanac-ide-do-dzibrila","headingText":"Lanac ide do Džibrila"},{"text":"Šta ovo znači u poređenju Kod drugih spisa put od izvornika do današnjeg teksta rekonstruiše se iz prepisa, poređenjem porodica rukopisa, uz aparat varijanti. Kod Kur'ana taj put ne mora se rekonstruisati, jer nikada nije bio prekinut. Postoji imenovan i proverljiv niz ljudi kroz koji je učenje prošlo. To ne znači da su drugi spisi time obezvređeni niti da je njihova rukopisna tradicija bezvredna. Znači samo da je vrsta dokaza različita. Jedno je zaključivanje unazad iz prepisa, drugo je neprekinut prenos unapred. Oba su legitimna postupka, ali ne daju istu vrstu izvesnosti.","headingId":"sta-ovo-znaci-u-poredjenju","headingText":"Šta ovo znači u poređenju"},{"text":"Zaključak Kur'an se prenosi na način koji ga čini nezavisnim od sudbine bilo kojeg pojedinačnog primerka. Zapis je uveden kao potpora, a ne kao osnov, i to su sami ashabi i kasniji učenjaci izričito i dosledno tvrdili, do te mere da su zabranjivali učenje bez učitelja.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Zasto-Allah-nije-sacuvao-Tevrat-i-Indzil","chunks":[{"text":"Allah nije obećao da će čuvati ranije objave onako kako je obećao za Kur'an. Odgovornost za čuvanje tih tekstova poverena je njihovim zajednicama. To potvrđuje i sam Kur'an u suri El Maida 5:44, a i biblijski tekstovi govore o povereništvu, poput Poslanice Rimljanima 3:1 2 i 1. Timoteju 1:11.","headingId":"","headingText":""},{"text":"Ajet o kojem je reč Sura El Hidžr 15:9 Mi, uistinu, Kur'an objavljujemo i zaista ćemo Mi nad njim bdeti. Pitanje koje postavljaju i sledbenici ranijih objava i ateisti glasi: zašto Allah nije sačuvao ranije knjige?","headingId":"ajet-o-kojem-je-rec","headingText":"Ajet o kojem je reč"},{"text":"Odgovor Allah nije obećao da će čuvati ranije objave onako kako je to obećao za Kur'an. Odgovornost za čuvanje tih tekstova poverena je njihovim zajednicama. Sura El Maida 5:44 Mi smo objavili Tevrat, u kojem je uputstvo i svetlo… prema onome što im je povereno od Allahove Knjige.","headingId":"odgovor","headingText":"Odgovor"},{"text":"Svedočanstva iz same Biblije Rimljanima 3:1 2 Šta dakle ima više Jevrejin, ili šta pomaže obrezanje? Mnogo, svakojako; prvo što su im poverene reči Božije. 1. Solunjanima 2:4 Nego kako nas okuša Bog da smo verni da primimo jevanđelje, tako govorimo, ne kao ljudima ugađajući, nego Bogu. 1. Timoteju 1:11 Po jevanđelju slave blaženoga Boga, koje je meni povereno. Ponovljeni zakon 6:17 I pazi dobro na zapovesti Gospoda Boga svog i na svedočanstva Njegova i na uredbe Njegove, koje ti je zapovedio. Na svim tim mestima objava se opisuje kao nešto što je zajednici povereno na čuvanje. To je bitno, jer se time ne poriče njena božanska objavljenost, nego se utvrđuje ko je za njeno čuvanje bio odgovoran.","headingId":"svedocanstva-iz-same-biblije","headingText":"Svedočanstva iz same Biblije"},{"text":"Priznanje iz Jeremije Jeremija 8:8 Kako govorite: Mudri smo, i zakon je Gospodnji u nas? Doista, gle, laž učini lažljiva pisaljka književnička.","headingId":"priznanje-iz-jeremije","headingText":"Priznanje iz Jeremije"},{"text":"Isto značenje u Kur'anu Sura El Bekara 2:79 A teško onima koji svojim rukama pišu Knjigu, a zatim govore: Evo, ovo je od Allaha. Sura Ali Imran 3:71 O sledbenici Knjige, zašto istinu neistinom zamračujete i svesno istinu krijete?","headingId":"isto-znacenje-u-kuranu","headingText":"Isto značenje u Kur'anu"},{"text":"Ni poslanicima nije bila obećana zaštita od ubistva Luka 13:34 Jerusalime, Jerusalime, koji ubijaš proroke i zasipaš kamenjem poslane k sebi. Ako ni sami poslanici nisu bili zaštićeni od ubistva, onda ni tekstovi koji su ljudima povereni nisu imali jamstvo koje im ljudi pripisuju.","headingId":"ni-poslanicima-nije-bila-obecana-zastita-od-ubistva","headingText":"Ni poslanicima nije bila obećana zaštita od ubistva"},{"text":"Zašto takav poredak uopšte Postavlja se dalje pitanje: zašto bi Allah čuvanje poveravao ljudima, znajući ishod? Odgovor leži u svrsi ranijih objava. Ranije objave bile su upućene određenom narodu, u određenom razdoblju, i imale su rok. Nakon njih dolazio je novi poslanik, sa novom objavom, koja je prethodnu potvrđivala i ispravljala. Poslednja objava nema naslednika. Nakon nje ne dolazi poslanik koji bi ispravio ono što se pokvarilo. Zato njeno čuvanje nije moglo biti prepušteno istom poretku. Ovo je unutrašnja doslednost, a ne naknadno objašnjenje. Konačnost poslanstva i jemstvo čuvanja idu zajedno. Objava koja je poslednja mora biti sačuvana neposredno, jer za nju nema popravke; objava koja nije poslednja ne mora, jer za nju popravka dolazi.","headingId":"zasto-takav-poredak-uopste","headingText":"Zašto takav poredak uopšte"},{"text":"Način prenošenja Biblija se oslanjala na rukopisno prenošenje, dok se Kur'an prenosio dvostruko, i pamćenjem i pisanjem. Jemstvo, međutim, nije značilo da se tekst čuva bez ljudskog rada. Ono se ostvarilo kroz sredstva koja se mogu proveriti: 1. Masovno pamćenje u svakom naraštaju, a ne samo kod pisarske struke. 2. Godišnje ponavljanje pred Džibrilom , dva puta u godini Poslanikove ﷺ smrti. 3. Zapisivanje pred Poslanikom ﷺ , uz njegovu neposrednu proveru. 4. Sakupljanje sa dvostrukom potvrdom u vreme Ebu Bekra, zapisom i svedočenjem. 5. Ujednačavanje i slanje primeraka uz učače u vreme Osmana. 6. Nauka o kiraetima , koja svaki oblik učenja vezuje za imenovan i proveren lanac. Zabrane dodavanja i oduzimanja u samim ranijim spisima, poput onih u","headingId":"nacin-prenosenja","headingText":"Način prenošenja"},{"text":"Ponovljenom zakonu 4:2 i 12:32, potvrđuju isti zaključak sa druge strane. Zabrana ima smisla samo tamo gde je prekršaj moguć. Da je tekst bio neposredno zaštićen, upozorenje ne bi imalo predmet.","headingId":"nacin-prenosenja","headingText":"Način prenošenja"},{"text":"Zaključak Allah je ranije objave poverio njihovim zajednicama na čuvanje, a ne Sebi. Te zajednice tu odgovornost nisu ispunile, i zato je objavljen Kur'an, kao konačna poruka koju Allah Sam čuva.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Zasto-je-Osman-spalio-mushafe","chunks":[{"text":"Osman nije izmislio, izmenio niti prikrio Kur'an. On je ujednačio zapisani mushaf prema proverenoj zbirci koja je čuvana kod Hafse. Spaljivanje ostalih primeraka bio je čin očuvanja, a ne iskrivljavanja, jer je ummet zaštitio od podele. Sam Alija ibn Ebu Talib izjavio je da je Osman postupio tek nakon saglasnosti ashaba i da bi on, da je bio na njegovom mestu, učinio isto.","headingId":"","headingText":""},{"text":"Povod Huzejfa ibn el Jeman se uznemirio nakon što je tokom vojnih pohoda video da muslimani iz različitih krajeva uče različito. Pobojao se da će ummet zapasti u razilaženje oko Knjige, kao što se to dogodilo Jevrejima i hrišćanima. Osman je zatražio zapisane listove koji su čuvani kod Hafse, obrazovao odbor u kojem je bio i Zejd ibn Sabit, i naredio da se prepišu provereni primerci i razašalju. Nakon što su načinjeni zvanični primerci, naredio je da se ostali zapisani materijali uklone, kako se ummet ne bi podelio oko nezvaničnih ličnih primeraka. Ibn el Arebi, El Avasim minel kavasim.","headingId":"povod","headingText":"Povod"},{"text":"Razlika između sakupljanja i ujednačavanja Ibn el Arebi je razlikovao ranije očuvanje od kasnijeg osmanskog ujednačavanja. Kur'an je već bio sakupljen pre Osmanovog postupka. Ebu Bekrovo sakupljanje sačuvalo je Kur'an u pisanom obliku nakon što je poginuo velik broj učača. Osmanovo ujednačavanje razaslalo je zvanične primerke i objedinilo ummet na jednoj odobrenoj pisanoj verziji. Reč je, dakle, o dva različita postupka. Ebu Bekr je Kur'an sakupio na jedno mesto, a Osman je zapisani tekst ujednačio i razaslao. Osman nije sakupljao ono što nije postojalo, nego je ujednačio ono što je već bilo sakupljeno.","headingId":"razlika-izmedju-sakupljanja-i-ujednacavanja","headingText":"Razlika između sakupljanja i ujednačavanja"},{"text":"Stav ashaba Osim Ibn Mes'uda, koji je kasnije povukao svoju primedbu, nijedan ashab se nije usprotivio Osmanovom postupku. Osman se posavetovao sa muhadžirima, ensarijama i prvacima muslimanske zajednice, i oni su se sa njim složili u pogledu sakupljanja i ujednačavanja. To, dakle, nije bio Osmanov lični politički čin, nego odluka zajednice.","headingId":"stav-ashaba","headingText":"Stav ashaba"},{"text":"Svedočanstvo Alije ibn Ebu Taliba Alija ibn Ebu Talib izjavio je da je Osman u vezi sa mushafima postupio tek nakon saglasnosti ashaba, i da bi on, da je bio na Osmanovom mestu, učinio isto. To izravno pobija tvrdnju da je Osman postupio sam ili da su stariji ashabi odbacili njegovu odluku.","headingId":"svedocanstvo-alije-ibn-ebu-taliba","headingText":"Svedočanstvo Alije ibn Ebu Taliba"},{"text":"Osmanov metod sedam načela Kadija Bakillani naveo je da je Osman želeo da ih objedini prema utvrđenim učenjima poznatim od Poslanika ﷺ, i da ukine ono što nije bilo takvo. El Kadi el Bakillani. Ibn Hazm je objasnio da se Osman pobojao da bi obmana ili greška mogle iskvariti tekst, pa je zato zapisao mushafe oko kojih postoji saglasnost i poslao po jedan mushaf u svaku pokrajinu. Ibn Hazm. Nevevi je naveo da je Osman prepisivao iz zbirke koju je imala Hafsa, oko koje su se ashabi bili složili, u primerke koje je razaslao zemljama. En Nevevi. Njegov rad vodilo je sedam načela: 1. Oslanjanje na Ebu Bekrovu zbirku. Osman je zatražio izvorne listove od Hafse, da bi osigurao neprekinutost","headingId":"osmanov-metod-sedam-nacela","headingText":"Osmanov metod - sedam načela"},{"text":"između ranije zbirke i novih primeraka. 2. Nadzor odbora. Osman je okupio dvanaest ljudi iz Kurejša i ensarija, među njima Ubejja ibn Ka'ba i Zejda ibn Sabita, uz lični nadzor. 3. Učešće javnosti. Ljudi su pozvani da donesu zapisane delove koje su primili neposredno od Poslanika ﷺ, uz proveru ispitivanjem. 4. Prednost kurejšijskog jezika. Kada bi došlo do spora, Osman je nalagao: „Zapišite to jezikom Kurejša, jer je na njihovom jeziku i objavljen.\" 5. Isključivanje nekanonske građe. Derogirana učenja, pojedinačne vesti i objašnjavajuće beleške namerno su isključeni iz zvaničnih primeraka. 6. Prilagođavanje različitim učenjima. Reči koje je Poslanik ﷺ izgovarao na više načina zapisivane su tako da rasm dopušta više verodostojnih učenja. Kada se dva učenja nisu mogla obuhvatiti jednim","headingId":"osmanov-metod-sedam-nacela","headingText":"Osmanov metod - sedam načela"},{"text":"zapisom, različiti primerci beležili su različite oblike, u skladu sa proverenim učenjima. 7. Više faza provere. Zejd ibn Sabit pregledao je glavni primerak, a Osman je lično pregledao primerke pre razašiljanja. Šesto načelo objašnjava mnogo toga što se kasnije predstavlja kao nedoslednost. Odsustvo tačaka i pojedine pravopisne odluke nisu bile slučajne, nego namerne, upravo zato da bi jedan zapis mogao nositi više dopuštenih učenja. Ashabi su postupali sa krajnjom preciznošću, pa su ponekad odlagali dovršenje kako bi proverili da li odsutni pojedinci poseduju odgovarajuće delove, pre nego što bi konačno utvrdili mesto teksta.","headingId":"osmanov-metod-sedam-nacela","headingText":"Osmanov metod - sedam načela"},{"text":"Pitanje onoga što nije ušlo u mushaf Predaje o materijalu koji se ne nalazi u konačnom osmanskom mushafu odnose se na ono čije je učenje derogirano, a ne na ajete koji su izgubljeni. To se mora razumeti kroz nauku o nesh et tilavetu, dakle o derogaciji učenja.","headingId":"pitanje-onoga-sto-nije-uslo-u-mushaf","headingText":"Pitanje onoga što nije ušlo u mushaf"},{"text":"Zašto su pojedine predaje slabe Pojedini prigovori protiv osmanskog sakupljanja oslanjaju se na predaje koje nisu dovoljno jake da bi nadjačale opštepoznatu, masovno prenesenu istoriju očuvanja Kur'ana. Predaje koje idu preko slabih prenosilaca iziskuju opreznost, jer su hadiski učenjaci kritikovali pouzdanost i preciznost tih prenosilaca.","headingId":"zasto-su-pojedine-predaje-slabe","headingText":"Zašto su pojedine predaje slabe"},{"text":"Predaja iz Tarihul Medine Ponekad se navodi predaja iz dela Tarihul Medina od Ibn Šebbe, u vezi sa onim što je Osman učinio sa ostalim zapisanim primercima. Sa tom predajom postoje dva problema. Prvo, jezičko pitanje. U predaji se koristi glagol šekka, koji ne znači spaliti. On znači rascepiti, razderati, preseći, razdvojiti ili odvojiti. Prevoditi šekka kao „spalio\" nije precizno, jer sama arapska formulacija to ne podupire. Drugo, slabost lanca. U lancu te predaje nalazi se Rebi ibn Bedr es Sa'di et Temimi, kojeg su hadiski kritičari ocenili slabim, među njima i Nesai. Ibn Šebbe, Tarihul Medina; ocena Nesaija o Rebiu ibn Bedru. Ta se predaja, dakle, navodi da bi se dokazalo spaljivanje, a u njoj stoji glagol koji spaljivanje","headingId":"predaja-iz-tarihul-medine","headingText":"Predaja iz Tarihul-Medine"},{"text":"uopšte ne znači. Uz to, i sama je slaba. Slaba predaja sa kritikovanim prenosiocem ne može nadjačati jače i opštepoznate izveštaje o osmanskom ujednačavanju.","headingId":"predaja-iz-tarihul-medine","headingText":"Predaja iz Tarihul-Medine"},{"text":"Svedočanstvo orijentaliste Jedan orijentalista priznao je da je Osmanov mushaf bio potpun, veran svom izvoru, i da je od samog početka uživao zvanično priznanje u muslimanskoj zajednici. To pokazuje da ni izvan islamske nauke pojednostavljena optužba ne stoji lako.","headingId":"svedocanstvo-orijentaliste","headingText":"Svedočanstvo orijentaliste"},{"text":"Zaključak Osman ibn Affan nije izmislio, izmenio niti prikrio Kur'an. Ujednačio je zapisani mushaf prema proverenoj zbirci koja je čuvana kod Hafse. Spaljivanje primeraka bio je čin očuvanja, a ne iskrivljavanja, jer je zaštitio ummet od podele. Posavetovao se sa ashabima. Oni su se sa njim složili. Alija ga je branio. Ummet je taj mushaf prihvatio.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Zasto-je-ostao-jedan-harf","chunks":[{"text":"Sedam harfova ne znači da svaka kur'anska reč ima sedam oblika, nego da su ti oblici prisutni na različitim mestima. Kurejšijsko narečje bilo je mešavina narečja svih arapskih plemena, jer su Kurejšije te oblike preuzimale na hadžskim sezonama i sajmovima. Ujednačavanje na taj harf nije izgubilo očuvanje, jer je ummetu ostavljen izbor, kao što je izbor ostavljen i u drugim propisima.","headingId":"","headingText":""},{"text":"Šta znači sedam harfova Učenjaci su se razišli o značenju sedam harfova, a većina tih mišljenja međusobno se prepliće. Većina učenjaka kaže da se pod sedam harfova misli na sedam arapskih jezika, odnosno narečja, sa jednim značenjem. To znači da, kada se narečja arapskog jezika razlikuju u izražavanju nekog značenja, Kur'an biva objavljen rečima koje tim narečjima odgovaraju za to jedno značenje. Tamo gde razlike nema, dolazi jedna reč ili više njih. To znači da su ti harfovi u Kur'anu prisutni u različitim oblicima, a ne da svaka kur'anska reč ima sedam narečja. Pogrešno razumevanje te tačke izvor je većine zabuna o ovoj temi.","headingId":"sta-znaci-sedam-harfova","headingText":"Šta znači sedam harfova"},{"text":"Zašto je Kur'an objavljen na sedam harfova 1. Umnožavanje propisa umnožavanjem harfova. Jedan harf izgovoren na jedan način nosi jedan propis i značenje, a izgovoren na drugi način nosi drugi propis i značenje, što daje lepotu i potpunost. 2. Otklanjanje teškoće , jer se isto značenje može učiti različitim rečima, a u proširenju reči nema smetnje sve dok je značenje isto. 3. Da je objavljen na jednom narečju, govornicima drugih narečja bilo bi teško da pređu sa svog govora na drugi.","headingId":"zasto-je-kuran-objavljen-na-sedam-harfova","headingText":"Zašto je Kur'an objavljen na sedam harfova"},{"text":"Zašto baš kurejšijsko narečje Sedam harfova bilo je uobičajeno u jeziku Kurejša, jer je on bio mešavina jezika i narečja svih arapskih plemena. Kurejšije su te jezike i narečja neprekidno preuzimale tokom hadžskih sezona, kada su se plemena susretala na njihovim sajmovima i skupovima. To je i najrečitije arapsko narečje, zbog svoje udaljenosti od persijskih zemalja. Zato su i ostala arapska plemena pribegavala jeziku Kurejša u svakom jezičkom sporu koji bi među njima nastao.","headingId":"zasto-bas-kurejsijsko-narecje","headingText":"Zašto baš kurejšijsko narečje"},{"text":"Kako je došlo do ujednačavanja Ljudi su Kur'an zapisivali prema onim harfovima koji su do njih doprli. Sa širenjem učača po muslimanskim zemljama, i sa tim da su se stanovnici svakog kraja ograničavali na određeno učenje, došlo je do toga da su se stanovnici Šama i stanovnici Kufe sreli u pohodu na Jermeniju i Azerbejdžan i razišli se u učenju Kur'ana, što je dovelo do spora i sukoba koji je zamalo prerastao u veliku smutnju. Zato je Osman, radijallahu anhu, odlučio da mushafe muslimana ujednači u jedan primerak, zapisan na jednom harfu, kurejšijskom. Ostali utvrđeni harfovi i dalje se mogu učiti u okviru tog istog zapisa ili njemu bliskog. To je Osman i učinio, a ostali ashabi su se sa","headingId":"kako-je-doslo-do-ujednacavanja","headingText":"Kako je došlo do ujednačavanja"},{"text":"njim složili i njegov postupak odobrili.","headingId":"kako-je-doslo-do-ujednacavanja","headingText":"Kako je došlo do ujednačavanja"},{"text":"Zašto to nije gubitak Ummet time nije izgubio očuvanje Kur'ana, jer je Uzvišeni Allah dao izbor da se Kur'an pamti i uči na bilo koji od tih sedam harfova, kao što je izbor dao i u drugim stvarima, poput otkupa za prekršenu zakletvu. To poređenje je precizno. Kada šerijat nudi više dopuštenih mogućnosti, izbor jedne od njih ne poništava ostale niti znači da je nešto izgubljeno. Isto važi i za harfove.","headingId":"zasto-to-nije-gubitak","headingText":"Zašto to nije gubitak"},{"text":"Nema protivrečnosti među harfovima Među muslimanima nema spora o tome da sedam harfova na kojima je Kur'an objavljen ne sadrže protivrečnost niti suprotstavljanje u značenju. Njihova značenja mogu biti ista ili slična, kako je rekao Ibn Mes'ud, radijallahu anhu: „To je kao kada neko od vas kaže: dođi, dođi, dođi.\" Značenje jednog može se i razlikovati od značenja drugog, ali su oba značenja istinita, i to je razlika raznolikosti i različitosti, a ne razlika suprotstavljanja i sukoba.","headingId":"nema-protivrecnosti-medju-harfovima","headingText":"Nema protivrečnosti među harfovima"}]},{"slug":"Zasto-kiraet-Ibn-Mesuda-nije-u-osmanskom-mushafu","chunks":[{"text":"Zejdovo učenje bilo je učenje poslednjeg izlaganja Kur'ana Poslaniku ﷺ. Uz to, današnji mushaf prenosi i učenje Ibn Mes'uda kroz više lanaca, jer je Asim učio pred Ebu Abdur Rahmanom, a od Ibn Mes'uda su učili i Alkama, Esved, Ibn Vehb, Mesruk i drugi. I sam Ibn Mes'ud prihvatao je različita učenja, a Alija je posvedočio da je Osman postupio uz saglasnost svih.","headingId":"","headingText":""},{"text":"Prvo pitanje poslednjeg izlaganja Zejd ibn Sabit, radijallahu anhu, učio je onako kako je glasilo poslednje izlaganje Kur'ana. Koje od dva učenja smatrate ranijim? Rekli su: Abdullahovo. Rekao je: Ne, nego je ono poslednje. Izvor: Musned imama Ahmeda. Musned Ahmed, br. 3422. Samura ibn Džundub naveo je: „Kur'an je izlagan Allahovom Poslaniku ﷺ u izlaganjima. Kažu: naše učenje je poslednje izlaganje.\" El Mustedrek, br. 2857. Ibn Hadžer je potvrdio da je taj hadis sličan hadisu Ibn Abbasa. Ibn Hadžer, Fethul bari.","headingId":"prvo-pitanje-poslednjeg-izlaganja","headingText":"Prvo - pitanje poslednjeg izlaganja"},{"text":"Drugo današnji mushaf prenosi i Ibn Mes'udovo učenje Tahavi je naveo: „Asim je učio pred Ebu Abdur Rahmanom, Ebu Abdur Rahman pred Alijom, a Alija pred Poslanikom ﷺ.\" Et Tahavi, Muškilul asar, prvi deo. Ibn el Džezeri je zabeležio da su pred Abdullahom ibn Mes'udom učili i Alkama, Esved, Ibn Vehb, Mesruk, Asim ibn Damra i Haris. Ibn el Džezeri, En Nešr fil kiraatil ašr, prvi deo, str. 165. To je ključno. Tvrdnja da je Ibn Mes'udovo učenje odbačeno pretpostavlja da je ono nestalo. Ali ono i danas živi kroz prenosne lance koji idu preko njegovih učenika, pa i kroz Asimov kiraet, koji je najrašireniji u svetu.","headingId":"drugo-danasnji-mushaf-prenosi-i-ibn-mesudovo-ucenje","headingText":"Drugo - današnji mushaf prenosi i Ibn Mes'udovo učenje"},{"text":"Treće sam Ibn Mes'ud prihvatao je različita učenja Slušao sam učenja i našao sam ih bliskim jedna drugima, pa učite onako kako ste naučili. Izvor: Ibn Mes'ud. Ebu Ubejd, Fedailul Kur'an.","headingId":"trece-sam-ibn-mesud-prihvatao-je-razlicita-ucenja","headingText":"Treće - sam Ibn Mes'ud prihvatao je različita učenja"},{"text":"Četvrto saglasnost ashaba Tako mi Allaha, on ih nije spalio osim uz odobrenje svih nas. Alija je rekao: Da sam ja bio na vlasti, učinio bih ono što je i on učinio. Izvor: Alija ibn Ebu Talib. Ibn Ebu Davud es Sidžistani, Kitabul mesahif.","headingId":"cetvrto-saglasnost-ashaba","headingText":"Četvrto - saglasnost ashaba"},{"text":"Peto Osmanovi primerci poklapali su se sa Ebu Bekrovom zbirkom Zejd ibn Sabit je izvestio: „Pokazao sam mushaf, i nisu se razišli ni u čemu.\" Prikaz objašnjenja teških hadisa, osmi deo, str. 127.","headingId":"peto-osmanovi-primerci-poklapali-su-se-sa-ebu-bekrovom-zbirkom","headingText":"Peto - Osmanovi primerci poklapali su se sa Ebu Bekrovom zbirkom"},{"text":"Šesto svedočanstvo Ibn Abbasa Ibn Abbas je potvrdio očuvanje: „Nije ostavio ništa osim onoga što je između dve korice.\" Sahih Buhari, br. 4731. Današnji mushaf prenosi se i preko potvrđenih lanaca od Ibn Abbasa, preko Mudžahida, koji je pred Ibn Abbasom proučio Kur'an od početka do kraja tri puta. Musannef Ibn Ebu Šejbe, br. 32293 32294.","headingId":"sesto-svedocanstvo-ibn-abbasa","headingText":"Šesto - svedočanstvo Ibn Abbasa"},{"text":"Sedmo postepeno uvođenje tačaka Tačkovanje je postojalo i pre Osmana, ali nije bilo uobičajeno. Sanski rukopis pokazuje da je jedan prepisivač bio sklon da tačkuje slovo ta. Behnam Sadeghi, The Codex of a Companion of the Prophet, str. 354 356. Kur'an je u mushafima bio ogoljen, pa je prvo što su stavili bile tačke na ja i ta. Izvor: El Muhkem fi naktil mesahif. El Muhkem fi naktil mesahif. Ibrahim je prezirao tačke u mushafu, dok je Rebia rekao: „U tome nema smetnje.\" Ibn Ebu Davud, Kitabul mesahif.","headingId":"sedmo-postepeno-uvodjenje-tacaka","headingText":"Sedmo - postepeno uvođenje tačaka"},{"text":"Zaključak Osmanski mushaf odražava poslednje učenje izloženo pre Poslanikove ﷺ smrti. Sva verodostojna učenja, uključujući i učenja Ibn Mes'uda i Ubejja ibn Ka'ba, uklapaju se u sedam harfova koje je Poslanik ﷺ dopustio. Tačke su dodavane postepeno radi jasnoće, a ne radi izmene teksta. Sura El Hidžr 15:9 Mi, uistinu, Kur'an objavljujemo i zaista ćemo Mi nad njim bdeti.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Zasto-Kuran-nije-sakupljen-za-Poslanikovog-zivota","chunks":[{"text":"Odgovor je jednostavniji nego što primedba pretpostavlja. Objava je trajala do poslednjih dana Poslanikovog ﷺ života, pa nijedna zbirka pre toga ne bi bila potpuna. Uz to, derogacija je bila u toku, pa bi zatvorena knjiga sadržala i ono što je kasnije stavljeno van snage. Raspored ajeta i sura bio je, međutim, poznat i utvrđen još tada.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Pita se zašto Kur'an nije sakupljen u jednu knjigu dok je Poslanik ﷺ bio živ, ako je već bio toliko važan, i zašto je to prepušteno ljudima nakon njega.","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Prvi razlog potrebe još nije bilo Ono što je kasnije nateralo na sakupljanje bilo je stanje koje tada nije postojalo. 1. Nosilaca teksta bilo je mnogo , i bili su na okupu. Hafiza je bilo u velikom broju, u istom gradu, i međusobno su se proveravali svakodnevno. 2. Zajednica se još nije bila raširila. Razilaženja u učenju među udaljenim pokrajinama, koja su kasnije bila povod, još nisu mogla nastati. 3. Materijal za pisanje bio je redak i skup , a knjiga u današnjem smislu nije bila uobičajen oblik čuvanja teksta. 4. Poslanik ﷺ je bio prisutan. Svako nejasno mesto rešavalo se pitanjem njemu, neposredno, pa nije postojalo pitanje na koje bi knjiga trebalo da odgovori. Poslednja tačka je najvažnija. Zapisana","headingId":"prvi-razlog-potrebe-jos-nije-bilo","headingText":"Prvi razlog - potrebe još nije bilo"},{"text":"knjiga postoji da bi zamenila prisustvo izvora. Dok je izvor prisutan, ona ne rešava nijedan problem koji već nije rešen. Prva zbirka i nastaje tačno u trenutku kada to prisustvo prestaje i kada nosioci pamćenja počinju da ginu. Isto zapažanje nalazi se i kod kasnijih obrađivača ove teme, među kojima su Sujuti, Kastalani, ed Dejrakuli, Taberi i Zuhri.","headingId":"prvi-razlog-potrebe-jos-nije-bilo","headingText":"Prvi razlog - potrebe još nije bilo"},{"text":"Drugi razlog objava je još trajala Objava je pristizala u razmacima kroz dvadeset i tri godine, a poslednji ajeti objavljeni su neposredno pred Poslanikovu ﷺ smrt. Svaka zbirka sačinjena pre tog trenutka bila bi nepotpuna već sutradan. Ovo je odlučujuće, a često se previđa. Zatvoriti knjigu znači proglasiti je dovršenom. Dok objava traje, takvo proglašenje nije moguće. Tražiti da je Poslanik ﷺ zatvorio knjigu za života znači tražiti da je unapred proglasio kraj objave, koju nije on određivao.","headingId":"drugi-razlog-objava-je-jos-trajala","headingText":"Drugi razlog - objava je još trajala"},{"text":"Treći razlog derogacija je bila u toku Za Poslanikovog ﷺ života pojedini ajeti bili su derogirani, u učenju ili u propisu. Da je tekst bio uvezan u zatvorenu knjigu ranije, u njoj bi ostalo i ono što je kasnije stavljeno van snage, što bi stvorilo zabunu upravo u onome što se htelo sačuvati. Zato je čuvanje teklo kroz pamćenje i kroz pojedinačne zapise, sve dok derogacija nije prestala Poslanikovom ﷺ smrću.","headingId":"treci-razlog-derogacija-je-bila-u-toku","headingText":"Treći razlog - derogacija je bila u toku"},{"text":"Šta je onda postojalo Ne treba, međutim, misliti da tekst nije bio zapisan. Postojale su dve stvari istovremeno: Zapisi. Svaki objavljeni deo zapisan je pred Poslanikom ﷺ, na materijalu koji je bio dostupan: palmino lišće, kamene ploče, komadi kože. Pamćenje. Veliki broj ashaba znao je tekst napamet u celini. Sura El A'la 87:6 Mi ćemo te naučiti da učiš, pa ništa nećeš zaboraviti. Kada je Zejd ibn Sabit, radijallahu anhu, kasnije pristupio sakupljanju, on je tražio upravo te postojeće zapise i uporedo ih potvrđivao svedočenjem hafiza. Sahih Buhari. Iz toga sledi da prva zbirka nije bila pisanje teksta iz sećanja nego prikupljanje već postojećih zapisa uz proveru. Razlika je bitna: sakupljalo se ono što je već bilo zapisano pred Poslanikom","headingId":"sta-je-onda-postojalo","headingText":"Šta je onda postojalo"},{"text":"ﷺ, a ne ono čega se neko naknadno prisetio.","headingId":"sta-je-onda-postojalo","headingText":"Šta je onda postojalo"},{"text":"O tvrdnji da su se ashabi razišli Iznosi se i tvrdnja da neslaganje ashaba o tome treba li sakupljati pokazuje nesigurnost. Ono što se u izvorima naziva neslaganjem bilo je Ebu Bekrovo početno oklevanje pred postupkom koji Poslanik ﷺ nije izričito naredio, dakle pravna obazrivost, a ne sumnja u tekst. To oklevanje razrešeno je razgovorom, a ishod su prihvatili svi, bez ijednog zabeleženog protivljenja.","headingId":"o-tvrdnji-da-su-se-ashabi-razisli","headingText":"O tvrdnji da su se ashabi razišli"},{"text":"Raspored ajeta Raspored ajeta unutar sura nije bio prepušten nikome nakon Poslanika ﷺ. Osman ibn Affan, radijallahu anhu, preneo je da je Poslanik ﷺ, kada bi mu nešto bilo objavljeno, pozivao pisara i određivao u koju suru i na koje mesto ajet ide. El Musned i Es Sunen, preko Ibn Abbasa. Imam Malik naveo je da su ashabi Kur'an sastavili samo prema onome što su čuli od Poslanika ﷺ. Imam Malik.","headingId":"raspored-ajeta","headingText":"Raspored ajeta"},{"text":"Raspored sura Ovde među učenjacima postoji stvarno razilaženje, i pošteno je to reći. Ibn el Enbari smatra da je raspored sura u celini utvrđen objavom. Ibn el Enbari. Ibn Atijja smatra da je za deo sura raspored bio poznat još za Poslanikovog ﷺ života, i navodi sedam dugih sura, sure koje počinju sa Ha Mim i mufassal, dok je za ostale prepušteno kasnijem uređenju. Ibn Atijja. Zerkeši je zaključio da je to razilaženje uglavnom rečničko, a ne suštinsko. Ez Zerkeši, El Burhan. Razilaženje o rasporedu sura ne dodiruje pitanje očuvanja teksta. Ono se tiče redosleda celina, a ne njihovog sadržaja. Čak i kod najšireg stava, nijedan učenjak ne tvrdi da je nešto dodato ili izostavljeno.","headingId":"raspored-sura","headingText":"Raspored sura"},{"text":"Dokazi da je raspored bio poznat Više predaja pokazuje da su sure i njihov međusobni odnos bili poznati i imenovani još tada: En Nevvas ibn Sem'an, radijallahu anhu, prenosi hadis u kojem se sure El Bekara i Ali Imran spominju zajedno i po imenu. Sahih Muslim. Ebu Hurejra, radijallahu anhu, prenosi hadis o kući u kojoj se uči sura El Bekara. Huzejfa, radijallahu anhu, opisuje noćni namaz sa Poslanikom ﷺ, navodeći sure po imenu i redosledu učenja. Sahih Buhari; Sahih Muslim. U dvema zbirkama zabeležen je i slučaj sklapanja braka u kojem je mehr bilo ono što je čovek znao iz Kur'ana, po surama. Abdur Rahman ibn Jezid prenosi od Ibn Mes'uda, radijallahu anhu, da je sure El Isra, El","headingId":"dokazi-da-je-raspored-bio-poznat","headingText":"Dokazi da je raspored bio poznat"},{"text":"Kehf i Merjem nazivao ranima. Sahih Buhari. Evs ibn Ebu Evs, radijallahu anhu, prenosi podelu Kur'ana na skupine sura radi učenja. Musned Ahmed.","headingId":"dokazi-da-je-raspored-bio-poznat","headingText":"Dokazi da je raspored bio poznat"},{"text":"Imena sura Sujuti je naveo da su i imena sura potvrđena objavom. Es Sujuti, El Itkan. Navedene predaje to potkrepljuju, jer se u njima sure oslovljavaju imenima kao nečim opšte poznatim, bez ikakvog objašnjavanja.","headingId":"imena-sura","headingText":"Imena sura"},{"text":"Zaključak 1. Zbirka nije zatvorena ranije jer objava još nije bila dovršena. 2. Derogacija je bila u toku, pa bi zatvorena knjiga sadržala i stavljeno van snage. 3. Tekst je istovremeno postojao zapisan i zapamćen. 4. Raspored ajeta bio je određen uputom, a ne kasnijom procenom. 5. Imena sura i njihov međusobni odnos bili su opšte poznati još tada.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Zuhrijeva-slaba-predaja-o-izgubljenom-Kuranu","chunks":[{"text":"Zuhrijeva izjava koristi izraz „doprlo nam je\", bez navođenja izvora. Jahja ibn Seid el Kattan naveo je da je Zuhrijev mursel gori od mursela drugih, upravo zato što je Zuhri bio hafiz koji je imenovao svakoga koga je mogao imenovati. Šafija je naveo da takav prenos nema vrednost, a Ibn Redžeb da su Zuhrijevi murseli među najslabijima. Priređivač samog dela to takođe priznaje.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Tvrdi se da je velik deo Kur'ana izgubljen. Kao dokaz navodi se predaja koju beleži Ibn Ebu Davud, preko Ebu Rebia, od Junusa i Ibn Šihaba, u kojoj stoji da je velik deo Kur'ana bio objavljen, a da su njegovi znalci koji su ga znali napamet izginuli na dan Jemame.","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Prvo predaja je slaba Verodostojan hadis iziskuje pet uslova: neprekinut prenos, pravednost prenosioca, njegovu preciznost, odsustvo neuobičajenosti i odsustvo skrivene mane. Zuhrijeva izjava koristi izraz „doprlo nam je\", bez navođenja izvora. Zuhrijev mursel gori je od mursela drugih, zato što je on hafiz i imenuje sve koga je u stanju da imenuje. Izvor: Jahja ibn Seid el Kattan. Jahja ibn Seid el Kattan. To je precizan argument, vredan pažnje. Kod prenosioca slabijeg pamćenja izostavljanje imena moglo bi biti puka nemarnost. Kod Zuhrija, koji je bio poznat po tome da imenuje svakoga koga može, izostavljanje imena upućuje na to da izvor nije bio takav da bi ga vredelo navesti. Imam Šafija je naveo da takav prenos nema nikakvu vrednost. Imam Šafija.","headingId":"prvo-predaja-je-slaba","headingText":"Prvo - predaja je slaba"},{"text":"Ibn Redžeb el Hanbeli naveo je da su Zuhrijevi mursel hadisi među najslabijim mursel hadisima. Ibn Redžeb el Hanbeli. Ibn Abdul Hadi el Makdisi prenosi da je Jahja el Kattan za te hadise rekao da su „poput vetra\". Ibn Abdul Hadi el Makdisi.","headingId":"prvo-predaja-je-slaba","headingText":"Prvo - predaja je slaba"},{"text":"Drugo i priređivač dela priznaje slabost Dr Muhibbudin je naveo da učenjaci ne prihvataju Zuhrijeve mursele i njegove takve izveštaje. Dr Muhibbudin, priređivač dela.","headingId":"drugo-i-priredjivac-dela-priznaje-slabost","headingText":"Drugo - i priređivač dela priznaje slabost"},{"text":"Treće Poslanik ﷺ nije ostavio ništa osim onoga što imamo Ibn Abbas je izvestio: „Nije ostavio ništa osim onoga što je između dve korice.\" Sahih Buhari.","headingId":"trece-poslanik-nije-ostavio-nista-osim-onoga-sto-imamo","headingText":"Treće - Poslanik ﷺ nije ostavio ništa osim onoga što imamo"},{"text":"Četvrto Allahovo obećanje Sura Fussilet 41:41 42 A on je, zaista, knjiga zaštićena, laž joj je strana, bilo s koje strane.","headingId":"cetvrto-allahovo-obecanje","headingText":"Četvrto - Allahovo obećanje"},{"text":"Peto šta se na Jemami zaista dogodilo Pogibija hafiza kod Jemame jeste istorijska činjenica i ona se ne poriče. Ali ono što iz nje sledi upravo je suprotno od onoga što se tvrdi. Ta pogibija bila je povod za prvo sakupljanje, dakle za postupak kojim je tekst osiguran. Ovde postoji unutrašnja nedoslednost u samoj primedbi. Ista pogibija ne može istovremeno biti dokaz da je tekst izgubljen i povod za postupak koji je tekst sačuvao. Izvori je navode upravo u drugom kontekstu, kao razlog zbog kojeg se pristupilo sakupljanju, a ne kao izveštaj o gubitku. Uz to, tekst nije bio raspoređen tako da bi ga pogibija jedne skupine mogla ukloniti. Svaki deo znalo je napamet mnoštvo ljudi, na različitim mestima, a","headingId":"peto-sta-se-na-jemami-zaista-dogodilo","headingText":"Peto - šta se na Jemami zaista dogodilo"},{"text":"postojao je i zapis nastao pred Poslanikom ﷺ. Ibn Hadžer je ukazao na to da je poglavlje kod Buharija postavljeno upravo kao odgovor onima koji su tvrdili da je deo Kur'ana izgubljen pogibijom njegovih nosilaca. Tvrdnja, dakle, nije nova; bila je poznata već u trećem veku po Hidžri i tada je odbačena. Ibn Hadžer el Askalani, Fethul bari.","headingId":"peto-sta-se-na-jemami-zaista-dogodilo","headingText":"Peto - šta se na Jemami zaista dogodilo"},{"text":"Poređenje sa biblijskim prenosom Vil Djurant je naveo da najstariji primerci Jevanđelja potiču iz trećeg veka, dok su izvornici pisani između 60. i 120. godine, i da su potom bili podložni greškama u prenošenju i namernim izmenama. Vil Djurant.","headingId":"poredjenje-sa-biblijskim-prenosom","headingText":"Poređenje sa biblijskim prenosom"}]}];
